window.__D("text/tikkunei-zohar/c006",{"p":[[9500011267,"<p>בְּעִינָא (יחזקאל א א) נִפְתְּחוּ הַשָּׁמַיִם וָאֶרְאֶה מַרְאוֹת אלהי\"ם, דְּאִינוּן חָמֵשׁ אוֹר דְּעוֹבָדָא דִבְּרֵאשִׁית, דִּכְלִילָן בְּה' עִלָּאָה, חָמֵשׁ אוֹר דְּנָהֲרִין בְּחָמֵשׁ גַּוָּונִין, שַׁבְּתַא\"י פַּתְיָא אוּכְמָא, כָל גַּוָּונִין אִתְחַשְׁכָאן בֵּיהּ, אִיהוּ גַוָּון גָּחוֹן דְּחִוְיָא, דְאִתְּמַר בֵּיהּ (בראשית ג יד) עַל גְּחוֹנְךָ תֵלֵךְ וְעָפָר תֹּאכַל כָּל יְמֵי חַיֶּיךָ, עָפָר אִיהוּ קַר וְיָבֵשׁ, הָכִי טְחוֹל קַר וְיָבֵשׁ, וּבְגִין דָּא וְעָפָר תֹּאכַל כָּל יְמֵי חַיֶּיךָ.</p>\n<p>תָּא חֲזִי לַאו לְמַגָּנָא אָמְרוּ קַדְמָאִין, אֵין הָרוֹכֵב טְפֵלָה לַסּוּס אֶלָּא הַסּוּס טְפֵלָה לָרוֹכֵב, דְּסוּס אִיהוּ נוּקְבָא, לָרוֹכֵב דְּאִיהוּ אָדָם, אִם זָכָה אִתְּמַר בֵּיהּ (שם ב יח) אֶעֱשֶׂה לּוֹ עִזֶר, וְאִם לַאו כְּנֶגְדּוֹ יֵצֶר הָרָע, עֲלֵיהּ אִתְּמַר (קהלת ז כו) וּמוֹצֵא אֲנִי מַר מִמָּוְת אֶת הָאִשָּׁה, וְדָא טְחוֹל שַׁבְּתַא\"י, עִזֶר דָּא שְׁכִינְתָּא, עֲלָהּ אִתְּמַר (משלי יח כב) מָצָא אִשָּׁה מָצָא טוֹב וַיָּפֶק רָצוֹן מֵיהו\"ה, וּבְגִין דָּא הֲווֹ אָמְרֵי מָארֵי מַתְנִיתִין, מָצָא אוֹ מוֹצֵא.</p>\n<p>לְזִמְנִין תִּשְׁכַּח סוּסְיָא דְאִתְגָּאֶה וְאַפִּיל לְרוֹכְבוֹ תְּחוֹתֵיהּ, דָּא אִתְּתָא בִּישָׁא, לְזִמְנִין תִּשְׁכַּח אָדָם רָכִיב עַל סוּסְיָא, לְזִמְנִין אִישׁ, לְזִמְנִין עִִבֶד, כְּגַוְונָא דָא תִשְׁכַּח לְזִמְנִין דְּאִית גּוּף דְּאִיהוּ סוּס שַׁפִּיר בְּכָל תִּקּוּנוֹי, וְעָבִיד עוֹבָדִין בִּישִׁין, בְּגִין דְּאִית לֵיהּ הַהוּא נֶפֶשׁ דְּרָכִיב עֲלֵיהּ, דְּאִיהוּ אָדָם רַע עִִבֶד או מַמְזֵר, וּבְגִין דָּא אוּקְמוּהוּ מָארֵי מַתְנִיתִין, לֹא הַמֶּדְרָשׁ עִקָּר אֶלָּא הַמַּעֲשֶׂה הוּא הָעִקָּר, וּלְזִמְנִין תִּשְׁכַּח סוּסְיָא בִּישָׁא דְאִיהוּ גוּפָא, דְאִית לֵיהּ דִּיּוֹקְנָא בִישָׁא, וּמָאן דְּרָכִיב עֲלֵיהּ אִיהוּ טַב, וְסָטֵי לֵיהּ לְמֶעֱבַד עוֹבָדִין טָבִין, וְדָא אִיהוּ מַטֶּה כְּלַפֵּי חֶסֶד, וּמָאן דְּאִית לֵיהּ דִּיּוֹקְנָא שַׁפִּירָא וְעוֹבָדִין טָבִין, דָּא צַדִּיק וְטוֹב לוֹ.</p>\n<p>וְהָכִי אִיהוּ מָאן דְּאִיהוּ צַדִּיק וּבַת זוּגֵיהּ צַדֶּקֶת, מָאן דְּאִיהוּ דִיּוֹקְנֵיהּ בִּישָׁא וְאִיהוּ שַׁפִּיר בְּעוֹבָדוֹי, דָּא צַדִּיק וְרַע לוֹ, וְהָכִי אִיהוּ מָאן דְּאִיהוּ צַדִּיק וּבַת זוּגֵיהּ בִּישָׁא, וּמָאן דְּאִיהוּ דִיּוֹקְנָא בִישָׁא וְעוֹבָדוֹי בִּישִׁין, דָּא אִיהוּ רָשָׁע וְרַע לוֹ, וְהָכִי אִיהוּ מָאן דְּאִיהוּ רַע וְאִתְּתֵיהּ רָעָה, הָכָא אִשְׁתְּמוֹדְעִין תְּלַת גִּלְגּוּלִין, רָשָׁע וְטוֹב לוֹ מָאן דְּעוֹבָדוֹי בִּישִׁין וְדִיּוֹקְנֵיהּ שַׁפִּירָא, וְאִתְּתֵיהּ צַדֶּקֶת שַׁפִּירְתָּא בְעוֹבָדָהָא.</p>\n<p>דְּגִלְגּוּלָא גָרִים דָּא לְמֶהֱוֵי בַּר נַשׁ צַדִּיק וְטוֹב לוֹ, צַדִּיק וְרַע לוֹ רָשָׁע וְטוֹב לוֹ רָשָׁע וְרַע לוֹ, דְּגוּפָא בִישָׁא וְאִתְּתָא בִּישָׁא לַצַּדִּיק אִיהוּ עוֹנָשָׁא דִילֵיהּ, דְּגִלְגּוּלָא מְחַיֵּיב לֵיהּ, אָמַר רַבִּי אֶלְעָזָר, אַבָּא, אִם כֵּן מַאי תַּקַּנְתֵּיהּ לְמָאן דְּאִיהוּ צַדִּיק וְאִית לֵיהּ אִתְּתָא בִּישָׁא, אָמַר לֵיהּ בְּרִי, יַעֲבִיד לֵיהּ שִׁנּוּי מָקוֹם וְשִׁנּוּי הַשֵּׁם וְשִׁנּוּי מַעֲשֶׂה, וְאִי לָא אִתְתַּקְנַת יְתָרֵךְ לָהּ מִנֵּיהּ בְּגֵט וְיִתְּסֵי, וְאִתְנַטַּע בַּאֲתַר אָחֳרָא (איוב לג כט), וְהֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר, עַד הָכָא בְּשִׁרְטוּטִין דִּיְדִין.</p>\n<p>בְּקוֹמָה בְּצַוָּאר, פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, אֵלִיָּהוּ אֵלִיָּהוּ, הָא שְׁכִינְתָּא הָכָא, וְכֻלְּהוּ חַבְרַיָּיא עִמָּהּ נָטְרִין לָךְ הָכָא, טוֹל רְשׁוּ מִקּוּדְשָׁא בְּרִיךְ הוּא לְנָחֲתָא הָכָא לִיקָרָא דְמַלְכָּא קַדִּישָׁא, אַנְתְּ וְכָל מָארֵי מְתִיבְתָּאן דִּלְעִילָא וְתַתָּא עִמָּךְ, לְתַקְנָא שִׁעוּר קוֹמָה דְקוּדְשָׁא בְּרִיךְ הוּא כִּדְקָא יָאוּת לֵיהּ, אַדְהָכִי הָא אֵלִיָּהוּ קָא נָחַת וְכָל מָארֵי מְתִיבְתָּאן דִּלְעִילָא וְתַתָּא עִמֵּיהּ, וְקוּדְשָׁא בְּרִיךְ הוּא עַל כֻּלְּהוּ.</p>\n<p>פָּתַח אֵלִיָּהוּ וְאָמַר, רִבּוֹן עָלְמָא יְהֵא רַעֲוָא דִילָךְ דְּאֵימָא מִלִּין בְּאֹרַח מִישׁוֹר כִּדְקָא יָאוּת, כֻּלְּהוּ בַּמִּדָּה בַּמִּשְׁקָל בְּשִׁעוּר קוֹמָה דִשְׁכִינְתָּךְ. פָּתַח וְאָמַר, (שיר ז ח) זֹאת קוֹמָתֵךְ דָּמְתָה לְתָמָר וְשָׁדַיִךְ לְאַשְׁכֹּלוֹת, מַאי לְתָמָר, אֶלָּא לְהַהוּא דְאִתְּמַר בֵּיהּ (תהלים צב יד) צַדִּיק כַּתָּמָר יִפְרָח, כַּפֹּת תְּמָרִים, קוֹמָתֵךְ וַדַּאי דַּמְיָא לְלוּלָב דְּלֵית בֵּיהּ קִצּוּץ וּפִרוּד, וְלַאו לְמַגָּנָא אוּקְמוּהוּ מָארֵי מַתְנִיתִין נִפְרְצוּ עַלָּיו פָּסוּל, לוּלָב אִיהוּ דוֹמֶה לְשִׁדְרָה דְּגוּפָא, דְאִיהוּ ו', קוֹמָה דְכֹלָּא, וְאִיהוּ שִׁית בְּחוּשְׁבַּן, וְחָמֵשׁ עַנְפִין מִתְפַּשְׁטִין מִנֵּיהּ, וְאִיהוּ גוּפָא</p>"],[9500011268,"<p>דְאִילָנָא בְּאֶמְצָעִיתָא, וְחָמֵשׁ עַנְפִין אִינוּן תְּרֵין מֵהַאי סִטְרָא, וּתְלַת מֵהַאי סִטְרָא, וַעֲלַיְיהוּ אִתְּמַר (ויקרא כג מ) וַעֲנַף עִץ עָבוֹת וְעַרְבֵי נָחַל, עֲנַף לִשְׂמָאלָא, עָבוֹת לִימִינָא, עִץ בְּאֶמְצָעִיתָא, עַרְבֵי נַחַל תְּרֵין, עָבוֹת תְּלַת, וְכֻלְּהוּ חָמֵשׁ, וְאִינוּן לָקֳבֵל תְּרֵין שׁוֹקִין וּבְרִית, וּתְרֵין דְּרוֹעִין, אֶתְרוֹג לֵב בְּאֶמְצָעִיתָא, עִקָּרָא דְאִילָנָא וְעַנְפּוֹי, וְאִיהוּ אִיבָּא דְאִילָנָא, וּבֵיהּ אִיהוּ עִץ פְּרִי עוֹשֶׂה פְּרִי לְמִינוֹ.</p>\n<p>צַוָּאר עַל כֻּלְּהוּ אִימָּא עִלָּאָה, מוֹחָא אַבָּא, וּבֵיהּ נְבִיעוּ דְאִילָנָא, דִּמְקוֹרָא דִילֵיהּ אִתְקְרֵי אֵין סוֹף, עַלִּין דְּאִילָנָא אִינוּן קְווּצוֹתָיו, עֲלַיְיהוּ אִתְּמַר (שיר ז ו) רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל, כֻּלְּהוּ יְרוֹקִין, דְּהָכִי צְרִיכָא שַׂעֲרָא דְאִתְּתָא דְאִיהִי בְרַתָּא דְמַלְכָּא לְמֶהֱוִי יָרוֹק כְּשִׁבְעָה מִינֵי דַהֲבָא, וְאֶתְרוֹג אִיהִי יְרוֹקָא, וְאֶסְתֵּר מִתַּמָּן הֲוַת יְרַקְרוֹקֶת.</p>\n<p>שִׁעוּרָא דִרְצוּעִין דִּתְּפִלִּין אִינוּן עַד לִבָּא, וְהָכִי שִׁעֲרוּ לוֹן מָארֵי מַתְנִיתִין, וְהָכִי שִׁעוּרָא דְשַׂעֲרָא דִבְרַתָּא דְמַלְכָּא עַד לִבָּא, וְכָל עַנְפָא וְעַנְפָא דְאִילָנָא דִילָהּ, דְּאִינוּן קְנֵי מְנוֹרָה, כֻּלְּהוּ צְרִיכִין בַּמִּדָּה וּבַמִּשְׁקָל וּבַמִּדָּה חֲדָא, דְּלָא יְהֵא דְרוֹעָא חֲדָא אֲרִיךְ מֵחַבְרֵיהּ, וְלָא שׁוֹקָא חֲדָא אֲרִיךְ מֵחַבְרֵיהּ, אֶלָּא כֻלְּהוּ בַּמִּדָּה בַמִּשְׁקָל דָּא בְדָא, וְהָכִי עַיְינִין דִּילֵיהּ שְׁקִילִין דָּא לְדָא, וְהָכִי אוּדְנִין, וְהָכִי נוּקְבָא דְחוֹטָמָא דִילָהּ, וְהָכִי אַנְפִּין דִּילָהּ, וְהָכִי שִׂפְוָון דִּילָהּ, דְּלָא יְהֵא חַד אֲרִיךְ וְחַד קְצִיר, אֶלָּא כֻּלְּהוּ בְשִׁקּוּלָא חֲדָא.</p>\n<p>מַבּוּעָא דְמַיָּא הָכִי צָרִיךְ לְאַשְׁקָאָה וּלְדַכָּאָה לְכָל גּוּפָא, וְכֹלָּא אִצְטְרִיךְ בַּמִּדָּה וּבַמִּשְׁקָל כְּמַבּוּעָא דְמַיָּא, וּלְכָל אֵבֶר וְאֵבֶר דְּאִיהוּ עַנְפָא דְאִילָנָא, בַּמִּדָּה וּבַמִּשְׁקָל, וְסִימָנָא (ישעיה מ מ) מִי מָדַד בְּשָׁעֳלוֹ מַיִם, וְשָׁמַיִם בַּזֶּרֶת תִּכֵּן (איוב כח כה), וּמַיִם תִּכֵּן בְּמִדָּה, מִי וַדַּאי, מִדָּה דִנְבִיעוּ כְּגַוְונָא דָא ם, מֵם בְּרִיבּוּעָא, נְקוּדָה בְעִגּוּלָא, (מרובעת) בְּרִבּוּעָא.</p>\n<p>וְרָזָא דְמִקְוְה אַרְבָּעִים סְאָה כְּגַוְונָא דָא תֵּשַׁע נְקוּדִין לְכָל סְטַר, וּבַנְּקוּדָה דְמִלְּגָאו בָּהּ אִשְׁתַּלִּימוּ לְעִִשֶׂר כָּל תִּשְׁעָה, עַד דְּאִתְעֲבִידוּ אַרְבְּעִין, וְאִלֵּין אִינוּן אַרְבְּעִים סְאָה, וְאִינוּן ם' עִלָּאָה, מ' תַּתָּאָה, דָּא בְּרִבּוּעָא וְדָא בְּעִגּוּלָא, י' נְבִיעוּ דְתַרְוַיְהוּ, וְרָזָא דָא מַיִם חַיִּים.</p>\n<p>וְאִית עַנְפִין עִלָּאִין, וְעַנְפִין בֵּינוּנִיִּים, וְעַנְפִין תַּתָּאִין, וְכֻלְּהוּ בַמִּדָּה בַּמִּשְׁקָל, עִלָּאִין בַּמִּשְׁקָל דָּא בְדָא, בֵּינוּנִיִּים בַּמִּשְׁקָל דָּא בְדָא, תַּתָּאִין בַּמִּשְׁקָל דָּא בְדָא, עִלָּאִין אִינוּן אֲבָהָן, בֵּינוּנִיִּים מְמַנָּן, וְתַתָּאִין שְׁלִיחָן דִּלְהוֹן, וְכֻלְּהוּ אִית לוֹן שְׁמָהָן יְדִיעָאן, לְאִשְׁתְּמוֹדְעָאן שְׁלִיחָאן וְרָאשִׁין וּמְמַנָּן דִּתְחוֹתַיְיהוּ, וְכָל חַד אִית לֵיהּ נְקוּדָה, וּבֵיהּ אִשְׁתְּמוֹדָע כָּל עַנְפָא וְעַנְפָא דְאִיהוּ אֵבֶר דְּגוּפָא.</p>\n<p>רָאשִׁין יהו\"ה מֶלֶךְ יהו\"ה מָלָךְ יהו\"ה יִמְלֹךְ, נְקוּדָה דִלְהוֹן יֶהוְה מֶלֶךְ יַהוַה מַלַךְ יִהוֹהְ יִמְלֹךְ, וְהָכִי אִינוּן לְתַתָּא בִתְרֵין שׁוֹקִין וְאָמָה, וּבְגִין דָּא כָפַל לוֹן תְּרֵין זִמְנִין יהו\"ה מֶלֶךְ יהו\"ה מָלָךְ יהו\"ה יִמְלֹךְ, לְעוֹלָם וָעִִד שְׁכִינְתָּא, וּנְקוּדָה דִילָהּ יהו\"ה, וְדָא רָזָא (תהלים צא יא) כִּ\"י בִ\"י חָשַׁ\"ק וַאֲפַלְּטֵהוּ, דְרָאשֵׁי רָאשִׁין (תיבין) דְּאִינוּן כֶּתֶר עִלָּאָה חָכְמָה בִּינָה, (זכריה יד ט) וְהָיָ\"ה יהו\"ה לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יהו\"ה אֶחָד וּשְׁמוֹ אֶחָד, וְהָיָה יהו\"ה אַבָּא וְאִמָּא, יִהְיֶה יהו\"ה אֶחָד וּשְׁמוֹ אֶחָד כֶּתֶר עִלָּאָה.</p>\n<p>יְדִין אִינוּן מְשַׁמְּשִׁין דְּגוּפָא, רַגְלִין שְׁלִיחָן דְּגוּפָא, וַעֲלַיְיהוּ אִתְּמַר (תהלים קד ד) עוֹשֶׂה מַלְאָכָיו רוּחוֹת, מְשָׁרְתָיו אֵשׁ לוֹהֵט, וּמְשַׁמְּשִׁין דְּגוּפָא תְּרֵין דְּרוֹעִין, אִינוּן ע\"ב עַנְפִין דְּוַיִּסַּע וַיָּבֹא וַיֵּט, אִלֵּין אִינוּן עַנְפֵי דְאִילָנָא, שָׁרְשָׁא דְאִילָנָא אִינוּן שְׁלִיחָן, וְאִינוּן שַׁבְעִין וּתְרֵין ע\"ב עִלָּאִין לָקֳבֵל שַׁבְעִין וּתְרֵין תֵּיבִין, דְּאִינוּן מִן וְהָיָה</p>"],[9500011269,"<p>אִם שָׁמֹעַ עַד וְשַׂמְתֶּם, וְשִׁבְעִים וּתְרֵין אָחֳרָנִין אִינוּן דְּפָרָשַׁת צִיצִית, רֵישָׁא דְאִילָנָא, מְשַׁמְּשִׁין דִּילֵיהּ דְּאִינוּן שׁוֹפְטִים וְשׁוֹטְרִים, אִינוּן מ\"ב תֵּיבִין מִן וְאָהַבְתָּ עַד וְהָיָה, גּוּפָא (נ\"א נופא) דְאִילָנָא מְמַנָּן וּשְׁלִיחָאן דִּילֵיהּ, חַמְשִׁין תֵּיבִין דְּאִינוּן מִן וְשַׂמְתֶּם אֶת עַד וַיֹּאמֶר.</p>\n<p>שִׁבְעָה שְׁמָהָן דְּרֵישָׁא דְסָלְקִין לְמ\"ב, אִינוּן אְבָגְיֶתֵץ וכו', רְקִיעָא קַדְמָאָה אבגית\"ץ, וּנְקוּדָה דִילֵיהּ יְהָוֶהֵ, דְּנָפְקִין מֵאִלֵּין רָאשֵׁי תֵּיבִין בְּרֵאשִׁית בָּרָא אֱלהי\"ם אֵת, וְאִית תַּמָּן תְּמַנְיָא מַבּוּעִין, דְּנָפְקִין מִצִּנּוֹרָא חֲדָא, דְאִיהוּ רָקִיעַ, וְאִינוּן תְּמַנְיָא נִצּוֹצִין, וְרָקִיעַ תִּנְיָינָא קַרְעִִ שְטָן, וּנְקוּדָה דִלְהוֹן וַיֹּאמֶר אֱלהי\"ם יְהִי רָקִיעַ וְדָא יַהֱוְ\"הָ, תְּלִיתָאָה נַגְדֶיִכַש נְקוּדָה דִילֵיהּ וַיּאמֶר אֱלהי\"ם יִקָּווּ הַמַּיִם, וְדָא יַהֱוִ\"הַ, רְבִיעָאָה בַטְ\"רָ צְתְ\"ג, נְקוּדָה דִילֵיהּ וַיֹּאמֶר אֱלהי\"ם יְהִי מְאֹרֹת, וְדָא יַהוְ\"הְ, חֲמִשָּׁאָה חַקְ\"בֶ טִנַ\"ע, וּנְקוּדָה דִילֵיהּ וַיֹּאמֶר אֱלהי\"ם יִשְׁרְצוּ הַמַּיִם, וְדָא יַהֱוִ\"הַ, שְׁתִיתָאָה יַגְלֶ פֹזָק, נְקוּדָה דִילֵיהּ וַיֹּאמֶר אֱלהי\"ם תּוֹצֵא הָאָרֶץ, וְדָא נְקוּדָה יַהֱוֹהָ, שַׁקְ\"וְ צִיָ\"ת, דָא נְקוּדָה שְׁבִיעָאָה כָּלִיל בְּיוֹמָא שְׁתִיתָאָה, וַיֹּאמֶר אֱלהי\"ם הִנֵּה נָתַתִּי, וְדָא יַהֱוִ\"הָ.</p>\n<p>תָּא חֲזִי אִית שְׁמָהָן דְּאוֹרַיְיתָא דְנָפְקִין מֵרֵישֵׁי תֵּיבִין דְּכָל פְּסוּקָא וּפְסוּקָא דְאוֹרַיְיתָא, וְאִית שְׁמָהָן דְּנָפְקִין מִסּוֹף תֵּיבִין, וְאִית דְּנָפְקִין מֵאֶמְצָעִיתָא, וְרָזָא דְמִלָּה (נ\"א דכלא) (ישעיה מד ו) אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן וּמִבַּלְעָדַי אֵין אלהי\"ם, וְאִית שְׁמָהָן דְּנָפְקִין מִתְּרֵין אַתְוָון כָּל חַד וְחַד, וְאִית מִתְּלַת תְּלַת, וְאִית מֵאַרְבַּע, וְאִית מֵחָמֵשׁ, עַד עֲשָׂרָה, אִינוּן מֵעֲשַׂר סְפִירָאן תַּלְיָין, מִתְּרֵין עֲשַׂר אִינוּן תַּלְיָין מִכֶּתֶר עִלָּאָה, כְּגוֹן יואאחצ\"צבירון, בְּהַאי שְׁמָא תַּמָּן אָח, תַּמָּן צִיץ, תַּמָּן אַבִּיר, תַּמָּן יָרוֹן, דָּא שְׁמָא דְתַלְיָא מִכִּתְרָא עִלָּאָה, כָּל שְׁמָא דְאִיהוּ מִתְּרֵין עֲשַׂר אַתְוָון, אִיהוּ בְּרָזָא דְאַלֶּ\"ף, דְּאִיהוּ פֶּלֶ\"א, וַעֲלֵיהּ אִתְּמַר (תהלים קלט יד) אוֹדְךָ עַל כִּי נוֹרָאוֹת נִפְלֵאתִי נִפְלָאִים מַעֲשֶׂיךָ, וּתְרֵין עֲשַׂר שְׁמָהָן אִנּוּן אחצצביההירו\"ן, (ס\"א יואחציצבירו\"ן), (ס\"א אהצצביהרירו\"ן), (נ\"א אהה נצב הרירו\"ן), כָּל חַד מִתְּרֵין עֲשַׂר אַתְוָון, וְאִינוּן מְמַנָּן עַל תְּרֵין עֲשַׂר צִנּוֹרִין, דְּנָפְקִין מִמְּקוֹר עִלָּאָה דְלֵית לֵיהּ סוֹף, וְאִינוּן מִסִּטְרָא דַאֲרִיךְ אַנְפִּין דְּאִיהוּ וָא\"ו, וְאִינוּן הֵ\"א הֵ\"א, יוּ\"ד אִיהוּ כ' כֶּתֶר בְּרֵישָׁא דְא' (נ\"א דא) דְּאִיהוּ אֶרֶךְ אַפַּיִם, דְּאִיהוּ וָא\"ו, א' אִיהִי אוֹרַיְיתָא, דְאִיהִי אִתְיְיהִיבַת בִּתְרֵין לוּחִין דְּאִינוּן ו' ו', וְאִית כִּתְרָא דִזְעִיר אַנְפִּין דְּאִתְּמַר בֵּיהּ (איוב לו ב) כַּתַּר לִי זְעִיר וַאֲחַוְּךָּ, וְכַמָּה כִּתְרִין אִינוּן, כֶּתֶר תּוֹרָה וְכֶתֶר כְּהוּנָה וְכֶתֶר מַלְכוּת.</p>\n<p>מַאי אִית בֵּין כֶּתֶר לַעֲטֶרֶת, אֶלָּא כֶתֶר אִיהוּ מִסִּטְרָא דְא', דְּאִיהוּ בְדִיּוֹקְנָא דְאָת יוּ\"ד, דְּסָלִיק כ', וְדָא א' מִן אהי\"ה, דְּאִיהוּ כֶּתֶר דַּאֲרִיךְ אַנְפִּין, א' מִן אדנ\"י כֶּתֶר דִּזְעִיר אַנְפִּין, י' מִן יהו\"ה אִיהִי עֲטָרָה עַל סֵפֶר תּוֹרָה דְאִיהוּ ו', וְאִית י' לְתַתָּא וְאִיהִי י' מִן אדנ\"י, דְּאִיהִי עֲטָרָה בְרֵישָׁא דְכָל צַדִּיק, לֵית סְפִירָה דְלָא אִית לָהּ עֲטָרָה עַל רֵישָׁא וְכֶתֶר, וַעֲטָרָה דְאִיהִי י' אִיהִי עֲטָרָה דִבְרִית מִילָה, דְסָלִיק לְמֵאָה, עִִשֶׂר זִמְנִין עִִשֶׂר מֵאָה, וְאִיהִי עַל כָּל פִּקּוּדָא וּפִקּוּדָא, וְכַמָּה עִלּוֹת אִינוּן עַל עִלּוֹת דְּסָלְקִין עַל כָּל בִּרְכָאָן וּפִקּוּדִין.</p>\n<p>וְכָל סְפִירָן סָלְקִין כָּל חַד וְחַד לְמֵאָה בְּאָת י', וּבְאָת א' סָלְקִין לַעֲשֶׂרֶת אֲלָפִים, וְאִית לְעִילָא מִנַּיְיהוּ הַהוּא דְאִתְקְרֵי עִלַּת עַל כָּל הָעִלּוֹת, דְּסָלִיק עַל כָּל עִלָּאִין, וְלֵית מָאן דְּסָלִיק עֲלֵיהּ, וְכַמָּה אַתְוָון אִית בְּאוֹרַיְיתָא מְעוּטָּרִים וּמְכוּתָּרִים, וּמֵאִלֵּין עִלָּאִין נָחֲתִין בִּרְכָאָן וּמַבּוּעִין לְכָל סְפִירָה וּסְפִירָה</p>"],[9500011270,"<p>דְּאִינוּן י\"א, עַל כָּל סְפִירָה וּסְפִירָה, וְאִינוּן י\"א י\"א מִן (דברים ו ד) יְ הוָֹה אֱ לֹהֵינוּ יְ הוָֹה אֶ חָד, בְּא' אִתְקְרֵי אֵ\"ל עִִלְיוֹן, בְּי' יהו\"ה, וְכֵן בְּא' אִתְקְרֵי אלהינ\"ו אהי\"ה אלהי\"ם אדנ\"י וְהָא אוּקְמוּהָ. וְעוֹד כֶּתֶר עִלָּאָה אַף עַל גַּב דְּאִיהוּ אוֹר קַדְמוֹן אוֹר צַח וְאוֹר מְצוּחְצָח, אִיהוּ אוּכַם קֳדָם עִלַּת הָעִלּוֹת, וְכָל חֲיָילִין דְּתַלְיָין מִנֵּיהּ אִתְּמַר בְּהוֹן (שיר ה יא) קְווּצּוֹתָיו תַּלְתַּלִּים שְׁחוֹרוֹת כָּעוֹרֵב, לֵית נְהוֹרָא קַיְימָא קַמֵּי נְהוֹרֵיהּ, דְּכֻלְּהוּ נְהוֹרִין אִתְחַשְׁכָאן קַמֵּיהּ.</p>\n<p>תָּא חֲזִי כַּמָּה עִלּוֹת סְתִימִין, דְּאִינוּן מִתְלַבְּשִׁין וְאִינוּן מוּרְכָּבִין בִּסְפִירָן, וּסְפִירָן מֶרְכָּבָה לְגַבַּיְיהוּ, דְאִינוּן טְמִירִין מִמַּחְשְׁבוֹת בְּנֵי אָדָם, וַעֲלַיְיהוּ אִתְּמַר (קהלת ח ח) כִּי גָבֹהַּ מֵעַל גָּבֹהַּ שֹׁמֵר וּגְבֹהִים עֲלֵיהֶם, נְהוֹרִין מְצוּחְצָחִין אִלֵּין עַל אִלֵּין, וְאִלֵּין דִּמְקַבְּלִין אִינוּן כַּחֲשׁוֹכִין מֵאָחֳרָנִין דַּעֲלַיְיהוּ דִּמְקַבְּלִין מִנַּיְיהוּ, וְעִלַּת עַל כָּל הָעִלּוֹת, לֵית נְהוֹרָא קַיְימָא קַמֵּיהּ, כָּל נְהוֹרִין מְצוּחְצָחִין מִתְחַשְׁכָאן קַמֵּיהּ.</p>\n<p>וְכָל נְהוֹרִין דְּאִינוּן לְעִילָא מִנְּהוֹרִין אִינוּן כִּתְרִין עַל רֵישַׁיְיהוּ, וְרָזָא דְמִלָּה אל\"ף ה\"א יו\"ד ה\"א, דָא רָזָא דַעֲשָׂרָה כִּתְרִין דְּאִינוּן מוּרְכָּבִין עַל עֲשַׂר סְפִירָן, וְדָא אִיהוּ כִּי גָבֹהַּ מֵעַל גָּבֹהַּ שֹׁמֵר, וּגְבֹהִים עֲלֵיהֶם יו\"ד ה\"א וא\"ו ה\"א, יו\"ד ה\"י וא\"ו ה\"י, אִלֵּין עַל אִלֵּין, עִִשֶׂר נְהוֹרִין בְּעִִשֶׂר, הֲדָא הוּא דִכְתִיב (במדבר ז׳:פ״ו) עֲשָׂרָה עֲשָׂרָה הַכַּף בְּשֶׁקֶל הַקֹּדֶשׁ, לְעִילָא עַל כֻּלְּהוּ עִלַּת הָעִלּוֹת דְּרָכִיב עַל כֹּלָּא וְשַׁלִּיט עַל כֹּלָּא, וְכֻלְּהוּ שְׁמָהָן אִינוּן מֶרְכָּבָה דִילֵיהּ, וְלֵית דְּרָכִיב עֲלֵיהּ, דְּלֵית לְעִילָא מִנֵּיהּ, וּבְגִין דָּא אִתְקְרֵי עִלַּת עַל כָּל עִלָּאִין.</p>\n<p>וּשְׁמָהָן אִלֵּין אִינוּן צִנּוֹרִין, וּשְׁמָהָן דַּעֲלַיְיהוּ מָבוּעִין דְּנָחֲתִין לְצִנּוֹרִין, וְכָל צִנּוֹרִין אִינוּן כְּאֵבָרִין דְּשִׁעוּר קוֹמָה, דְאָזְלִין בְּשִׁעוּר וּבַמִּדָּה וּבְתִקְלָא, הֲדָא הוּא דִכְתִיב (איוב כח כה) וּמַיִם תִּכֵּן בְּמִדָּה, וְהָא אוּקְמוּהָ כָּל חַד אִיהוּ מְקַבֵּל כְּפִי שִׁעוּרֵיהּ, וּכְפִי מִדָּה דִילֵיהּ, וְאִית נְבִיעוּ לְעִילָא דְלֵית לֵיהּ מִדָּה וְשִׁעוּר וּמִשְׁקָל, וְהָא אוּקְמוּהָ, (ויקרא יט לה) לֹא תַעֲשׂוּ עָוֶל בַּמִּשְׁפָּט בַּמִּדָּה בַּמִּשְׁקָל וּבַמְּשׂוּרָה, בַּמִּדָּה בְּחָמֵשׁ תִּקּוּנִין דְּה' עִלָּאָה, בַּמִּשְׁקָל דָּא ו', בַּמְּשׂוּרָה דָא ה', מִשְׁפָּט דְּכֹלָּא דָא י', הֲדָא הוּא דִכְתִיב (ישעיה ה טז) וַיִּגְבַּהּ יהו\"ה צְבָאוֹ\"ת בַּמִּשְׁפָּט, דְּאִיהוּ גָבֹהַּ מֵעַל גָּבֹהַּ שֹׁמֵר.</p>\n<p>חָמֵשׁ זִמְנִין כְּגַוְונָא דָא אִאֻאֵאֹאָ וְסִימָנָךְ (שמות כח יח) פִּתּוּחֵי חוֹתָם. אָמַר לֵיהּ רַבִּי אֶלְעָזָר, וְהָא הָכָא שׁוּרֵ\"ק בִּנְקוּדָה חֲדָא בְּפִּתּוּחֵי חוֹתָם, וְהָכָא בִתְלַת נְקוּדִין בְּאַתְרֵיהּ, אָמַר לֵיהּ, בַּאֲתַר דְּאִית ו' אִיהוּ שׁוּרֵ\"ק בִּנְקוּדָה חֲדָא, בַאֲתַר דְּלֵית ו' אִיהוּ שׁוּרֵ\"ק בִּתְלַת נְקוּדִין בְּאַתְרֵיהּ, עִלָּאָה וְאֶמְצָעִיתָא וְתַתָּאָה.</p>\n<p>חָמֵשׁ נְקוּדִין אִינוּן אלהי\"ם, כְּגַוְונָא דָא אִאֻאֵאֹאָ, תְּמַנְיָא נִצּוֹצִין אִינוּן תְּמַנְיָא יוּדִי\"ן דְּסָלְקִין תְּמַנִין, רָקִיעַ דְּאִיהוּ דִיּוֹקְנָא דְו' דְּאִיהוּ רְמִיזָא בְקָמֵ\"ץ, הָא פ\"ו כְּחֻשְׁבַּן אלהי\"ם, וְאִלֵּין נְקוּדִין עֲלַיְיהוּ אִתְּמַר פִּתּוּחֵי חוֹתָם, פִּתּוּחֵי דְאִימָּא עִלָּאָה, דְּאִיהִי חוֹתָם, כֻּלְּהוּן פִּתּוּחִין בָּהּ וְכֻלְּהוּ מְצוּיָירִין בָּהּ וּמִתְגַּלְּפָאן בָּהּ, וְאִיהִי חוֹתָם דְּכֻלְּהוּ, תֵּשַׁע נְקוּדִין אִינוּן גְּלִיפִין בָּהּ, תְּמַנְיָא נִיצוֹצוֹת וְרָקִיעַ, וְאִיהוּ עֲשִׂירִית לוֹן, תֵּשַׁע נְקוּדִין עַד צַדִּיק, וְאִיהִי חוֹתָם דְּכֻלְּהוֹן, כְּמָה דְאַתְּ אָמַר וְצֶאֱצָאָיו חָתַם בְּאוֹת בְּרִית קֹדֶשׁ, וְהַנֵּי אִינוּן תֵּשַׁע מִתַּתָּא לְעִילָא, וְאִימָּא עִלָּאָה חוֹתָם דְּכֻלְּהוּ, כֶּתֶר עַל כֻּלְּהוּ, וּבָהּ נַהֲרִין כְּמַרְגְּלָאן דְּנַהֲרִין בְּכִתְרָא.</p>\n<p>וּמִסִּטְרָא דְאִלֵּין נְקוּדִין אִתְקְרִיאַת שְׁכִינְתָּא שִׂיחָה דְכֹלָּא, שִׂיחָה דְמַלְאֲכֵי הַשָּׁרֵת, שִׂיחַת דְּקָלִים, שִׂיחַת הָרוּחוֹת, שִׂיחַת עוֹפִין, שִׂיחַת כָּל בִּרְיָין דְּעָלְמָא, אלהי\"ם בְּלָא נְקוּדִין אִתְקְרֵי אִלֵּם, וְדָא רָזָא דְמִלָּה (שם ד יא) אוֹ מִי יָשׂוּם אִלֵּם, אוֹ מִי, מִ\"י וַדַּאי, אִימָּא עִלָּאָה, מָאן שַׁוִּי אִלֵּם לְאִימָּא עִלָּאָה, עִלַּת הָעִלּוֹת דְּחֵילָא דְכֹלָּא בִידֵיהּ.</p>\n<p>דָּבָר</p>"],[9500011271,"<p>אַחֵר זֶה סֵפֶר תּוֹלְדוֹת אָדָם, זֶה סֵפֶר, דְּהָא כַמָּה סִפְרִין אִינוּן, סִפְרָא דְרַב הַמְנוּנָא סָבָא, סִפְרָא דַחֲנוֹךְ, סִפְרָא דְרַבִּי כְּרוּסְפְּדָאי, תָּא חֲזִי, יוֹמָא חַד אַעִִרַעִִנָא בַאֲתַר דְּרַבִּי כְּרוּסְפְּדָאי, אֲנָא וְחַבְרַיָּיא, וְתַקִּינַת לָן אִמֵּיהּ דְּרַבִּי כְּרוּסְפְּדָאי מְנַרְתָּא בְּשִׁבְעָה בּוֹצִינִין, וְאַפֵּקַת סִפְרָא דְרַבִּי כְּרוּסְפְּדָאי, כִּי הֲווֹ קָרָאן בְּסִפְרָא דָא הָכִי הֲווֹ נָחֲתִין חַיָּילָא דְמַלְאָכַיָּא לְסַחֲרָא לוֹן, כִּבְנֵי נָשָׁא דְמִתְקַבְּצִין לְחוּפָּה בְּמַזְמוּטֵי חָתָן וְכַלָּה, וְקוּדְשָׁא בְּרִיךְ הוּא הֲוָה נָחִית בְּכָל מַשִּׁרְיָין דִּילֵיהּ, לְמִשְׁמַע מִלִּין מֵהַהוּא סִפְרָא, וַאֲבוֹי דְרַבִּי כְּרוּסְפְּדָאי הֲוָה נָחִית לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא עִמֵּיהּ, לְמִשְׁמַע מִלִּין דִּבְרֵיהּ רַבִּי כְּרוּסְפְּדָאי, וְלֵילְיָא דָא לֵיל דְּשָׁבוּעוֹת הֲוָה, וְהָכִי הֲוָה חָדֵי קוּדְשָׁא בְּרִיךְ הוּא בְּאִלֵּין מִלִּין כְּיוֹמָא דְאִתְיְיהִיבַת אוֹרַיְיתָא בְטוּרָא דְסִינַי.</p>\n<p>לֵילְיָא חֲדָא אִזְדַּמַּן לָן לְמֶהֱוֵי אוֹשְׁפִּיזִין בְּבֵית אִמֵּיהּ דְּרַבִּי כְּרוּסְפְּדָאי, וְתַקִּינַת לָן פָּתוֹרָא וּמְנַרְתָּא, וַהֲוָה רַבִּי כְּרוּסְפְּדָאי אִתְכַּנַּשׁ לְהַהוּא עָלְמָא, אָמְרַת אִמֵּיהּ רַבָּנָן, וְהָא לָא הֲוִיתוּן שַׁרְיָין לְפָתוֹרָא דָא בְלָא אוֹרַיְיתָא, מַאי אִשְׁתַּנִּי זִמְנָא דָא מִשְּׁאָר זִמְנִין, אֲמֵינָא לְחַבְרַיָּא נִפְתַּח בְּמִילֵי דְאוֹרַיְיתָא, דְלָא יֵיתֵי תַּקָּלָה לְהַאי עַנְיָא עַל יְדָנָא, דְּאִם יָדְעַת דִּבְרָהּ אִיהוּ מֵת, יֵיתֵי תַּקָּלָה עַל יְדָנָא וְתָמוּת קֳדָם זִמְנָהּ, אֶפְתַּח בְּאוֹרַיְיתָא.</p>\n<p>פָּתַח וְאָמַר, בְּרֵאשִׁית בָּרָא אלהי\"ם דָּא נִשְׁמָתָא, כַּד נָפִיק מִמְּעִי אִמֵּיהּ אִתְּמַר בָּהּ (בראשית א ב) וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם, דְּנָפִיק עִינוֹי סְתִימִין, אַפְתַּח עִינוֹי מִיָּד (שם ג) וַיֹּאמֶר אלהי\"ם יְהִי אוֹר וַיְהִי אוֹר, בָּתַר דְּאִתְכַּנִּישׁ מֵהַאי עָלְמָא נִשְׁמָתֵיהּ, מַה כְּתִיב בֵּיהּ (שם א ט) וַיֹּאמֶר אלהי\"ם יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד וְתֵרָאֶה הַיַּבָּשָׁה, כֵּיוָן דְּאִסְתַּלְקַת נִשְׁמָתָא מִנֵּיהּ גּוּפָא אִשְׁתָּאֳרַת</p>"],[9500011272,"<p>יְבֵשָׁה, אָמְרַת לוֹן, רַבָּנָן, מִלִּין אִלֵּין לַאו אִינוּן אֶלָּא מֵהַהוּא עָלְמָא, אָזְלַת לְהַהוּא שְׁרַגָּא דַהֲוָה לָהּ סִימָנָא בֵּיהּ, דְּכַד רַבִּי כְּרוּסְפְּדָאי הֲוָה חַי הֲוָה שְׁרַגָּא מִתְנַעִִנְעָא וְנַהֲרָא בְּכַמָּה נְהוֹרִין מְרַקְמָן, חֲזִתָּהּ לִנְהוֹרָא דְאִתְחַשְׁכַת, מִיָּד אָמְרַת, רַבָּנָן רַבָּנָן, אֲבֵדָה קָא אִתְאֲבִידַת לִי, וַאֲנָא בָּעִינָא לְמֵיזַל לְפַשְׁפְּשָׁא בְגִינָהּ, אָמְרוּ וַדַּאי הָא אִשְׁתְּמוֹדְעַאת לָהּ, אֲזַלוּ לְאָרְחַיְיהוּ, וְאִיהִי נָפְקַת לְפָרָשַׁת אוֹרְחִין, וְאַשְׁכַּחַת יוֹנָה נוּקְבָא, אָמְרַת לָהּ יוֹנָה יוֹנָה אַנְתְּ דַּהֲוַת שְׁלִיחָא מְהֵימְנָא לְמָארָךְ, הֲדָא הוּא דִכְתִיב (שם ח ח) וַיְשַׁלַּח אֶת הַיּוֹנָה מֵאִתּוֹ, וְאִתְּמַר בָּךְ (שם יא) וַתָּשָׁב אֵלָיו הַיּוֹנָה לְעִת עִִרֶב, תָּבַת לֵיהּ בִּשְׁלִיחוּתָהּ, בְּאוֹמָאָה עֲלָךְ בְּהַהִיא יוֹנָה קַדִּישָׁא, דְתֵיזִיל בִּשְׁלִיחוּת דִּילִי, וְתֵדַע אִי בְּרִי חַי אוֹ מֵת, מִיָּד לְעִידָּן רַמְשָׁא חָזְרָה בִּשְׁלִיחוּתָהּ, דְּהָכִי חָזְרַת לְנֹחַ לְעִת עִִרֶב, הֲדָא הוּא דִכְתִיב וַתָּבֹא אֵלָיו הַיּוֹנָה לְעִת עִִרֶב, וַהֲוַת מְמַרְטַת גַּדְפָהָא, וְחָפְרַת כּוּכָא, מִיָּד יְהִבַת קָלָא וְאִתְכַּנְשַׁת לְהַהוּא עָלְמָא.</p>\n<p>לְבָתַר דַּהֲווֹ אָזְלִין בְּאָרְחָא רַבִּי שִׁמְעוֹן וְחַבְרוֹי, שְׁאִילוּ לֵיהּ, אַמַּאי כַּד נָפִיק יְנוּקָא מִמְּעִי אִמֵּיהּ אִיהוּ עִינוֹי סְתִימִין, אָמַר לון וַדַּאי דָּא אִיהוּ רָזָא (שם כז א) וַתִּכְהֶןָ עִינָיו מֵרְאוֹת, בְּאִלֵּין מַרְאוֹת דְּאַחְזִיאוּ לֵיהּ בִּמְעִי אִמֵּיהּ כַּמָּה נְהוֹרִין, כְּמָה דְחָמָא יְחֶזְקֵאל בְּמֶרְכָּבָה, לְכָל יְנוּקָא אַחְזְיָין לֵיהּ כְּפוּם דַּרְגֵּיהּ, אַחְזְיָין לֵיהּ מֵאֲתַר דְּאִיהוּ נִשְׁמָתֵיהּ, דְּאִי יִשְׁתַּדַּל בְּאוֹרַיְיתָא וּבְפִקּוּדִין, דְּיַנְהִיר הַהוּא אֲתַר דְּאִתְנְטִילַת נִשְׁמָתֵיהּ, בְּכַמָּה נִשְׁמָתִין.</p>\n<p>וְאֵיךְ נָחֲתִין בְּגִינֵיהּ כַּמָּה מֶרְכָּבוֹת, וְאוֹלְפִין לֵיהּ כָּל אוֹרַיְיתָא, וְאִי אִשְׁתַּדַּל בָּהּ אַדְכִּיר לֵיהּ כָּל מַה דַּהֲווֹ אוֹלְפִין לֵיהּ בִּמְעִי אִמֵּיהּ, לְבָתַר אַחְזְיָין לֵיהּ גֵּיהִנָּם, דְּאִם עָבַר עַל פִּקּוּדֵי אוֹרַיְיתָא מַהוּ עוֹנְשָׁא דִילֵיהּ, כְּמָה דְאַחְזִיאוּ לֵיהּ אַגְרֵיהּ, לְבָתַר דְּנָפִיק מִמְּעִי אִמֵּיהּ סָתִים</p>"],[9500011273,"<p>עִינוֹי מִכָּל אִינוּן נְהוֹרִין, כְּמָה דְאִתְּמַר וַתִּכְהֶןָ עִינָיו מֵרְאוֹת, וְאִלֵּין תֹּה\"וּ וָבֹה\"וּ, הֲדָא הוּא דִכְתִיב וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ וְחֹשֶׁךְ וכו', וְהָכִי אִיהוּ מָאן דְּלָא אִשְׁתַּדַּל בְּאוֹרַיְיתָא, עִינוֹי סָתִים מֵעָלְמָא דְאָתֵי, בָּתַר דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא, מִיָּד וַיֹּאמֶר אלהי\"ם יְהִי אוֹר וַיְהִי אוֹר, דְּנַהֲרִין לֵיהּ בִּנְהוֹרָא דְהַהוּא עָלְמָא, מִיָּד דְּאָזִיל לְהַהוּא עָלְמָא, מִיָּד יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד, אִתְכַּנְשַׁת נִשְׁמָתָא לַאֲתַר חַד, הֲדָא הוּא דִכְתִיב (קהלת יב ז) וְהָרוּחַ תָּשׁוּב אֶל הָאלהי\"ם אֲשֶׁר נְתָנָהּ, וְגוּפָא אִשְׁתָּאַר יַבָּשָׁה, הֲדָא הוּא דִכְתִיב וְתֵרָאֶה הַיַּבָּשָׁה, לְבָתַר דְּאִתְכַּנְשַׁת נִשְׁמָתֵיהּ, קוּדְשָׁא בְּרִיךְ הוּא יֵימָא לִשְׁכִינְתָּא, תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ, מָאן חַיָּה אִלֵּין חַיּוֹת הַקֹּדֶשׁ, וְנַהֲרִין לֵיהּ, דְּנָחֲתִין לֵיהּ לְקַבְּלָא לֵיהּ, הֲדָא הוּא דִכְתִיב (תהלים צא יב) עַל כַּפַּיִם יִשָּׂאוּנְךָ וכו'.</p>\n<p>וְעוֹד תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְקַבְּלָא לֵיהּ, לְמִינָהּ דָּא בַּת זוּגֵיהּ דְּאִתְיְיהִיבַת לֵיהּ בְּהַהוּא עָלְמָא, בְּהֵמָה וָרֶמֶשׂ וְחַיְתוֹ אֶרֶץ לְמִינָהּ, כַּמָּה חֲיָילִין וּמַשִּׁרְיָין לִיקָרֵיהּ, וּלְבָתַר אַפִּיק לֵיהּ אִילָנִין וְעִשְׂבִּין בְּגִנְּתָא דְעִדֶן, הֲדָא הוּא דִכְתִיב וַיֹּאמֶר אלהי\"ם תַּדְשֵׁא הָאָרֶץ וכו', כָּל מַה דְּאִתְבְּרֵי בְּשִׁית יְמֵי בְרֵאשִׁית כֻּלְּהוּ מְזוּמָן לֵיהּ בְּהַהוּא עָלְמָא, בְגַן עִדֶן עִלָּאָה וְתַתָּאָה.</p>\n<p>דָּבָר אַחֵר זֶה סֵפֶר תּוֹלְדוֹת אָדָם, דָּא סִפְרָא דַחֲנוֹךְ נַעַר, דַּעֲלֵיהּ אִתְּמַר (בראשית ה כב) וַיִתְהַלֵּךְ חֲנוֹךְ אֶת הָאלהי\"ם וְאֵינֶנּוּ כִּי לָקַח אוֹתוֹ אלהי\"ם, וְאַמַּאי קָארֵי לֵיהּ תּוֹלְדוֹת אָדָם, אֶלָּא הָכָא רָזָא דְגִלְגּוּלָא, תּוֹלְדוֹת אָדָם אִתְקְרֵי, דְּמִנֵּיהּ נָפַק, וְאִיהוּ הֲוָה תּוֹלָדָה דִילֵיהּ, וְאַמַּאי אִתְקְרֵי נַעַר, אֶלָּא הָכָא רָזָא (איוב לג כה) יָשׁוּב לִימֵי עֲלוּמָיו, כְּמָה דַהֲוָה בְּקַדְמֵיתָא לְעִילָא, וּלְבָתַר נָחִית בְּהַהוּא דְאִתְּמַר בֵּיהּ (בראשית לז ב) וְהוּא נַעַר אֶת בְּנֵי בִלְהָה וְאֶת בְּנֵי זִלְפָּה נְשֵׁי אָבִיו, וַיָּבֵא יוֹסֵף אֶת דִּבָּתָם רָעָה, מַאי דִּבָּתָם רָעָה אֶלָּא דַהֲווֹ מִגִּזְעָא</p>"],[9500011274,"<p>דְאִלֵּין דְּאָמְרוּ (תהלים ח ה) מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ וּבֶן אָדָם כִּי תִפְקְדֶנּוּ וַתְּחַסְּרֵהוּ מְעַט מֵאלהי\"ם, דְּיַהֲבַת לֵיהּ כָּל גִּנְזֵי שְׁמַיָּא, וְכָל מַפְתְּחָן דִּילֵיהּ בִּידֵיהּ, וְאַשְׁלְטֵיהּ בְּכָל דִּילֵיהּ, כְּגַוְונָא דְמַלְכָּא דְאָמַר לְיוֹסֵף (בראשית מא מ) רַק הַכִּסֵּא אֶגְדַּל מִמֶּךָּ.</p>\n<p>אָמַר לֵיהּ וְהָא עז\"א ועזא\"ל הֲווֹ אִלֵּין, אָמַר לֵיהּ וְהָא אָחֳרָנִין הֲווֹ מִתְכַּנְּשִׁין עִמֵּיהּ, אָמַר לֵיהּ רַבִּי אֶלְעָזָר וְהָא קוּדְשָׁא בְּרִיךְ הוּא עַד דְּאִתְיָיעַץ בַּחֲיָילִין דִּילֵיהּ לָא הֲוָה עָבִיד לְאָדָם, דְּאָמַר נַעֲשֶׂה אָדָם, אָמַר לֵיהּ לְאוֹלָפָא דֶרֶךְ אֶרֶץ לִבְנֵי נָשָׁא, דְנָטִיל רַבְרְבָא עִצָה מִדִּזְעִיר מִנֵּיהּ, וְלָא עוֹד אֶלָּא רָזָא אָחֳרָא אִית הָכָא, לְמַלְכָּא דַהֲוָה לֵיהּ שְׁלִיחָא מְהֵימְנָא, וַהֲוָה בָּעִי לְמֵיהַב לֵיהּ אַגְרֵיהּ, אָמַר לְחֵיְילוֹי אֲנָא בָעִינָא לְשַׁלְטָאָה הַאי שְׁלִיחָא דִילִי עֲלַיְיכוּ, בְּגִין דְּהוּא מְהֵימְנָא, אִי אִית מָאן דְּיָדַע בֵּיהּ מִלָּה אָחֳרָא יֵימָא, בְּזִמְנָא דְלָא אַשְׁכַּח מְקַטְרְגָא עֲלֵיהּ, אָמַר נַעֲשֶׂה אָדָם.</p>\n<p>וְתוּ נַעֲשֶׂה אָדָם, בָּעִינָא אָדָם דְּיַעֲבִיד פִּקּוּדֵי אוֹרַיְיתָא, וְיִשְׁתַּדַּל בְּאוֹרַיְיתָא, לְעָבְדָהּ וּלְשָׁמְרָהּ, וִיהֵא לֵיהּ אַגְרָא טָבָא, וְשׁוּלְטָנוֹ עֲלַיְיכוּ, וְדָא אִיהוּ (ישעיה ס כא) נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר, דְּהָא מַלְאֲכֵי עִלָּאֵי אַף עַל גַּב דְּאִינוּן גִּבּוֹרֵי כֹחַ עוֹשֵׂי דְּבָרוֹ, לָא עָבְדֵי גְּבוּרָה בְּפוּלְחָנָא דְקוּדְשָׁא בְּרִיךְ הוּא, דְאִינוּן פָּלְחִין בְּהֶכְרֵחַ, וְלֵית לוֹן עִרוּבָא דְבִשְׂרָא וְיִצְרָא בִישָׁא, וּבְגִין דָּא נַעֲשֶׂה אָדָם, וְיִשְׁלוֹט בְּכוּ, הֲדָא הוּא דִכְתִיב (בראשית א כו) וְיִרְדּוּ בִדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם וְגוֹמֵר.</p>\n<p>וְתוּ נַעֲשֶׂה אָדָם אֲנָא יָהִיב בֵּיהּ נִשְׁמָתָא, דִכְתִיב בְּצַלְמֵינוּ, וּכְתִיב (תהלים לט ז) אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ, וְאַתּוּן יַהֲבוּ בֵּיהּ רוּחָא וְנַפְשָׁא, וְאַרְעָא אַרְבַּע יְסוֹדִין, וְיִדְמֶה לְכֹלָּא עִלָּאִין וְתַתָּאִין, וּמַה דְּרָעִינָא דְלֶהֱוִי שַׁלִּיט וּמְמַנָּא עֲלַיְיכוּ, אַצְדִּיקוּ דִינָא דִילִי, וִיהֵא בִרְעוּ דִלְכוֹן, דַּאֲנָא אַשְׁרֵי שְׁמִי עֲלֵיהּ, וְחוֹתָמָא דִילִי בִּידֵיהּ, דְּאִיהוּ חוֹתָם הַבְּרִית, מַלְאָכַיָּא דְסִטְרָא יְמִינָא בָּרְכוּ לֵיהּ, וְאָמְרוּ נַעֲשֶׂה וְנִשְׁמַע, הֲדָא הוּא דִכְתִיב (שם קג כ) בָּרְכוּ יהו\"ה מַלְאָכָיו גִּבֹּרֵי כֹחַ עֹשֵׂי דְבָרוֹ לִשְׁמֹעַ בְּקוֹל דְּבָרוֹ, וְדָא מטטרו\"ן, לְקִבְלֵיהּ יוֹסֵף לְתַתָּא, וַהֲווֹ אָחֳרָנִין דַּהֲווֹ שָׂנְאִין לֵיהּ וְאָמְרוּ (שם ח ה) מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ, וּבְגִין דָּא וַיָּבֵא יוֹסֵף אֶת דִּבָּתָם רָעָה, וַיִּשְׂנְאוּ אֹתוֹ וְלֹא יָכְלוּ דַבְּרוֹ לְשָׁלוֹם, וְלַאו דְּאִינוּן אִלֵּין עז\"א ועזא\"ל, אֶלָּא אִינוּן אָחֳרָנִין דְּאִתְכַּנְשׁוּ (ס\"א דאתכללו) עִמְּהוֹן.</p>\n<p>דָּבָר אַחֵר זֶה סֵפֶר תּוֹלְדוֹת אָדָם, אָמַר רַבִּי שִׁמְעוֹן, זֶה סֵפֶר דָּא צַדִּיק חַי עָלְמִין, דְּאִיהוּ אַפִּיק תּוֹלְדִין, זֶה סֵפֶר וַדַּאי וְלָא אָחֳרָא, וְאִינוּן תּוֹלְדוֹת אָדָם, הַהוּא דְאִתְּמַר בֵּיהּ (ישעיה מד ג) כְּתִפְאֶרֶת אָדָם לָשֶׁבֶת בָּיִת, מָאן בַּיִת דִּילֵיהּ, דָּא שְׁכִינְתָּא, וְרַעֲיָא מְהֵימְנָא אַנְתְּ הוּא כְּדִיּוֹקְנֵיהּ, וְלָךְ חֵילָא לְאִסְתַּכָּלָא בְּדִיּוֹקְנִין דִּבְנֵי נָשָׁא, בְּצִיּוּרִין דְּהַהוּא דְאִתְּמַר בֵּיהּ (בראשית ה א) בִּדְמוּת אלהי\"ם בָּרָא אוֹתוֹ, דְּכָל צִיּוּרִין דִּבְנֵי נָשָׁא אִינוּן רְשִׁימִין בְּכָרְסַיָּא, וּבְגִין דְּכָל כָּרְסַיָּא וּמַרְכַּבְתָּא דְאַנְתְּ זְקִיקָא, אַנְתְּ אִית לָךְ חֵילָא לְאִסְתַּכָּלָא, בְּגִין כַּךְ וְאַתָּה תֶחזֶה מִכָּל הָעָם וְגוֹמֵר</p>\n<p>(אמר המגיה זה מצאתי בס\"א וטוב לשומו כאן) דָּבָר אַחֵר (בראשית ה א) זֶה סֵפֶר תּוֹלְדוֹת אָדָם וכו', זֶה תְּרֵין עֲשַׂר אַנְפִּין, דְּאִתְּמַר בְּהוֹן (יחזקאל א י) וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּם, וּפְנֵי שׁוֹר וְגוֹמֵר, וּפְנֵי נֶשֶׁר וְגוֹמֵר, בְּיוֹם בְּרֹא אלהי\"ם אָדָם חַיָּה רְבִיעָאָה, וְצָּרִיךְ לְאִסְתַּכָּלָא בְּהוֹן, בְּאַנְפִּין בְּאַרְבַּע גַּוָּונִין דְּנַהֲרִין בְּהוֹן אַרְבַּע חַיּוֹת, דְּאִתְּמַר בְּהוֹן (דברים ה ד) פָּנִים בְּפָנִים דִּבֶּר יהו\"ה עִמָּכֶם, וּבְמֹשֶׁה נֶאֱמַר (שמות לג יא) וְדִבֶּר יהו\"ה אֶל מֹשֶׁה פָּנִים אֶל פָּנִים, בָּתַר דְּאַהֲדָרוּ לַאֲחוֹרָא, קוּדְשָׁא בְּרִיךְ הוּא הַדַּר לוֹן אֲחֹרוֹי, וְדָא אִיהוּ (שם כג) וְרָאִיתָ אֶת אֲחֹרָי וּפָנֵי לֹא יִרָאוּ, וְאִלֵּין אִינוּן פָּנִים דְּנִרְאִין וּפָנִים דְּאֵינָן נִרְאִין. אַנְפִּין חִוָּורִין בַּעֲנָוָה, אִינוּן אַנְשֵׁי חַיִל, אַנְפִּין סוּמְקִין בְּבֹשֶׁת, דְּאִית לוֹן כְּסוּפָא מִן שְׁמַיָּא, אִינוּן יִרְאֵי אלהי\"ם, אַנְפִּין יְרוֹקִין בְּאוֹרַיְיתָא, אִינוּן אַנְשֵׁי אֱמֶת, אַנְפִּין אוּכְמִין בְּמִצְּוָה, דְאִיהִי תְּפִלָּה דְיָד, וּתְפִלִּין בְּמִשְׁכָא אוּכְמָא, אִינוּן שֹׂנְאֵי בָצַּע, אֲבָל אַנְפִּין בְּלָא עֲנָוָה וּבְלָא בֹשֶׁת וּבְלָא תּוֹרָה וּמִצְּוָה, אִינוּן תֹּהוּ וָבֹהוּ וְחֹשֶׁךְ וְרוּחַ, דְאִתְּמַר בְּהוֹן (בראשית א ב) וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ וכו', דְּאִינוּן אַחְזְרִין עָלְמָא לְתֹהוּ וָבֹהוּ, אַנְשֵׁי חַיִל מִזַּרְעָא דְאַבְרָהָם, דְּבֵיהּ שְׁכִינְתָּא תַּתָּאָה, יִרְאֵי אלהי\"ם מִזַּרְעָא דְיִצְּחָק, דְּבֵיהּ שְׁכִינְתָּא עִלָּאָה, דְהִיא אוֹצְּרָא לְחָכְמָה, אַנְשֵׁי אֱמֶת מִזַּרְעָא דְיַעֲקֹב דְּאִתְּמַר בֵּיהּ (מיכה ז כ) תִּתֵּן אֱמֶת לְיַעֲקֹב, וּבֵיהּ ו' דְּאִיהוּ תִּפְאֶרֶת, שֹׂנְאֵי בָצַּע מִסִּטְרָא דְּדָוִד דְּאִיהוּ רַגְלָא רְבִיעָאָה וּבֵיהּ י', דְאִתְּמַר בֵּיהּ בְּגִינָהּ (שמואל א יז יד) וְדָוִד הוּא הַקָּטָן, הַאי אִיהוּ שְׁמָא ההו\"י, וּבְגַוָּונָא אָחֳרָא אִתְפַּרִישׁ לְזִמְנִין הוה\"י, שְׁכִינְתָּא עִלָּאָה וְתַתָּאָה, עַמּוּדָא דְאֶמְצָּעִיתָא בֵּינַיְיהוּ, וּבְגַוָּונָא אָחֳרָא יהו\"ה מִסִּטְרָא (דמשה) דְמטטרו\"ן, גַּוָּונִין מִתְהַפְּכִין לְשִׁית סְרֵי בִּשְׁכִינְתָּא כַּד אִיהִי צְּרִיכָא לְתַתָּאִין, וְדָא אִיהוּ דְאָמְרוּ מָארֵי מַתְנִיתִין, דְּבַר נַשׁ דְּצָּרִיךְ לִבְרִיּוֹת אַנְפּוֹי מִשְׁתַּנִין כַּכְּרוּם, דְּאִתְהֲפַךְ לְכַמָּה גַוָּונִים, וְאִית הֲפוּכָא דְגַוָּונִים לְטַב דְּנַהֲרִין בִּנְהוֹרָא, וְאִינוּן מְרַקְמָן מִכַּמָּה גַוָּונִין, וְכָל הַאי בְּגוּפָא, כְּגַוְונָא (דגינתא) דְעֵדֶן דְאִתְבְּרֵי בִּשְׁמָא דְיהו\"ה. כָּל גַּוָּונִין וְצִּיּוּרִין דְּאִלֵּין גּוּפִין, וְאִינוּן כְּגַוְונָא דְנוֹבֶלֶת אוֹרָה דִלְעֵילָא גַלְגַּל חַמָּה, וַעֲלַיְיהוּ אִתְּמַר פְּנֵי מֹשֶׁה כִּפְנֵי חַמָּה וּפְנֵי יְהוֹשֻׁעַ כִּפְנֵי לְבָנָה, וְכַךְ דִּיּוֹקְנָא אִית לֵיהּ אַרְבַּע גַּוָּונִין, דְּאִית גַּוְונָא חִוְורָא סוּמְקָא יְרוֹקָא אוּכְמָא, נִימִין אִינוּן כֹּכְבַיָּא וּמַלְאָכַיָּא וּמְמַנָּן דְּתַלְיָין מֵאַנְפִּין כְּחוּשְׁבַּן נִימִין, וְכֻלְּהוּ מְשַׁמְּשֵׁי לְאַנְפִּין. פּוּמָא (במדבר יב יח) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ וּמַרְאֶה וְלֹא בְחִידוֹת, פֶּה אִיהוּ בְּרָזָא דִכְרוּבִים, דְּאִתְּמַר בְּהוֹן (שמות כה כ) וְהָיוּ הַכְּרוּבִים פֹּרְשֵׂי כְנָפַיִם לְמַעְלָה, אִלֵּין שִׂפְוָון כַּד אִתְפַּתְּחוּ אִתְפַּתְּחוּ בְּאדנ\"י (יהו\"ה), כְּמָה דְאַתְּ אָמַר (תהלים נא יז) אדנ\"י שְׂפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךָ. וְאָמְרוּ מָארֵי מַתְנִיתִין, כָּל הַכּוֹרֵעַ כּוֹרֵעַ בְּבָרוּךְ, וְכָל הַזּוֹקֵף זוֹקֵף בְּשֵׁם יהו\"ה, כַּד אִיהוּ כּוֹרֵעַ כְּרוּבִים סוֹכֲכִים בְּכַנְפֵיהֶם, וְדָא אִיהוּ סִכוּךְ דְּסוּכָּה, דְאִיהוּ כ\"ו ה\"ס, וְסִימָנָא יהו\"ה אדנ\"י, פֹּרְשֵׂי כְנָפַיִם לְמַעְלָה אִיהוּ רְמַ\"ח, כָּל הַזּוֹקֵף זוֹקֵף בְּשֵׁם, בִּתְרֵין שְׁמָהָן דְּאִינוּן אהי\"ה יהו\"ה, וְסִימָנָא י\"א י\"א, (דברים ו ד) יהו\"ה אלהינ\"ו יהו\"ה אֶחָד, חָכְמָה וּבִינָה עֲלַיְיהוּ אִתְּמַר וְהָיוּ הַכְּרֻבִים פֹּרְשֵׂי כְנָפַיִם לְמַעְלָה, יהו\"ה אֶחָד עֲלַיְיהוּ אִתְּמַר סֹכֲכִים בְּכַנְפֵיהֶם עַל הַכַּפֹּרֶת וְאִינוּן ו\"ה. דָּבָר אַחֵר וְהָיוּ הַכְּרֻבִים, אִינוּן צּוּרַת אָדָם, דְּאִיהוּ יו\"ד ה\"א וא\"ו ה\"א, פּוֹרְשֵׂי כְנָפַיִם לְמַעְלָה י\"ה, סֹכֲכִים בְּכַנְפֵיהֶם ו\"ה, דְּאִינוּן אַרְבַּע גַּדְפִין, וַעֲלַיְיהוּ אִתְּמַר (שמות יט ד) וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים, וּכְרוּבִים תְּרֵי שִׂפְוָון, עַל נֵס הָיוּ עוֹמְדִים, דָּא לִישְׁנָא, וַיִּשְׁמַע אֶת הַקּוֹל, קָלָא דְנָפִיק מִגָּרוֹן, וַיְדַבֵּר אֵלָיו דִבּוּר דְּפוּמָא, וְקָלָא וְדִבּוּר תִּפְאֶרֶת וּמַלְכוּת, וְעֶשֶׂר אַמּוֹת אֹרֶךְ הַקָּרֶשׁ, וַעֲלֵיהּ אִתְּמַר (מלאכי ב ו) תּוֹרַת אֱמֶת הָיְתָה בְּפִיהוּ, דָא פּוּמָא הֵיכָל, וַעֲלֵיהּ אִתְּמַר אדנ\"י שְׂפָתַי תִּפְתָּח. מִלְּגָאו מִנֵּיהּ קֹדֶשׁ הַקֳּדָשִׁים וְדָא לִבָּא, כְּרוּבִים כַּנְפֵי רֵיאָה, עֲלַיְיהוּ אִתְּמַר וְהָיוּ הַכְּרֻבִים פֹּרְשֵׂי כְנָפַיִם לְמַעְלָה סֹכֲכִים בְּכַנְפֵיהֶם עַל הַכַּפֹּרֶת, דָּא כַּפֹּרֶת הַלֵּב, דְּתַמָּן (משלי כ טז) נֵר יהו\"ה נִשְׁמַת אָדָם, וּפְנֵיהֶם אִישׁ אֶל אָחִיו תְּרֵין כִּלְיָין. בְּלִבָּא דְאִיהוּ קֹדֶשׁ הַקֳּדָשִׁים אִית תְּרֵי בָּתֵּי, בְּחַד סַם חַיִּים, וּבְחַד סַם מָוְת דְּאִיהִי אֵשׁ, כַּהֲנָא רַבָּא דְעָאל לְקֹדֶשׁ הַקֳּדָשִׁים, אִם זָכָה סַם חַיִּים הֲוָה נָפְקָא מִתַּמָּן וּנְהִירָא בְּאַנְפּוֹי, וְקָלָא וְדִבּוּר הֲוָה נָפִיק מִתַּמָּן מִקּוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, וְאִם לָא זָכָה סַם מָוְת הֲוָה נָפִיק מִסִּטְרָא דִשְׂמָאלָא, וַהֲוָה קָטִיל לֵיהּ, וּמַאי נִיהוּ כַּהֲנָא בְּגוּפָא, אֶלָּא נְשָׁמָה וְרוּחַ וְנֶפֶשׁ, אִינוּן לָקֳבֵל כֹּהֲנִים לְוִיִּים וְיִשְׂרְאֵלִים, תְּלַת צְּלוֹתִין לָקֳבֵל תְּלַת קָרְבָּנִין, וְאִינוּן מַאֲכָלִין דְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ. אִם הֲוָה עָאל בִּשְׁכִינְתָּא דְאִיהִי סַם חַיִּים, סַם חַיִּים הֲוָה נָפִיק לְקַדְמוּתֵיהּ, וְאִם לַאו הָא סַם הַמָּוְת לְקִבְלֵיהּ, דְּאִיהִי מָרָה אוּכְמָא, וּמִינָהּ יָמוּת בַּר נַשׁ בַּעֲנִיּוּת, וְאִיהִי לְסִטְרָא שְׂמָאלָא דְלִבָּא, וְדָא טְחוֹל. בְּנֵי אַהֲרֹן רוּחַ וְנֶפֶשׁ, דְּאַהֲרֹן אִיהוּ נְשָׁמָה, תְּרֵין בְּנוֹי נֶצַּח וְהוֹד, אִם יַעֲלוּן קָרְבָּנָא כִּדְקָא יָאוּת, הָא סַם חַיִּים, וְאִי לַאו הָא סַם מָוְת, דְּאִיהִי מָרָה, אֵשׁ זָרָה אוֹקִיד לוֹן, דִּכְתִיב (ויקרא י א) וַיַּקְרִיבוּ לִפְנֵי יהו\"ה אֵשׁ זָרָה וְגוֹמֵר, וַתֵּצֵּא אֵשׁ וְגוֹמֵר, אִינוּן סְלִיקוּ לָהּ מֵאַתְרָהָא, וְעָאלוּ לָהּ קַמֵּי מַלְכָּא לְלִבָּא, וְלָא הֲוָה לְהוּ רְשׁוּ לְמֵיעָאל לְתַמָּן, בָּהּ קוּדְשָׁא בְּרִיךְ הוּא נָטִיל דִּינָא בְּהוֹן. שִׂפְוָון עַקִּימִין, לֵית רְשׁוּ לְכַהֲנָא לְקַרְבָא בְּהוֹן קָרְבָּנָא, דְעָאל קֳדָם יהו\"ה, דַּעֲלַיְיהוּ אִתְּמַר (קהלת א טו) מְעֻוָּת לֹא יוּכַל לִתְקוֹן וכו', וְכֵן עַיְינִין עֲקִימִין פְּטוּרִין מִן הָרְאִיָּיה, דְנָחָשׁ עֲקַלָּתוֹן תַּמָּן, דְאִיהוּ נָטִיל נְהוֹרַיְיהוּ, וּפִימָא אַטִימָא אִתְקְרֵי טוּמְטוּם, וְאַנְדְּרוֹגִינוֹס אִיהוּ דִיּוֹקְנָא דְזָכָר וּנְקֵבָה, כְּגַוְונָא דָא אִיהוּ בַּר נַשׁ דְּקָלֵיהּ וְדִבּוּרֵיהּ כְּנוּקְבָא, וּמָאן דְאִיהוּ חֶצְּיוֹ עֶבֶד וְחֶצְּיוֹ בֶּן חוֹרִין, חֶצְּיוֹ עֶבֶד דְּיֵצֶּר הָרָע, וְחֶצְּיוֹ בֶּן חוֹרִין דְּיֵצֶּר הַטוֹב, כָּל אִלֵּין פְּטוּרִין מִן הָרְאִיָּה, בְּזִמְנָא דְנָפְקִין מִן גּוּפָא, נַפְשָׁא דְאִיהִי כְּגַוְונָא דָא, לֵית לָהּ רְשׁוּ לְאִסְתַּכְּלָא וּלְאִתְחַזְיָיא בִּשְׁכִינְתָּא, קַדְמָהָא בְּשַׁעַת פְּטִירָתָהּ מִן גּוּפָא. פִּימָא דְאַטִימָא בְּדִבּוּר, אֶבֶן דְּאִיהוּ יֵצֶּר הָרָע שַׁלִּיט עֲלָהּ, וְאִתְקְרֵי טוּמְטוּם, בְּגִין דָּא פָּטוּר מִן הָרְאִיָּיה, דְּנִשְׁמָתָא וְרוּחָא וְנַפְשָׁא בְּגִין דָּא יֵיתוּן בְּגִלְגּוּלָא, עַד דְּאִתְחַזְרָן שְׁלֵמִין לְאַתְרַיְיהוּ כְּמָה דְאִתְיְיהִיבוּ, כְּמָה דְאַתְּ אָמַר (קהלת יב ז) וְהָרוּחַ תָּשׁוּב אֶל הָאלהי\"ם אֲשֶׁר נְתָנָהּ, וּמִינָהּ אוֹלִיפְנָא קַל וָחוֹמֶר בְּאָחֳרָנִין דְּאִינוּן נִשְׁמָתָא וְנַפְשָׁא, וְלָא עוֹד אֶלָּא דִקְרָא אַסְהִיד עֲלַיְיהוּ (איוב לג כט) הֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַעֲמַיִם שָׁלֹשׁ עִם גָּבֶר. וּמָאן דְּיֵיתֵי בְּגִלְגּוּלָא זִמְנָא קַדְמָאָה אִם יֵיתֵי חִוָּור, אִתְקַיַּים בֵּיהּ קְרָא (ישעיה א יח) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ, וּבַמֶּה יִתְיַדַּע בַּר נַשׁ דְּאִיהוּ בְּגִלְגּוּלָא קַדְמָאָה, אִם הוּא קָלֵיהּ</p>"],[9500011275,"<p>כִּשְׁבָרִים אוֹ כִּתְרוּעָה, וְגוּפֵיהּ וְאַנְפּוֹי חִוָּורִין, אִם הוּא קָלֵיהּ כִּשְׁבָרִים אִיהוּ מִזִּמְנָא קַדְמָאָה, וְאִם קָלֵיהּ כִּתְרוּעָה אִיהוּ מִזִּמְנָא תִּנְיָנָא, וְאִם גּוּפֵיהּ יְרוֹקָא וְאַנְפּוֹי יְרוֹקִין וְקָלֵיהּ תְּקִיעָה אִיהוּ מִזִּמְנָא תְּלִיתָאָה, וְאִם הֲדַר לְגַוָּונֵיהּ, קָלֵיהּ כִּתְקִיעָה וְגוּפֵיהּ חִוָּור וְאַנְפּוֹי חִוָּורִין, דָּא אִיהוּ כְּגַוָּונֵיהּ קַדְמָאָה, כְּמוֹ דְאוּקְמוּהוּ בְּיַיִן דְּהֶחְמִיץ דְּחָזַר לְגַוָּונֵיהּ קַדְמָאָה, כְּגַוְונָא דָא בְּהִפּוּכָא לְטָב, וְכֵן אַנְפּוֹי סוּמְקִין וְקָלֵיהּ כִּשְׁבָרִים, וְאַנְפּוֹי יְרוֹקִין וְקָלֵיהּ תְּרוּעָה, הָא אִתְתַּקַּן. וְעוֹד אַשְׁכַּחְנָא, בַּר נַשׁ דְּכָל צִּיּוּרִין דִילֵיהּ בְּאֹרַח מֵישָׁר, שְׁקִילִין בְּתִקְלָא, וּלְזִמְנִין שִׂפְוָון אִינוּן עָבִים, וְנָפְקִין מִתִּקּוּנָא דְצִּיּוּרִין וְדִיּוֹקְנִין אָחֳרָנִין, אוֹ אִינוּן אֲרוּכִין אוֹ אִינוּן קְצָּרִים, תָּא חֲזִי וְאַתָּה תֶחֱזֶה מִכָּל הָעָם, הָכָא אוּקִימְנָא לְמִנְדַע תִּקּוּנִין אִלֵּין, אַנְשֵׁי חַיִל עַיְינִין, יִרְאֵי אלהי\"ם אוּדְנִין, הֲדָא הוּא דִכְתִיב (חבקוק ג ג) יהו\"ה שָׁמַעְתִּי שִׁמְעֲךָ יָרֵאתִי, אַנְשֵׁי אֱמֶת חוֹטָמָא, שׂוֹנְאֵי בָצַּע פּוּמָא, אִם חוֹטָמָא לַאו אִיהוּ בְּשָׁוָה עִם תִּקּוּנִין אַחֲרָנִין, דְּעַיְינִין אֲרִיכִין, וְאַנְפִּין אֲרִיכִין, וְאוּדְנִין אֲרִיכִין, וּפוּמָא אֲרִיכָא, וְחוֹטָמָא עָבָה, תַּמָּן אִתְגַּלְיָא גִלְגּוּלָא דְנַפְשָׁא, וְאִם עַיְינִין לָא בְּשָׁוָה מֵאָחֳרָנִין, תַּמָּן אִתְגַּלְיָא גִלְגּוּלָא דְנִשְׁמָתָא, וְאִם אוּדְנִין לַאו בְּשָׁוָה, תַּמָּן אִתְגַּלְיָא גִלְגּוּלָא דְרוּחָא, פּוּמָא בְּגִין דְּאִיהִי כְּלָלָא דְכֹלָּא, אִם לַאו אִיהִי בְּשָׁוָה, הָא אִתְּמַר בֵּיהּ (שמות כ ה) פֹּקֵד עֲוֹן אָבוֹת עַל בָּנִים עַל שִׁלֵּשִׁים וְעַל רִבֵּעִים, וְאִם עַל אַרְבַּע גִּלְגּוּלִין לָא אִתְתַּקְנַת, אִתְּמַר בְּהַהִיא שַׁעְתָּא (עמוס ב א) וְעַל אַרְבָּעָה לֹא אֲשִׁיבֶנּוּ. וְכָל נִשְׁמָתִין דְּאַתְיָין תְּלַת זִמְנִין וְלָא מִתְתַּקְנִין, אִתְקְרִיאוּ פּוֹשְׁעֵי יִשְׂרָאֵל עֵרֶב רַב, אֲבָל צַּדִּיקַיָּא דִבְכָל זִמְנָא דְיֵיתוּן מִתְתַּקְנִין, יֵיתוּן עַד אַרְבָּעָה, אֲפִילוּ עַד שִׁתִּין דּוֹר, וְדָא אִיהוּ (קהלת א ד) דּוֹר הוֹלֵךְ וְדוֹר בָּא, וְדָא נִשְׁמָתָא דְאִיהִי מֹשֶׁה רַבֵּינוּ, כְּלִילָא מִשִּׁתִּין רִבּוֹא, וּשְׁכִינְתָּא עִלָּאָה דְאִיהִי נִשְׁמַת חַיִּים כַּד שַׁרְיָא בְּמֹשֶׁה, אִתְחַשַּׁב לֵיהּ כְּאִלּוּ אָתָא בְּשִׁתִּין רִבּוֹא, וּבְגִינֵיהּ אִתְּמַר אִשָּׁה אַחַת יָלְדָה שִׁשִּׁים רִבּוֹא בְּכֶרֶס אֶחָד. וְאִינוּן מַרְעִין דִּבְנֵי נָשָׁא, דְאִתְּמַר בְּהוֹן (דברים כח נט) וָחֳלָיִם רָעִים, (משלי ג ח) רִפְאוּת תְּהִי לְשָׁרֶךָ, כַּד אִינוּן בְּרֵישָׁא דְצַּדִּיקַיָּא, אֲבָל כַּד אִינוּן בְּרֵישָׁא דְרַשִּׁיעַיָּא, כְּנֶסֶת יִשְׂרָאֵל אָמְרַת לְגַבַּיְיהוּ (שיר א ו) אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחֹרֶת, דְאִלֵּין שַׁרְיָין לוֹן לְפַתָּאָה לִבְנֵי נָשָׁא, כְּמָה דַהֲווֹ מְפַתֵּי לְיִשְׂרָאֵל בְּעֶגְלָא בְּשִׁית שַׁעְתִּין, הֲדָא הוּא דִכְתִיב (שמות לב א) וַיַּרְא הָעָם כִּי בֹשֵׁשׁ מֹשֶׁה, הָא אוּקְמוּהָ בְּשִׁית שַׁעְתִּין עֲבַדוּ יָת עֶגְלָא, בֵּין שֵׁשׁ לְשֶׁבַע, אַפְרִישׁוּ בֵּין עַמּוּדָא דְאֶמְצָּעִיתָא לְשֶׁבַע, דְּגוּפָא וּשְׁכִינְתָּא, וּבְגִין דָּא מַנִּי קוּדְשָׁא בְּרִיךְ הוּא לְאַפְרָשָׁא לוֹן מִשֶּׁבַע, הֲדָא הוּא דִכְתִיב (שם יב טו) אַךְ בַּיּוֹם הָרִאשׁוֹן, אַךְ חָלַק בֵּין שִׁית לְשֶׁבַע, בְּגִין דָּא אָמְרָה כְּנֶסֶת יִשְׂרָאֵל (שיר א) שֶׁשְּׁזָפַתְנִי הַשָּׁמֶשׁ, שֵׁשׁ זָפַתְנִי הַשָּׁמֶשׁ, דְּאִסְתַּלַּק מִנִּי ו' דְאִיהוּ הַשָּׁמֶשׁ, דְּנָהִיר בְּשִׁית תֵּיבִין דְּאִינוּן (דברים ו ד) שְׁמַע יִשְׂרָאֵל יהו\"ה אלהינ\"ו יהו\"ה אֶחָד, וְהָא אִתְּמַר.</p>\n<p>(עד כאן ההג\"ה מספרים אחרים).</p>\n<p>וַיְחִי</p>"],[9500011276,"<p>אָדָם שְׁלֹשִׁים וּמְאַת שָׁנָה וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ וַיִּקְרָא אֶת שְׁמוֹ שֵׁת (בראשית ה ג), ש תְּלַת חֵיוָון דְּמַרְכַּבְתָּא, ת אִיהִי (משלי כ כח) נֵר יהו\"ה נִשְׁמַת אָדָם, דְּאִתְּמַר בָּהּ (יחזקאל א י) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, וְדָא אִיהוּ וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ. וַיִּהְיוּ כָּל יְמֵי אָדָם אֲשֶׁר חַי תְּשַׁע מֵאוֹת שָׁנָה וּשְׁלֹשִׁים שָׁנָה וַיָּמוֹת, מַאי וַיָּמוֹת, אֶלָּא כָּל יוֹמִין דַּהֲוָה חַי הֲוָה תְּשַׁע מֵאוֹת וּתְלָתִין שְׁנִין, וּשְׁאָר שְׁנִין בְּתוֹסֶפֶת הֲוָה מִית. וְשַׁבְעִין דְּחָסְרוּ מֵאֶלֶף, יְהַב לְדָוִד מִשְּׁנוֹי, בְּגִין דַּהֲוָה עָתִיד לְאַשְׁלָמָא לוֹן בֵּיהּ, וְהָכָא רָזָא דְפוּרְקָנָא.</p>\n<p>עִִּשֶׂר דָּרִין הֲווֹ מֵאָדָם וְעַד נֹחַ, (בראשית ה כח) וַיְחִי לֶמֶךְ שְׁתַּיִם וּשְׁמֹנִים שָׁנָה וּמְאַת שָׁנָה וַיּוֹלֶד בֵּן וַיִּקְרָא אֶת שְׁמוֹ נֹחַ, לֵאמֹר זֶה יְנַחֲמֵנוּ מִמַּעֲשֵׂינוּ וּמֵעִצְּבוֹן יָדֵינוּ, וְאַמַּאי, דִּבְקַדְמֵיתָא הֲווֹ טָרְחִין בְּגִלְגּוּלִין, עַד דְּאָתָא נֹחַ דְּאִיהוּ שַׁבָּת, וּבֵיהּ נָחוּ כֻּלְּהוּ, וּבֵיהּ אִתְיַישְׁבוּ, וְאַפִּיק לוֹן לְעָלַם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר אַמַּאי הֲווֹ קַדְמָאִין חַיִּין יוֹמִין סַגִּיאִין, כְּגוֹן אָדָם דְּאִתְּמַר בֵּיהּ וַיְחִי אָדָם תְּשַׁע מֵאוֹת שָׁנָה וּשְׁלֹשִׁים שָׁנָה, וְנֹחַ תְּשַׁע מֵאוֹת וַחֲמִשִּׁים שָׁנָה, וְכֵן כֻּלְּהוּ דָרִין עַד נֹחַ הֲווֹ חַיִּין שְׁנִין סַגִּיאִין, וּמֵאַבְרָהָם (נ\"א ומנח) וְאֵילֵךְ הֲווֹ מִתְמַעֲטִין בִּשְׁנִין, אָמַר לֵיהּ בְּרִי, רִבּוּי שְׁנִין וַאֲרִיכוּ דְיוֹמִין אִינוּן מֵאֲרִיךְ אַנְפִּין, וּמִעוּטָא דְיוֹמִין וּשְׁנִין מִזְּעִיר אַנְפִּין, וּבְגִין דָּא בְּאַבְרָהָם אִתְּמַר אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם בְּה' זְעִירָא.</p>\n<p>בָּרוּךְ יהו\"ה לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9500011277,"<p>(אמר המגיה אלו התקונים מצאתי בספר אחר כתובים מאחד ועשרים תקונים ולהלאה, ולמען לא ימצא זה החבור נעדר מאלו המרגליות יקרות וטובות, גמרתי אומר לשים בעט ברזל ועופרת את שרשרות העבותות על המשבצות, ומצא מין את מינו ונעור).</p>\n<p>(זהו תקון כ\"ב וכ\"ג)</p>\n<p>בְּרֵאשִׁית בָּרָא אלהי\"ם, בְּרֵאשִׁית בָּרָ\"א תַּיִ\"שׁ, דָּא אֵילוֹ דְיִצְחָק. בְּרֵאשִׁית תַּמָּן אֵ\"שׁ לְעוֹלָה דְיִצְחָק, וְרָזָא דְמִלָּה (ועל אלין תלת גלגולין אתמר (שיר ז ב) מה יפו פעמיך בנעלים בת נדיב, (רות ד ד) וזאת לפנים דא אימא עלאה עלמא דאתי, ד\"א לגביה צריך חליצה, והדא הוא דכתיב (שמות ג ה) של נעליך וגומר, ואם לאו לית לון רשו לרווחא רמתאה (נ\"א לרוחא דמיתא) לסלקא לעלמא דאתי, ובגין דאיהי יום הכפורים אסיר בנעילת הסנדל), (בראשית כב ז) הִנֵּה הָאֵשׁ וְהָעִצִים וְאַיֵּה הַשֶּׂה לְעֹלָה, נָפַק קָלָא וְאָמַר מִשִּׁית יוֹמֵי בְּרֵאשִׁית אִתְבְּרֵי לַעֲקֵדָה דְיִצְחָק.</p>\n<p>בְּגִין דְּלָא אִית קָרְבָּן דְּבַטֵּיל מוֹתָנָא כַּעֲקֵדָה דְיִצְחָק, דְּאִתְּמַר בֵּיהּ (שם) וַיַּעֲקוֹד אֶת יִצְחָק בְּנוֹ, אִתְקַשַּׁר מִדַּת הַדִּין (מלאך המות) וְאִתְעַקַּד לְעִילָא, וְלָא הֲוָה לֵיהּ רְשׁוּ לְקָרְבָא לְבֵי דִינָא רַבְרְבָא דְאִיהוּ גְבוּרָה, לְתַבְעָא דִינָא, וַעֲקֵדָה דְנָא מוֹעִילָה לְגָלוּתָא, דַהֲוָה עָתִיד לְאִתְקַטְלָא מָשִׁיחַ בֶּן יוֹסֵף, וְקָלָא נָפִיק מֵהַהוּא זִמְנָא (שם) אַל תַּעַשׂ לוֹ מְאוּמָה (שם יב), בְּגִין דְּאִתְגַּבְּרוּ רַחֲמֵי עַל דִּינָא, וְרָזָא דְמִלָּה (תהלים צח א) הוֹשִׁיעָה לּוֹ יְמִינוֹ, וּלְבָתַר זְרוֹעַ קָדְשׁוֹ, דְגָבַר יְמִינָא עַל שְׂמָאלָא.</p>\n<p>כַּד אִתְגַּבַּר טִפָּה דִדְכוּרָא עַל טִפָּה דְנוּקְבָא אִיהוּ בֵּן, רַחֲמֵי אִיהוּ וַדַּאי, אֲבָל כַּד אִתְגַּבַּר טִפָּה דְנוּקְבָא עַל דְּכוּרָא, בַת אִיהִי וְדִינָא אִיהִי, וְרָזָא דְמִלָּה דְכוּרָא שַׁלִּיט עַל נוּקְבָא גָרִים דְּשַׁלִּיט יְמִינָא עַל שְׂמָאלָא, וְיִפְקוּן יִשְׂרָאֵל בְּרַחֲמֵי וְלָא בְדִינָא, וְדָא אִיהוּ (תהלים קיז ב) כִּי גָבַר עָלֵינוּ חַסְדּוֹ, וְרָזָא דְמִלָּה (ישעיה סו ז) בְּטֶרֶם יָבֹא חֵבֶל לָהּ וְהִמְלִיטָה זָכָר.</p>\n<p>וּבִשְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא, יהו\"ה רַחֲמֵי, אדנ\"י דִּינָא, כַּד שַׁלִּיט יהו\"ה עַל אדנ\"י יאהדונה\"י רַחֲמֵי אִיהוּ, וְכַד שַׁלִּיט אדנ\"י עַל יהו\"ה אידהנוי\"ה דִינָא אִיהוּ, וְרָזָא דְמִלָּה (שם מ י) אדנ\"י אלהי\"ם בְּחָזָק יָבֹא, בִּתְקִיפוּ דְּדִינָא, וּבְדָא עֲקֵדָה דְיִצְחָק דְּאִתְעַקַּד קַמֵּי אֲבוֹי, וּמָסַר גַּרְמֵיהּ לְמִיתָה בְּגִין דִּיְשֵׁזִיב מָשִׁיחַ וְיִשְׂרָאֵל דְּלָא יְמוּתוּן, וְלָא עוֹד אֶלָּא דַאֲפִילוּ אִי יִשְׂרָאֵל לֶהֱווּ עָבְרִין בְּגָלוּתָא, עַל שְׁפִיכוּת דָּמִים וְגִלּוּי עֲרָיוֹת וַעֲבוֹדָה זָרָה, זְכוּת אֲבָהָן יָגֵן עֲלֵיהוֹן מִשְּׂרֵפָה הֶרֶג וְחֶנֶק, בְּגִין דְּאַבְרָהָם נִתְנַסָּה בְּנוּרָא, וְיִצְחָק בְּסַכִּינָא, וְיַעֲקֹב בְּגָלוּתָא, זְכוּת אֲבָהָן יְהֵא מֵגִין עֲלֵיהוֹן.</p>\n<p>וְעוֹד נִסְיוֹנָא דִתְלַת אֲבָהָן מְעִידִין, דְּלָא עָבַר אָדָם דְּאִיהוּ יִשְׂרָאֵל עַל תְּלַת פִּקּוּדִין אִלֵּין, דְּמַנִּי לוֹן (ליה) קוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב (בראשית ב טז) וַיְצַו יהו\"ה אלהי\"ם עַל הָאָדָם, וַיְצַו דָּא עֲבוֹדָה זָרָה, לֵאמֹר דָּא גִּלּוּי עֲרָיוֹת, עַל הָאָדָם דָּא שְׁפִיכוּת דָּמִים, דְּנִשְׁמָתָא דְאָדָם עָאלַת בְּגִלְגּוּלָא דְאַבְרָהָם, וְאִם אִיהוּ עָבַד עֲבוֹדָה זָרָה, כַּד עָאל בְּנוּרָא הֲוָה אִתּוֹקַד, הֲדָא הוּא דִכְתִיב (דברים ז כה) פְּסִילֵי אֱלֹהֵיהֶם תִּשְׂרְפוּן בָּאֵשׁ.</p>\n<p>דְּאֵשׁ אִית לֵיהּ תְּלַת גַּוָּונִין, חִוָּור וְיָרוֹק וְאוּכַם, וּרְבִיעָאָה תְּכֵלֶת, וְאִינוּן דְּבֵקִין בְּגַחֶלֶת דְּאִיהוּ סוּמְקָא הָא חֲמִשָּׁה, כְּחֻשְׁבַּן ה (חמש) דְּאִיהִי אֱמוּנָה דְקוּדְשָׁא בְּרִיךְ הוּא דְאִיהוּ ו', דְּאִתְלַבַּשׁ בְּחָמֵשׁ גַּוָּונִין וְנָהִיר בְּהוֹן, וּבֵיהּ סָלְקִין גַּוָּונִין דְּאִינוּן כְּלִילָן בָּהּ, וְהִיא סְלִיקַת בְּהוֹן לְגַבֵּי ו', הֲדָא הוּא דִכְתִיב (ויקרא ו ב) הִיא הָעוֹלָה, וְכַד סָלְקִין תְּרֵין דְּאִינוּן ו' ה' בְּקָרְבָּנָא, נָחֲתִין תְּרֵין מִלְּעִילָא דְאִינוּן י\"ה,</p>"],[9500011278,"<p>וּמִתְקָרְבִין אַתְוָון וּמִתְיַיחֲדִין וּמִתְקַשְּׁרִין דָּא בְּדָא, וְדָא אִיהוּ רָזָא דְקָרְבָּנָא.</p>\n<p>וְרָזָא דְמִלָּה (בראשית כח יב) וְהִנֵּה מַלְאֲכֵי אלהי\"ם עֹלִים וְיֹרְדִים בּוֹ, סָלְקִין תְּרֵין בְּאֶשָּׁא, וְנָחֲתִין תְּרֵין. וְאִשְׁתֵּזַב אַבְרָהָם בִּשְׁמָא דְיהו\"ה, דְּאַף עַל גַּב דְּאִית אַרְבַּע מַלְאָכִים דְּאִינוּן מְמַנָּן דִּשְׁמָא קַדִּישָׁא, לָא בָּעִי קוּדְשָׁא בְּרִיךְ הוּא לְאִשְׁתַּדְלָא בְּאַבְרָהָם לְשֵׁזָבָא לֵיהּ אֶלָּא אִיהוּ מַמָּשׁ, בְּגִין דְּקַנֵּי עַל שְׁמֵיהּ, וּבֵיהּ אִתְלַבַּן אָדָם הָרִאשׁוֹן דְּאִיהוּ יִשְׂרָאֵל, דְּלָא עָבַר עַל וַיְצַו דְּאִיהוּ עֲבוֹדָה זָרָה, לְבָתַר אִתְלַבַּשׁ בְּיִצְחָק וְאִצְטְרִיף וְאָמַר (בראשית כב יב) אַל תַּעַשׂ לוֹ מְאוּמָה, דְהַהוּא דְאִצְטְרִיף בֵּיהּ לָא עָבַד מִדָּעַם, דְּלָא עָבַר עַל שְׁפִיכוּת דָּמִים, וְכֵן יַעֲקֹב אִתְגַּלְגַּל בֵּיהּ, כַּד נָחַת לְגָלוּתָא דְמִצְרָיִם (דחוצה לארץ) דְּדָחִיל דְּלָא הֲוָה סָלִיק, בְּהַהוּא זִמְנָא אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא (שם מו ג) אַל תִּירָא מֵרְדָה מִצְרַיְמָה וְגוֹמֵר, אָנֹכִי אֵרֵד עִמְּךָ מִצְרַיְמָה וְאָנֹכִי אַעַלְךָ גַּם עָלֹה.</p>\n<p>(זהו תקון כ\"ד)</p>\n<p>בְּרֵאשִׁית תַּמָּן אֲרִ\"י דְּקָרְבָּנָא, דַּהֲוָה נָחִית בְּקָרְבָּנָא בְדִיּוֹקְנָא דַאֲרִי אָכִיל קָרְבָּנִין, וְדָא אִיהוּ קַדְמָאָה לְחֵיוָון דַּהֲווֹ אָכְלֵי קָרְבָּנִין. אָמַר לֵיהּ רַבִּי אֶלְעָזָר וְאַמַּאי הֲווֹ נָחֲתִין חֵיוָון לְמֵיכַל קָרְבָּנִין, אָמַר לֵיהּ בְּרִי אַרְבַּע חֵיוָון אִינוּן בְּכָרְסַיָּא, אַרְיֵה שׁוֹר נֶשֶׁר אָדָם, וּבְגוּפָא דְבַר נַשׁ אַרְבַּע יְסוֹדֵי, דִּמְמַנָּן עֲלַיְיהוּ אַרְבַּע חֵיוָון, דְּנֶפֶשׁ כְּלִילָא בְהוֹן, וּבְגִין דָּא פַּרְנָסָה דְנַפְשָׁא מֵאִלֵּין אַרְבַּע, כַּד חָאב בַּר נַשׁ בְּאַרְבַּע יְסוֹדֵי דִילֵיהּ כְּאִלּוּ חָאב בְּנַפְשָׁא, הֲדָא הוּא דִכְתִיב (במדבר ו יא) מֵאֲשֶׁר חָטָא עַל הַנָּפֶשׁ, וּבְהַהוּא זִמְנָא אִתְפַּרַשׁ מַיָּא מֵאֶשָּׁא וְרוּחָא מֵעַפְרָא.</p>\n<p>דְּמֵעַפְרָא נָפְקִין זַרְעִין דְּאִינוּן פַּרְנָסָה דְאָדָם, וּמִמַּיָּא חֵיוָון דְּאִינוּן פַּרְנָסָה דַאֲרִי, וּמֵאֶשָּׁא בְּעִירִין דְּאִינוּן פַּרְנָסָה דְשׁוֹר, וּמֵרוּחָא עוֹפִין דְּאִינוּן פַּרְנָסָה דְנֶשֶׁר, וְכַד חָב בְּהוֹן אִתְפָּרְשָׁן יְסוֹדִין וְאִית בְּהוֹן מַחֲלוֹקֶת דְּאִיהוּ פִּרוּדָא, וְסָלִיק שֵׁם יהו\"ה מִנַּיְהוּ, וְעָאל יֵצֶר הָרָע דְּאִיהוּ סמא\"ל שָׂטָן, דַּיהו\"ה לָא שַׁרְיָא בְּפִרוּדָא, וְרָזָא דְמִלָּה (הושע י ב) חָלַק לִבָּם עַתָּה יֶאְשָׁמוּ, וּבְגִין דָּא צָרִיךְ קָרְבָּנָא מֵאִלֵּין מִינִין דְּחָב בְּהוֹן, לְקָרְבָא בְּהוֹן, אִינוּן אַרְבַּע יְסוֹדִין דְּאִית בְּהוֹן פִּרוּדָא, וּבְהַהוּא זִמְנָא דְמִתְקָרְבִין יְסוֹדִין דָּא לְגַבֵּי דָּא, מִיָּד נָחִית קוּדְשָׁא בְּרִיךְ הוּא עֲלַיְיהוּ וּבָרַח שָׂטָן, וְאִי לָא בָרַח הָא אֶשָּׁא דְקָרְבָּנָא אוֹקִיד לֵיהּ, הֲדָא הוּא דִכְתִיב (ויקרא ו ה) וְהָאֵשׁ עַל הַמִּזְבֵּחַ תּוּקַד בּוֹ.</p>\n<p>וְרָזָא דְקָרְבָּנִין (איוב י יא) עוֹר וּבָשָׂר תַּלְבִּישֵׁנִי וּבַעֲצָמוֹת וְגִידִים תְּסוֹכְכֵנִי, עוֹר אִיהוּ לְבוּשָׁא דְאָדָם, הֲדָא הוּא דִכְתִיב (בראשית ג כא) וַיַּעַשׂ יהו\"ה אלהי\"ם לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּישֵׁם, אִם זָכָה כָּתְנוֹת אוֹר מְרַקְמָן מִפִּקּוּדִין דַּעֲשֵׂה, דְאַגְרָא דִלְהוֹן לְעָלְמָא דְאָתֵי דְּאִיהוּ אוֹר הַגָּנוּז לַצַּדִּיקַיָּא, וְאִם לָא זָכָה מִשְׁכָא דְחִוְיָא דְכָלִיל אַרְבַּע יְסוֹדִין, דְּתַמָּן רְשִׁימִין פִּקּוּדִין דְּלָא תַעֲשֶׂה דְעָבַר בַּר נַשׁ עֲלַיְיהוּ, וּבְגִין דָּא אוּקְמוּהוּ מָארֵי מַתְנִיתִין עֲוֹנוֹתָיו שֶׁל אָדָם חֲקוּקִים לוֹ עַל עַצְמוֹתָיו, וּקְרִיבוּ דְמִשְׁכָא דְאָדָם פִּקּוּדִין דַּעֲשֵׂה, דְּאִינוּן קְרִיבוּ דְאַתְוָון דִּשְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>וַעֲלַיְיהוּ אִתְּמַר (ויקרא א ב) אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן, מִכֶּם וַדַּאי, לְאַפָּקָא מִשְׁכָא דְחִוְיָא דְבֵיהּ מְרַקְמִין פִּקּוּדִין דְּלֹא תַעֲשֶׂה, וְאָדָם דְּעָבַר עֲלַיְהוּ אִתְּמַר בֵּיהּ (תהלים קמד ד) אָדָם לַהֶבֶל דָּמָה יָמָיו כְּצֵל עוֹבֵר, (במדבר יט יד) אָדָם כִּי יָמוּת בְּאֹהֶל, כִּי יָמוּת וַדַּאי, וְדָא אִיהוּ קְרִיבוּ דְקָרְבָּנָא דְעִשָׂו יֵצֶר הָרָע, דְּאִתְּמַר בֵּיהּ (בראשית כז לא) יָקֻם אָבִי וְיֹאכַל מִצֵּיד בְּנוֹ. בָּשָׂר אִיהוּ שֶׁבֶר מִן שְׁבָרִים, וְאִיהוּ סוּמַק, מִסִּטְרָא דְחַיָּה דְאִיהוּ שׁוֹר, בָּשָׂר חַי בָּשָׁר טָהוֹר, וְאִית</p>"],[9500011279,"<p>אָחֳרָא דְבָשָׂר בַּשָּׂדֶה טְרֵיפָה דְשַׁרְיָא בֵיהּ רוּחַ הַטּוּמְאָה, מַלְאַךְ הַמָּוְת דְּרָכִיב עַל קַרְנוֹי שׁוֹר מוּעָד בָּשָׂר טָמֵא.</p>\n<p>עִִּצֶם, אִית עִִצֶם טָמֵא וְאִית עִִצֶם טָהוֹר, וּבָשָׂר דְּדַכְיוּ וְעִִצֶם דְּדַכְיוּ, עֲלַיְהוּ אִתְּמַר (בראשית ב כג) עִִצֶם מֵעֲצָמַי וּבָשָׂר מִבְּשָׂרִי, וְעִִצֶם אִיהוּ אַרְיֵה, גִּידִים אִיהוּ נֶשֶׁר, נֶשֶׁר, נִשְׁרָא דְּדַכְיוּ וְנִשְׁרָא דִמְסָאֲבוּ, עִִצֶם וּבָשָׂר וְגִידִים עֲלַיְיהוּ שַׁרְיָא בְרָכָה וּקְדוּשָׁה וְיִחוּד, דְּאִינוּן כֹּהֵן לֵוִי וְיִשְׂרָאֵל, בְּעִִצֶם כַּד שַׁרְיָא בְרָכָה בֵּיהּ, מִיָּד (יחזקאל לז ז) וַתִּקְרְבוּ עֲצָמוֹת עִִצֶם אֶל עַצְמוֹ, מִתְקָרְבִין וּמִתְקַשְּׁרִין דָּא בְדָא בְקָרְבָּנָא, וּמִיָּד נָחִית עֲלַיְיהוּ מִשְׁחָא וְשַׁרְיָיא עֲלַיְיהוּ בְּרָכָה, בָּשָׂר שַׁרְיָא עֲלֵיהּ קְדוּשָׁה, דְאִיהִי מִסִּטְרָא דִלְוִיִּם, הֲדָא הוּא דִכְתִיב וְקִדַּשְׁתָּ אֶת הַלְוִיִּם, מִיָּד מִתְקָרְבִין עַרְקִין דִּדְמָא לְגַבֵּי לִבָּא, דְּבִרְכָאָן מִכַּהֲנֵי אִינוּן, הֲדָא הוּא דִכְתִיב (במדבר ו כג) דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו לֵאמֹר כֹּה תְבָרַכוּ. גִּידִים מִיִּשְׂרָאֵל, וְאִינוּן יִחוּדָא וּקְדוּשָׁה וְקִשּׁוּרָה דְגַרְמִין וּבִשְׂרָא, וְכַד מִתְקַשְּׁרִין בְּתַרְוַיְיהוּ אִתְקְרִיאוּ יִחוּד וְיִחוּד אִיהוּ בְּיִשְׂרָאֵל, הֲדָא הוּא דִכְתִיב (דברים ו ד) שְׁמַע יִשְׂרָאֵל יהו\"ה אלהינ\"ו יהו\"ה אֶחָד.</p>\n<p>מִשְׁכָא אִיהוּ דְמוּת אָדָם מַלְכוּת, כָּל דִּיּוֹקְנִין אִתְחַזְיָין בָּהּ, וְאִיהִי כְּלִילָא מִבִּשְׂרָא וְגִידִין וְגַרְמִין, וְאִיהִי תְּמוּנַת כֹּל, וְאִיהִי בְּרָכָה וּקְדוּשָׁה וְיִחוּד, כֹּהֲנִים וּלְוִיִּם וְיִשְׂרְאֵלִים, דְּאִינוּן קְשִׁירָן בִּתְלַת אֲבָהָן, דְּאִתְּמַר בְּהוֹן הָאָבוֹת הֵן הֵן הַמֶּרְכָּבָה, בַּבָּשָׂר כַּד מִתְקַדְּשָׁא, נָחִית עֲלֵיהּ דָּם טָהוֹר, וְגִידִים כַּד מִתְיַחֲדִין נָחִית עֲלַיְיהוּ רוּחָא קַדִּישָׁא, גַּרְמִין נָחִית עֲלַיְיהוּ מַיִּין דְּדַכְיוּ, דָא אִיהוּ רָזָא דְקָרְבָּנִין. חָדָא רַבִּי אֶלְעָזָר וְחָדוּ חַבְרַיָּא וְאָמְרוּ אִילוּ לָא אֲתֵינָא לְהַאי עָלְמָא אֶלָּא לְמִשְׁמַע דָּא דַיי.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן בְּרִי, וְעוֹד בְּרָזָא דְקָרְבָּנִין, לִבָּא אִיהוּ מִזְבֵּחַ דְּבֵיהּ דָּם דְּקָרְבָּנִין, וְעַל דָּא אִתְּמַר (שמות כ כא) וְזָבַחְתָּ עָלָיו, אִם זָכוּ אַרְיֵה הֲוָה נָחִית לְמֵיכַל קָרְבָּנָא, וְאִי לָא כַּלְבָּא נָחִית, וּבְאָן אֲתַר בְּכָבֵד, דְּתַמָּן מָרָה גֵּיהִנָּם, דְּאִיהִי עֲלוּקָה דְאִית לָהּ תְּרֵי בָנוֹת הַב הַב, כְּמָה דְאַתְּ אָמַר (משלי ל טו) לַעֲלוּקָה וכו', וְכַלְבָּא בְהוֹן צָוַוח הַב הַב, וּמָרָה אִיהִי גֵיהִנָּם, חַרְבָּא דְמַלְאַךְ הַמָּוְת דְּאִית לָהּ תְּרֵי פִּיּוֹת כְּגַוְונָא דְגֵיהִנָּם, דְּאִתְּמַר בָּהּ (שם) לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב, כְּגַוְונָא דָא אִתְּמַר בְּחַרְבָּא (שם ה ד) וְאַחֲרִיתָהּ מָרָה כַלַּעֲנָה חַדָּה כְּחֶרֶב פִּיּוֹת.</p>\n<p>וְכָבֵד אִיהוּ סמא\"ל, מָרָה סַם מָוְת דִּילֵיהּ, כַּד שָׁלְטָא מָרָה עַל עַרְקִין דִּילָהּ וּמִתְגַּבְּרָא בְחוֹבִין, אִתְּמַר בְּפִרְקִין דְּכָבֵד וּמָרָה, (שמות טו כג) וַיָּבֹאוּ מָרָתָה וְלֹא יָכְלוּ לִשְׁתּוֹת מַיִם מִמָּרָה כִּי מָרִים הֵם, בְּהַהוּא זִמְנָא אִינוּן עַרְקִין דְּלִבָּא בְדוֹחֲקָא וּמִתְטַמְּרִין בְּלִבָּא, כְּגַוְונָא דְנֹחַ וְאִתְּתֵיהּ וּבְנוֹי וְחֵיוָון וּבְעִירִין וְעוֹפִין דְּמִתְטַמְּרִין בְּתֵיבָה, וְלִבָּא אִיהוּ בְדוֹחֲקָא בְהוֹן, דְּאִם מָרָה מָטָא לְלִבָּא מִיָּד יָמוּת בַּר נַשׁ, וּמָרָה לָא מִתְגַּבְּרָה עַל יִשְׂרָאֵל דְּאִינוּן לִבָּא אֶלָּא בְחוֹבִין, אִי חָזְרִין בִּתְיוּבְתָּא דְאִיהִי נִשְׁמַת חַיִּים שְׁכִינְתָּא עִלָּאָה, הָא אַסְוָותָא תְּהֵא לְלִבָּא וּלְעַרְקִין דִּילָהּ, וְאִתְּמַר בְּהוֹן (שם) וַיִּמְתְּקוּ הַמָּיִם, וְאִתְּסִין עַרְקִין (גופא) וְאֵבָרִים דִּילֵיהּ.</p>\n<p>טְחוֹל דָּא לִילִי\"ת אִימָּא דְעִרֶב רַב, שְׂחוֹק הַכְּסִיל, מָאן כְּסִיל דָּא אֵל אַחֵר סמא\"ל, וְעִרֶב רַב אִינוּן בְּנָהָא, דְאִינוּן מְעוּרָבִין בְּיִשְׂרָאֵל רְשָׁעִים גְּמוּרִים, וַעֲלַיְיהוּ אִתְּמַר אִם רָאִיתָ רָשָׁע שֶׁהַשָּׁעָה מְשַׂחֶקֶת לוֹ אַל תִּתְגָרֶה בּוֹ, עֲלַיְיהוּ אִתְּמַר (חבקוק א יג) לָמָּה תַבִּיט בּוֹגְדִים תַּחֲרִישׁ בְּבַלַּע רָשָׁע צַדִּיק מִמֶּנּוּ, רָשָׁע דָּא כְסִיל, עִרֶב רַב בְּגָלוּתָא אִינוּן רָשָׁע, בְּבַלַּע צַדִּיק מִמֶּנּוּ, דָא יִשְׂרָאֵל, וּמָאן גָּרִים דְּבָלַע לוֹן, בְּגִין דְּלַאו אִינוּן צַדִּיקִים גְּמוּרִים, כְּמָה דְאִתְּמַר צַדִּיק מִמֶּנּוּ בּוֹלֵעַ אֲבָל צַדִּיק גָּמוּר אֵינוֹ בּוֹלֵעַ.</p>\n<p>וּטְחוֹל אִיהוּ לִילִי\"ת, (משלי ג לג) מְאֵרַת ה' בְּבֵית רָשָׁע, וְאִיהִי אַסְכְּרָה לְרַבְיֵי דְאִינוּן חַיָּיבַיָּא, חַיְיכַת בְּהוֹן בְּעוּתְרָא בְהַאי עָלְמָא,</p>"],[9500011280,"<p>וּלְבָתַר קְטִילַת בְּהוֹן, וְאַמַּאי אִתְקְרִיאוּ רַבְיֵי, בְּגִין דְּלֵית בְּהוֹן דַּעַת לְאִשְׁתֵּזָבָא מִינָהּ, אֲבָל לֵב מֵבִין אִשְׁתֵּזַב מִינָהּ, דְּתַמָּן צַדִּיק, וְרָזָא דְמִלָּה (קהלת ז כו) טוֹב לִפְנֵי הָאלהי\"ם יִמָּלֵט מִמֶּנָּה, וְחוֹטֵא יִלָּכֶד בָּהּ.</p>\n<p>כְּלָיוֹת אִינוּן יוֹעֲצוֹת אִם זָכוּ עָאל בְּהוֹן נְבוּאָה דְאִיהִי (משלי כ כז) נֵר יהו\"ה נִשְׁמַת אָדָם, וְאִתְעֲבִידוּ נְבִיאִים, וְאִינוּן יוֹעֲצִים לְטָב, וְאִית בְּהוֹן עִצָה וְתוּשִׁיָּה.</p>\n<p>כַּנְפֵי רֵיאָה, אִם זָכוּ שַׁרְיָא בְהוֹן רוּחַ קוּדְשָׁא, וְאִתְּמַר בְּהוֹן (ישעיה יא ב) וְנָחָה עָלָיו רוּחַ יהו\"ה רוּחַ חָכְמָה וּבִינָה רוּחַ עִצָה וּגְבוּרָה רוּחַ דַּעַת וְיִרְאַת יהו\"ה, וַעֲלַיְיהוּ אִתְּמַר (שמות כה כ) וְהָיוּ הַכְּרֻבִים פּוֹרְשֵׂי כְנָפַיִם, הַכְּרוּבִים כְּגוֹן צוּרַת אָדָם, פּוֹרְשֵׂי כְנָפַיִם לָקֳבֵל תְּלַת חֵיוָון דְּפָרְשִׂין גַּדְפִין לְקִבְלֵיהּ דְּאָדָם, וְאִינוּן שִׁית גַּדְפִין, תְּרֵין לְכָל חַיָּה, מִסִּטְרָא דִשְׁכִינְתָּא גַדְפִין דְּחֵיוָון מְרוּבָּעִים, שִׁית גַּדְפִין לָקֳבֵל שֵׁשׁ מַעֲלוֹת לַכִּסֵּא, אַרְבַּע גַּדְפִין לָקֳבֵל כָּרְסַיָּא מְרוּבָּע, פֹּרְשֵׂי כְנָפַיִם לְמַעִִלָה סֹכְכִים בְּכַנְפֵיהֶם עַל הַכַּפֹּרֶת, דָּא כַּפֹּרֶת דְּלִבָּא קֹדֶשׁ קֻדְשִׁין, וְדָא לִבָּא.</p>\n<p>נֶפֶשׁ רוּחַ נְשָׁמָה, כֹּהֵן לֵוִי וְיִשְׂרָאֵל, כֹּהֵן אִיהוּ נְשָׁמָה, אִם זָכָה נֵר יהו\"ה נֵר הֲוָה נָהִיר בֵּיהּ מִלִּבָּא כַּשֶּׁמֶשׁ זוֹרַחַת, וְרוּחָא דְקוּדְשָׁא הֲוָה נָפִיק מִבֵּין גַּדְפוֹי דִכְּרוּבִין דְּאִינוּן כַּנְפֵי רֵיאָה, וַהֲוָה מְמַלֵּיל עִמֵּיהּ, וְאִם לַאו נוּרָא, וְדָא נֶפֶשׁ הֲוָה דָלֵיק, וְנָפִיק אֶשָּׁא מִלִּבָּא וְאוֹקִיד לֵיהּ. קַרְקְבָנָא וְקֵיבָה כַּד נָאִים אִתְקְרֵי קֵיבָה יָשֵׁן.</p>\n<p>וְאִית שֵׁינָה לְטָב וְאִית שֵׁינָה לְבִישׁ, לְטָב כְּגוֹן חֲלוֹם דְּאִיהִי סֻלָּם (נ\"א כגון חלום) דְּחָזָא יַעֲקֹב, וּבֵיהּ דָּבִיק קָנֶה, וְשִׁית עִזְקִין דְּקָנֶה אִיהוּ שִׁית דַּרְגִּין דִּנְבוּאָה, וְסָלְקִין לְשִׁתִּין נִשְׁמֵי, דַהֲוָה נָאִים בְּהוֹן דָּוִד, דְּהָכִי אוּקְמוּה, דָוִד הֲוָה מִתְנַמְנֵם כַּסּוּס, וְסוּס לָא נָאִים אֶלָּא שִׁתִּין נִשְׁמֵי, וְאִית שֵׁינָה לְבִישׁ חֶלְמָא בִּישָׁא, דְאִתְּמַר בֵּיהּ לְגַבֵּי אַבְרָהָם, (בראשית טו יב) וְתַרְדֵּמָה נָפְלָה עַל אַבְרָם, וְהִנֵּה אֵימָה חֲשֵׁכָה גְדֹלָה נֹפֶלֶת עָלָיו, וְהָא אוּקְמוּהָ בְאַרְבַּע גָּלִיּוֹת, וּבְגִין דַּחֲלוֹם יֵיתֵי בִתְרֵין דַּרְגִּין, אוּקְמוּהוּ קַדְמָאִין, כְּמָה דְאִי אֶפְשַׁר לְבָר בְּלֹא תֶּבֶן כַּךְ אִי אֶפְשַׁר לְחֶלְמָא בְלֹא דְבָרִים בְּטֵלִים, בְּגִין דְּיֵיתֵי חֶלְמָא כַּאן עַל יְדֵי מַלְאָךְ, כַּאן עַל יְדֵי שֵׁד, בְּגִין דְּחֶלְמָא אִיהוּ מִסִּטְרָא דְאִילָנָא דְטוֹב וָרָע, אֲבָל מִסִּטְרָא דְאִילָנָא דְחַיֵּי לָא אַתְיָא (עליה אלא דקיבה) אֶלָּא עַל יְדֵי קֵיבָה דְקוּדְשָׁא בְּרִיךְ הוּא דְאִיהִי שְׁכִינְתָּא דִילֵיהּ, וְלֵית תַּמָּן קֵיבָה רַע דְּאִיהוּ שֵׁד.</p>\n<p>קָרְקְבָן טוֹחֵן, אִי בַּר נַשׁ זַכָּאָה אִיהוּ טוֹחֶנֶת מָן לְצַדִּיקִים, דְּאִינוּן אֵבָרִים קַדִּישִׁין בְּפִקּוּדִין דַּעֲשֵׂה, וְאִי לָא אָזְלִין בְּפִקּוּדִין טָבִין, מִתְפַּרְנְסִין בְּלֶחֶם הַקְּלוֹקֵל מְזוֹנָא קַלָּא בַּקָּלוֹן. וִושֶׁט (במדבר יא ח) שָׁטוּ הָעָם וְלָקְטוּ, שָׁטִין (שטיין) לָקְטִין בְּשִׁטּוּתָא, וְטָחֲנוּ בָרֵיחַיִם בְּדוֹחֲקָא, אִלֵּין אִינוּן טוֹחֲנוֹת בְּפוּמָא, אוֹ דָכוּ בַּמְּדוֹכָה דָא חֵיךְ, וּבִשְּׁלוּ בַּפָּרוּר דָּא אִצְטוּמְכָא.</p>\n<p>בְּרִי, רָזָא עִלָּאָה הָכָא, אִם זָכוּ יִשְׂרָאֵל הֲוָה נָחִית לוֹן אוֹרַיְיתָא מִן שְׁמַיָּא בְלָא דוֹחֲקָא, וְלָא הֲווֹ צְרִיכִין לְאַלָּפָא חַד לְחַבְרֵיהּ, הֲדָא הוּא דִכְתִיב (שמות טז ד) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם, דְּלֵית לֶחֶם אֶלָּא אוֹרַיְיתָא, לָא זָכוּ בְּגִין עִרֶב רַב דְּאִינוּן שַׁטְיָּין, אִתְּמַר בְּהוּ שָׁטוּ הָעָם וְלָקְטוּ, דְיִטְרְחוּן לְאוֹלָפָא דָא לְדָא, לְפַרְנָסָה כָּל חַד בְּדוֹחֲקָא, וּלְחַכִּימַיָּא בִרְמִיזָא. אֲבָל לְעָתִיד לָבֹא יִתְמְחוּן עִרֶב רַב מֵעָלְמָא, וְאִתְּמַר בְּהוֹן (ירמיה ל א לג) וְלֹא יְלַמְּדוּ עוֹד אִישׁ אֶת אָחִיו וְגוֹמֵר, וּבְגִין דָּא וִושֶׁט אִיהוּ לְבִישׁ וְאִיהוּ לְטָב, חִוָּור וְסוּמַק, דִּינָא וְרַחֲמֵי.</p>\n<p>וּבְרִי, בְּוַדַּאי אִינוּן שְׁלוּחַיָּא דְצִבּוּרָא, צְרִיכִין כַּד קָרָאן סֵפֶר תּוֹרָה דְּיַחְתְּכוּן מִלִּין, וְלָא יֵימְרוּן לְהוֹן בְּהַלְעָטָה, כְּגַוְונָא דְעִרֶב רַב דְּאִתְּמַר בְּהוֹן (במדבר יא יג) הַבָּשָׂר עוֹדֶנּוּ בֵּין שִׁנֵּיהֶם, וַהֲווֹ אָכְלִין בְּהַלְעָטָה, וּכְגַוְונָא דְעִשָׂו דְּאִתְּמַר בֵּיהּ (בראשית כה ל) הַלְעִיטֵנִי נָא, וְלָא הֲווֹ טָחֲנִין לֵיהּ, אִתְּמַר בְּהוֹן (במדבר יא לג) וְאַף יהו\"ה חָרָה בָעָם.</p>\n<p>הַדְרָא דְכַנְתָא דָא אִיהוּ נָחָשׁ בָּרִיחַ נָחָשׁ עֲקַלָּתוֹן, דִּזְמִינִין צַדִּיקַיָּיא</p>"],[9500011281,"<p>לְמֵיכַל לֵיהּ. וְאִית חֵלֶב טָמֵא דְאִיהוּ נָחָשׁ, דְּאִיהוּ אֲסִיר לְמֵיכַל עַמָּא קַדִּישָׁא, בְּגִין דַּעֲלֵיהּ אִתְּמַר (בראשית ג יד) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה.</p>\n<p>(זהו תיקון כ\"ה)</p>\n<p>בְּרֵאשִׁית תַּמָּן יֵ\"שׁ, (משלי ח כא) לְהַנְחִיל אוֹהֲבַי יֵשׁ וְאוֹצְרוֹתֵיהֶם אֲמַלֵּא, וּבְגִין דְּתַמָּן אוֹצָר דְּאִיהִי יִרְאַת יהו\"ה, מִנֵּיהּ אִתְמַלְיָא לְצַדִּיקַיָּא, וְאִינוּן דָּחֲלִין לְקוּדְשָׁא בְּרִיךְ הוּא יָרְתִין הַאי יֵשׁ, וְעִרְבוּבְיָא בִישָׁא לָא הֲווֹ דָחֲלִין לְקוּדְשָׁא בְּרִיךְ הוּא אֶלָּא בְגִין עוּתְרָא, וַהֲווֹ מְנַסִּין לֵיהּ, כְּגַוְונָא דָא (שמות יז ז) הֲיֵשׁ יהו\"ה בְּקִרְבֵּנוּ אִם אָיִן, וְכָל אִינוּן דִּמְנַסִּין לְקוּדְשָׁא בְּרִיךְ הוּא וְדָחֲלִין לֵיהּ בְּעוּתְרָא וְלָא דָחֲלִין מִנֵּיהּ בַּעֲנִיּוּתָא כְּמוֹ בְּעוּתְרָא, לַאו אִינוּן אֶלָּא עִרְבוּבְיָא בִישָׁא, דְּאִית יִרְאָה וְאִית יִרְאָה, אִית אַהֲבָה וְאִית אַהֲבָה, אִית מָאן דְּדָחִיל לְקוּדְשָׁא בְּרִיךְ הוּא בְּגִין דְּיֵחוּן בְּנוֹי אוֹ דְלָא נָחִית לַעֲנִיּוּתָא, אוֹ דְרָחִים לֵיהּ בְּגִין דִּיְהִיב לֵיהּ עוּתְרָא, וּמְנַסֶּה לֵיהּ כְּגוֹן נַעֲבֵיד הַאי פִּקּוּדָא הָכִי, וְנֶחזֵי הֲיֵשׁ יהו\"ה בְּקִרְבֵּנוּ וְיָהִיב לָן אַגְרָא בְגִינֵיהּ אִם אָיִן, דְּאִי לָא יָהִיב לֵיהּ אַגְרָא בְגִינָהָא לָא רָחִים לֵיהּ, וְלָא יָהִיב לֵיהּ צְדָקָה וְלָא יַעֲבִיד פִּקּוּדָא, וּמְנַסֵּי לְקוּדְשָׁא בְּרִיךְ הוּא בְּכָל פִּקּוּדָא וְעוֹבָדָא, בְּוַדַּאי הַאי אִיהוּ מֵאִלֵּין עִרְבוּבְיָא בִישָׁא, דְאִתְּמַר בְּהוֹן הֲיֵשׁ יהו\"ה בְּקִרְבֵּנוּ אִם אָיִן.</p>\n<p>אֶלָּא רְחִימוּ וּדְחִילוּ דְקוּדְשָׁא בְּרִיךְ הוּא, שְׁלִים בְּכָל פִּקּוּדָא וּפִקּוּדָא דְעָבִיד, בֵּין דִּיְהִיב לֵיהּ אַגְרָא בְטִיבוּ בֵין דְּלָא יְהִיב לֵיהּ, וּבְגִין דָּא מַנִּי בְאוֹרַיְיתָא (דברים ו ד) וְאָהַבְתָּ אֵת יהו\"ה אלהי\"ך בְּכָל לְבָבְךָ וּבְכָל נַפְשְׁךָ וּבְכָל מְאֹדֶךָ, וְאוּקְמוּהוּ קַדְמָאִין, אִם חָבִיב עָלֶיךָ נַפְשְׁךָ מִמָּמוֹנְךָ לְכַךְ נֶאֱמַר בְּכָל נַפְשְׁךָ, וְאִם חָבִיב עָלֶיךָ מָמוֹנְךָ מִנַּפְשְׁךָ לְכַךְ נֶאֱמַר בְּכָל מְאֹדֶךָ, דְּאִית בַּר נַשׁ דְּצַלִּי וְאָזִיל בְּכָל פִּקּוּדִין דְּלָא יָהִיב עֲלַיְיהוּ אַגְרָא, וְאִם הֲוָה יָהִיב אַגְרָא עֲלַיְיהוּ לָא הֲוָה עָבִיד לוֹן, דְּוַדַּאי סַגִּיאִין אִינוּן מִבְּנֵי נָשָׁא דְאִינוּן עֲתִירִין בְּעוּתְרָא סַגִּיא, וְאִינוּן חֲבִיבִין עוּתְרָא דִלְהוֹן יַתִּיר מִנִּשְׁמָתָא דִלְהוֹן, דְּעוּתְרָא דְנַפְשָׁא אִיהוּ פִּקּוּדִין טָבִין בְּעָלְמָא דְאָתֵי, וְעוּתְרָא דְגוּפָא מָמוֹנָא וְעִדּוּנָא בְעָלְמָא דֵין.</p>\n<p>וְאִינוּן דִּמְחַבְבִין מָמוֹנָא מִנַּפְשָׁא, אִם הֲווֹ יָהֲבִין לֵיהּ כָּל אוֹרַיְיתָא בְּמֵאָה זוּזֵי לָא הֲווֹ יָהֲבִין לְהוּ בְּגִינָהּ, בְּגִין דְּמָמוֹנָא חָבִיב עֲלַיְיהוּ מִנַּפְשָׁא, וּמַה דְּדָחִיל וְרָחִים לֵיהּ לַאו אִיהוּ אֶלָּא בְגִין מָמוֹנָא, הַאי דְּשַׁוִּי מָמוֹנָא עִקָּרָא וְאוֹרַיְיתָא דְרָחִים קוּדְשָׁא בְּרִיךְ הוּא טָפֵל, הַאי רְחִימוּ וּדְחִילוּ לָא חָשִׁיב לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא עִקָּרָא דִרְחִימוּ וּדְחִילוּ דְקוּדְשָׁא בְּרִיךְ הוּא, דְאַף עַל גַּב דְּאִיהוּ רָחִים מָמוֹנֵיהּ מִנַּפְשֵׁיהּ, דְּיִרְחֵים לֵיהּ בְּמָמוֹנֵיהּ, בַּמֶּה דְּאִיהוּ חָשִׁיב עֲלֵיהּ, וְלָא בְטָפֵל דִּילֵיהּ, לְכַךְ נֶאֱמַר בְּכָל מְאֹדֶךָ, וְכֵן מָאן דְּחָשִׁיב נַפְשֵׁיהּ מִמָּמוֹנֵיהּ, וַהֲוָה יָהֵיב כָּל מָמוֹנָא דְעָלְמָא וְלָא הֲוָה נָזִיק אֲפִילוּ בְּאֵבָרָא זְעִירָא דְאִית בֵּיהּ, לְכַךְ נֶאֱמַר בְּכָל נַפְשְׁךָ בְּמַאי דְרָחִים לֵיהּ.</p>\n<p>(זהו תקון כ\"ו)</p>\n<p>בְּרֵאשִׁית (ישעיה סו טז) כִּי בָאֵשׁ יהו\"ה נִשְׁפָּט, אלהי\"ם מָארֵי דְּדִינָא, וַעֲלֵיהּ אִתְּמַר (שמות כב כז) אלהי\"ם לֹא תְקַלֵּל, בְּוַדַּאי כְּמָה דִלְעִילָא אִתְּמַר (תהלים עה ח) כִּי אלהי\"ם שֹׁפֵט זֶה יַשְׁפִּיל וְזֶה יָרִים, כַּךְ אִיהוּ צָרִיךְ לְמֶהֱוִי דַיָּינָא לְתַתָּא, לְדָא יַשְׁפִּיל בְּדִינָא וּלְדָא יָרִים, כְּפוּם</p>"],[9500011282,"<p>עוֹבָדוֹי, לְדָא מַטֶּה כְּלַפֵּי חֶסֶד, לְדָא כְּלַפֵּי גְבוּרָה, אֱמֶת בְּאֶמְצָעִיתָא, וּבְגִין דָּא אִתְקְרֵי דַּיָּין אֱמֶת, אלהי\"ם הַכִּסֵּ\"א בְּחוּשְׁבָּן, דְּתַמָּן י\"ה דְּאִיהִי חָכְמָה וּבִינָה, זֶה שְּׁמִי עִם י\"ה שְׁסָ\"ה מִסִּטְרָא דִשְׂמָאלָא, וְדָא י\"ה מִן אלהי\"ם, ה' עַל י' נוּקְבָא.</p>\n<p>וְכַד דַּיָּין אִיהוּ דָן, צָרִיךְ לְמֶהֱוִי אִיהוּ יָתֵיב וּבַעֲלֵי דִינָא קַיְימִין, כְּגַוְונָא דִלְעִילָא, דְאִתְּמַר בְּקוּדְשָׁא בְּרִיךְ הוּא (איוב א ו) וַיָּבֹאוּ בְּנֵי הָאלהי\"ם לְהִתְיַצֵּב עַל יהו\"ה, אִיהוּ יָתֵיב, וְאִינוּן קַיְימִין לְמִתְּבַע דִּינָא, וּבְגִין דְּשָׂטָן יֵעוּל בֵּינַיְיהוּ לְמִתְּבַע חוֹבֵיהוֹן דִּבְנֵי יִשְׂרָאֵל, אִינוּן בְּמַטּוּלָא עֲלֵיהּ, עַד דַּהֲוָה דָן לְהוֹן וְדָא אִיהוּ לְהִתְיַצֵּב עַל יהו\"ה, וְעוֹד לְהִתְיַצֵּב עַל יהו\"ה, לְשַׁאֲלָא וּלְמִתְּבַע דִּינָא לְגַבֵּי (נ\"א קמי) קוּדְשָׁא בְּרִיךְ הוּא יהו\"ה, כַּד נָהִיג עָלְמָא בְּרַחֲמִין, וּמְקַטְרְגִין וְתָבְעִין דִּינָא, וְדָא אִיהוּ לְהִתְיַצֵּב עַל יהו\"ה. וְתוּ לְהִתְיַצֵּב עַל יהו\"ה, יהו\"ה עַמּוּדָא דְאֶמְצָעִיתָא, דְשָׁאֲלִין וְתָבְעִין דִּינָא מִגְּבוּרָה בֵּי דִינָא רַבְרְבָא, דְקַיְימָא עַל עַמּוּדָא דְאֶמְצָעִיתָא, וְדָא הוּא עַל יהו\"ה, עַל דִּמְקָרְבִין דִּינִין קֳדָם גְּבוּרָה אִתְּמַר בְּהוֹן לְהִתְיַצֵּב עַל יהו\"ה, דְּאַף עַל גַּב דְּבְנוֹי אִינוּן יִשְׂרָאֵל לֵית לֵיהּ רְשׁוּ לְאַעֲבָרָא עַל דִּינָא, דְּאוֹרַיְיתָא בְּדִינָא אִתְיְיהִיבַת, וְאוֹמֵי עֲלָהּ דְּלָא יַעֲבַר עֲלָהּ, וּלְגַבֵּי דִינָא גְּבוּרָה אִיהִי בְּאֶמְצָעִיתָא, וְחֶסֶד מִימִינָא, וְעַמּוּדָא דְּאֶמְצָעִיתָא מִשְּׂמָאלָא, וְכָל דִּינִין מֵהַאי אֲתַר תַּלְיָין, וְכָל סְפִירָן כֻּלְּהוּ אִתְקְרִיאוּ דִינִין גְּבוּרָה וַאֲפִילוּ יהו\"ה.</p>\n<p>דִּינָא קַדְמָאָה חֲדָא אִתְקְרֵי דִין לָדוּן בְּחֶנֶק, וְאִתְּמַר (דברים כא כג) לֹא תָלִין נִבְלָתוֹ עַל הָעִץ. אָמַר לֵיהּ אֶלְעָזָר בְּרִי, הָכָא צָרִיךְ לְחַדְּשָׁא מִלִּין, אִית עִץ וְאִית עִץ, הֲדָא הוּא דִכְתִיב (שם כ יט) כִּי הָאָדָם עִץ הַשָּׂדֶה, וְאִית אָדָם דְּאִיהוּ עִץ הַדַּעַת טוֹב וָרָע, וְחוֹבָא דְאָדָם אִיהִי נִבְלָתוֹ דְאָדָם קַדְמָאָה דְאִיהִי עִץ הַחַיִּים, לָא צָרִיךְ לְתַלְיָיא בֵיהּ חוֹבָא דָא, הֲדָא הוּא דִכְתִיב לֹא תָלִין נִבְלָתוֹ עַל הָעִץ, דְּמָאן דְּאָכַל מֵעִץ דִּילֵיהּ דְּאִיהוּ עִץ הַחַיִּים, אִתְּמַר בֵּיהּ (בראשית ג כב) וְאָכַל וָחַי לְעוֹלָם.</p>\n<p>וְעוֹד לֹא תָלִין נִבְלָתוֹ עַל הָעִץ, עִץ דְּהָכָא דָא תַלְמִיד חָכָם דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא דְּאִיהִי עִץ הַחַיִּים, הֲדָא הוּא דִכְתִיב (משלי ג יח) עִץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ, לֹא תָלִין בּוֹ נִבְלָתוֹ, דְאִיהִי חוֹבָה דְּחָב בְּיוֹמָא לֹא תָלִין עִמֵּיהּ בַּלַּיְלָה, דְמִיָּד יְתוּב בִּתְיוּבְתָּא, כְּמָה דְאוּקְמוּהָ מָארֵי מַתְנִיתִין אִם רָאִיתָ תַּלְמִיד חָכָם שֶׁחָטָא בַּיּוֹם אַל תְּהַרְהֵר אַחֲרָיו בַּלַּיְלָה, דְוַדַּאי עָשָׂה תְּשׁוּבָה, (נ\"א שמא עשה תשובה, שמא סלקא דעתך, אלא אימא ודאי עשה תשובה).</p>\n<p>וְעוֹד לֹא תָלִין נִבְלָתוֹ עַל הָעִץ, דָּא תַּלְמִיד חָכָם, נִבְלָתוֹ דָּא בַּת עַם הָאָרֶץ דְּאִיהִי רִיחֲשָׁא, דְאִם אַנְתְּ תַּלְיָא לָהּ בֵּיהּ, אוֹ קוֹבְרָהּ אוֹ קוֹבְרָתוֹ, וְדָא אִיהוּ (דברים כא כג) כִּי קָבוֹר תִּקְבְּרֶנּוּ, כִּי קָבוֹר הוּא לָהּ אוֹ תִּקְבְּרֶנּוּ אִיהִי לֵיהּ, וְאִתְּתָא דָא לַאו אִקְרֵי זִוּוּגָא וְיִחוּדָא דִילֵיהּ, אֶלָּא אִיהִי כְּמַטּוּלָא תַלְיָא עֲלֵיהּ, כְּחִוְיָא קָשִׁיר עַל קְדָלֵיהּ, וּבְגִין דָּא (שם) כִּי קִלְלַת אלהי\"ם תָּלוּי, דְּאִיהִי קְלָלָה, דְקַטִּילַת לֵיהּ אוֹ אַיְיתֵי לֵיהּ לִידֵי עֲנִיּוּתָא.</p>\n<p>דָבָר אַחֵר לֹא תָלִין נִבְלָתוֹ עַל הָעִץ, דָּא שַׁבָּת, דְּיָרִית בֵּיהּ בַּר נַשׁ נְשָׁמָה יְתֵירָה, לָא צָרִיךְ לְאִתְחַזְיָא קֳדָמָהָא נַפְשָׁא דְשָׁלְטָא בְּבַר נַשׁ בְּיוֹמִין דְּחוֹל, בִּמְלָאכָה דְאִיהִי אֲסוּרָה בְשַׁבָּת, אֶלָּא קָבוֹר תִּקְבְּרֶנּוּ בַּיּוֹם הַהוּא, דְלָא אִתְחַזְיָא קֳדָם זָכוֹר וְשָׁמוֹר דְּשַׁבָּת, וּבְגִינָהּ אִתְּמַר (שמות ה ה) שַׁל נְעָלֶיךָ מֵעַל רַגְלֶיךָ כִּי הַמָּקוֹם אֲשֶׁר אַתָּה עוֹמֵד עָלָיו אַדְמַת קֹדֶשׁ הוּא, (דברים כא כג) וְלֹא תְטַמֵּא אֶת אַדְמָתְךָ, דְנִשְׁמָתָא יְתֵירָה אִיהִי אֶרֶץ יִשְׂרָאֵל דִּלְעִילָא, אַדְמַת קֹדֶשׁ, דְּאִתְּמַר בָּהּ (ירמיה ב ג) קֹדֶשׁ יִשְׂרָאֵל לַיהו\"ה.</p>\n<p>וְעוֹד לֹא תָלִין נִבְלָתוֹ עַל הָעִץ דָּא בַר נַשׁ דְּאִיהוּ נָבָל, עֲלֵיהּ אִתְּמַר כָּל הַמַּעֲמִיד תַּלְמִיד דְּלַאו אִיהוּ הָגוּן כְּאִלּוּ מַעֲמִיד אֲשֵׁרָה, וּבְגִין דָּא לֹא תָלִין נִבְלָתוֹ עַל הָעִץ דְּאִיהוּ עִץ הַחַיִּים. דָּבָר אַחֵר לֹא תָלִין וְגוֹמֵר, הָעִץ אִלֵּין יִשְׂרָאֵל דְּאִתְּמַר בְּהוּ</p>"],[9500011283,"<p>(ישעיה סה כב) כִימֵי הָעִץ יְמֵי עַמִּי, חוֹבָא דְעָבְדוּ עַם נָבָל, לָא תְהֵא תַלְיָא לֵיהּ בְּיִשְׂרָאֵל, דְּכַד עֲבַדוּ יָת עִִגְלָא חַשִּׁיב מֹשֶׁה דְּיִשְׂרָאֵל עֲבַדוּ לֵיהּ, וְאָמַר (שמות לב יא) לָמָה יהו\"ה יֶחרֶה אַפְּךָ בְּעַמֶּךָ, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא (שם) לֶךְ רֵד כִּי שִׁחֵת עַמְּךָ, מִיָּד נָחִית וְחָזָא עִגֶל דִּיּוֹקְנָא דְשׁוֹר וַחֲמוֹר, שָׁאִיל לֵיהּ מָאן עָבַד לָךְ, אָמַר חֲמוֹר, עִרֶב רַב (יחזקאל כג כ) אֲשֶׁר בְּשַׂר חֲמוֹרִים בְּשָׂרָם, שׁוֹר אָמַר נַמִּי הָכִי, טַבַּעַת דַּעֲלָהּ מַזָּל שׁוֹר בְּזִמְנָא דְאִתְּמַר בְּעִרֶב רַב (שמות לב ג) וַיִּתְפָּרְקוּ כָּל הָעָם אֶת נִזְמֵי הַזָּהָב, אִזְדַּמְנַת תַּמָּן, וְאֶרְמֵי כֹּלָּא אַהֲרֹן בְּנוּרָא, וְנָפְקַת עִִגְלָא דִיּוֹקְנָא דְשׁוֹר וַחֲמוֹר, בְּהַהוּא זִמְנָא צָוְוחַת רוּחַ הַקֹּדֶשׁ וְאָמְרַת, (ישעיה א ג) יָדַע שׁוֹר קוֹנֵהוּ וַחֲמוֹר אֵבוּס בְּעָלָיו, יִשְׂרָאֵל לֹא יָדַע עַמִּי לֹא הִתְבּוֹנָן.</p>\n<p>וְרַשִּׁיעַיָּא מָה חָזוּ לְמֶעֱבַד עִגֶל, אֶלָּא וַדַּאי אִינוּן הֲווֹ מְכַשְּׁפִין דְּפַרְעֹה, יוֹנוֹ\"ס וְיַמְבְּרוּ\"ס בְּנֵי בִּלְעָם, דְּאִתְּמַר בְּהוֹן (שמות ח ג) וַיַּעֲשׂוּ כֵן הַחַרְטוּמִים בְּלָטֵיהֶם, וְחָזוּ דְּלָא הֲוָה מַמָּשׁוּ בְּהוֹן, אִתְחַזְרוּ עִמֵּיהּ דְּמֹשֶׁה וְקַבִּילוּ בְּרִית מִילָה, וְקוּדְשָׁא בְּרִיךְ הוּא דְיָדַע גְּלוּיִים וּסְתִירִין, דַּהֲוָה יָדַע בְּהוֹן דְּאִינוּן מִגִּזְעָא בִישָׁא, כַּד הֲוָה נָחֲתָא שְׁכִינְתָּא אִתְּמַר בָּהּ (שם יד יט) וַיִּסַּע מַלְאַךְ הָאלהי\"ם הַהֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל, וְלָא אָמַר לִפְנֵי הָעָם, וּבְגִין דָּא נָטְלוּ קִנְאָה בְּלִבַּיְיהוּ, וְאָמְרוּ (שם לב א) קוּם עֲשֵׂה לָנוּ אלהי\"ם אֲשֶׁר יֵלְכוּ לְפָנֵינוּ, כְּגַוְונָא דַהֲוָה אָזִיל קֳדָמַיְיכוּ, וּבְגִין דָּא עֲבַדוּ יָת עִִגְלָא בְחַרְשִׁין דִּלְהוֹן, וְדָא אִיהוּ יָדַע שׁוֹר קוֹנֵהוּ וכו', יִשְׂרָאֵל לֹא יָדַע חַרְשִׁין, עַמִּי אַהֲרֹן וּמֹשֶׁה בְּנֵי עַמְרָם לֹא הִתְבּוֹנָנוּ, וְדָא אִיהוּ לֹא תָלִין נִבְלָתוֹ עַל הָעִץ, חוֹבָא דָא דְעַם נָבָל לֹא תָלִין נִבְלָתוֹ עַל הָעִץ דְּאִינוּן יִשְׂרָאֵל. דָּבָר אַחֵר לֹא תָלִין וכו', דָּא גִיּוֹרָא דְלָא אִתְגַּיַּיר לִשְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא, לָא תַלְיָא בֵּיהּ בְּיִשְׂרָאֵל דְּאִינוּן עִץ, כְּמָה דְאוּקְמוּהוּ (ישעיה סה כב) כִימֵי הָעִץ יְמֵי עַמִּי.</p>\n<p>וְעוֹד לֹא תָלִין נִבְלָתוֹ, דָּא נִבְלוּת הַפֶּה, עַל הָעִץ דָּא לִישָׁנָא בִישָׁא, דְחוֹבָה דָא גָרִים דְּיָמוּת קֳדָם זִמְנֵיהּ, וְדָא אִיהוּ כִּי קָבוֹר תִּקְבְּרֶנּוּ, דָּבָר אַחֵר לֹא תָלִין נִבְלָתוֹ, דָּא יֵצֶר הָרָע, עַל הָעִץ דָּא נִשְׁמַת חַיִּים, דְּמָאן דְּחִלֵּל בָּהּ אִתְּמַר בֵּיהּ כִּי קָבוֹר תִּקְבְּרֶנּוּ, וְיָמוּת בְּעָלְמָא דֵין וּבְעָלְמָא דְאָתֵי, דָּא אִיהוּ דִינֵיהּ בְּחֶנֶק מָאן דְּעָבַר עַל דָּא. (דבר אחר לא תלין נבלתו על העץ, דא נפשא דחול דלא תתחזיא קדם נפשא יתירא ובגינה אמר למשה (שמות ג ה) של נעליך מעל רגליך).</p>\n<p>תִּנְיָינָא הֶרֶג, הֶרֶג לְגַנָּב, וּלְגַזְלָן עוֹנְשָׁא, וּבְגִין דָּא הַמְּמַשְׁכֵּן לְחַבְרֵיהּ צָרִיךְ לְמֶחְזַר לֵיהּ מַשְׁכּוֹנֵיהּ בְּעִידָּן דְּצָרִיךְ לֵיהּ, כֵּיוָן דְּלֵית לֵיהּ אָחֳרָא, הֲדָא הוּא דִכְתִיב (דברים כד יג) הָשֵׁב תָּשִׁיב לוֹ אֶת הָעֲבוֹט וְאִתְּמַר בִּקְרָא אַחֲרָא (שמות כב כה) אִם חָבֹל תַּחְבֹּל שַׂלְמַת רֵעִִךָ עַד בֹּא הַשֶּׁמֶשׁ תְּשִׁיבֶנּוּ לוֹ, הַאי בְּנִשְׁמָתָא דְבַר נַשׁ מְמַלֵּל, אִם חָבֹל תַּחְבֹּל נַפְשָׁא וְרוּחָא, שַׂלְמַת רֵעִִךָ דָּא נִשְׁמָתָא.</p>\n<p>וְאִם חָבוֹל תַּחְבּוֹל תְּפִלִּין דְּיָד וּתְפִלִּין דְּרֵישָׁא, שַׂלְמַת רֵעִִךָ כִּסּוּיָיא דְמִצְוָה, עַד בֹּא הַשֶּׁמֶשׁ, דְּאִתְּמַר בֵּיהּ (תהלים פד יב) כִּי שֶׁמֶשׁ וּמָגֵן יהו\"ה אלהי\"ם, תְּשִׁיבֶנּוּ לוֹ קֳדָם דְּיִתְכַּנִּישׁ מִנֵּיהּ, דַּעֲלֵיהּ אִתְּמַר (מלאכי ג כ) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וּמַרְפֵּא בִּכְנָפֶיהָ, מַאי צְדָקָה צְלוֹתָא, וּמַרְפֵּא בִּכְנָפֶיהָ כַּנְפֵי מִצְוָה דְּאִינוּן תְּפִלִּין כַּנְפֵי יוֹנָה, וְכַנְפֵי מִצְוַת צִיצִית, הִיא שִׂמְלָתוֹ לְעוֹרוֹ מִשְׁכָא דִתְּפִלִּין, וְאִם אַתְּ לָא תַחֲזִיר אִלֵּין כִּסּוּיָין לֵיהּ קֳדָם דְּיִתְכַּנִּישׁ מִנֵּיהּ שִׁמְשָׁא דְּאִיהוּ קוּדְשָׁא בְּרִיךְ הוּא, דְאִתְּמַר בֵּיהּ כִּי שֶׁמֶשׁ וּמָגֵן יהו\"ה אלהי\"ם, הָכִי יִתְכַּנִּישׁ מִינָךְ נִשְׁמָתָא, דְאִתְּמַר בָּהּ (תהלים פט לז) כִּסְאוֹ כַשֶּׁמֶשׁ נֶגְדִּי, מִדָּה לָקֳבֵל מִדָּה, וּבְגִין דָּא עַד בֹּא הַשֶּׁמֶשׁ תְּשִׁיבֶנּוּ לוֹ, לוֹ לְעָנִי דְאִיהוּ צַדִּיק, וְלִשְׁכִינְתָּא דְאִיהִי עֲנִיָּיה בְגָלוּתָא, כַּד יֵתֵי לֵילְיָא דְאִיהִי גָלוּתָא, בַּמֶּה יִשְׁכָּב</p>"],[9500011284,"<p>שְׁכִינְתָּא, דְּוַדַּאי שִׁמְשָׁא דְאִיהוּ קוּדְשָׁא בְּרִיךְ הוּא לָא נָהִיר לָהּ בְּגָלוּתָא דְאִיהִי לֵילְיָא, וְאִשְׁתְּאָרַת בַּחֲשׁוֹכָא, וּבְגִין דָּא צְרִיכִין יִשְׂרָאֵל לְאַנְהָרָא לָהּ בְּגָלוּתָא בְּאוֹר וְנֵר, דְּאִיהוּ תּוֹרָה וּמִצְוָה, אוֹר נִשְׁמָתָא, נֵ\"ר נֶפֶשׁ רוּחָא דְאִינוּן סִימָן נֵ\"ר, בָּתֵּי דִתְּפִלֵּי לְמִשְׁכַּב בְּהוּ שְׁכִינְתָּא בְגָלוּתָא, וְכִסּוּיָא דְצִיצִית לְאִתְעַטְּפָא בֵיהּ בְּמִשְׁכָּבָהּ.</p>\n<p>וּבְגִין דָּא אִי בַר נַשׁ לָא אַנַּח תְּפִלִּין וְצִיצִית, בַּמֶּה יִשְׁכַּב אִיהִי בְּגָלוּתָא, עֲלָהּ אִתְּמַר (תהלים מא ב) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל בְּיוֹם רָעָה יְמַלְּטֵהוּ יהו\"ה, וּבִזְכוּת פִּקּוּדִין אִלֵּין יָרְתִין בְּנֵי נָשָׁא תְּלַת קִטְרִין, דְּאִינוּן נִשְׁמָתָא וְרוּחָא וְנַפְשָׁא, וּבְהוּ צָרִיךְ לְמִקְרֵי לְיִשְׂרָאֵל עִלָּאָה, דְיַנְחִית לְאַנְהָרָא בִשְׁכִינְתָּא בִּנְהוֹרָא דְפוּרְקָנָא, דְאִיהִי שֶׁמֶשׁ צְדָקָה, וּמַרְפֵּא בִּכְנָפֶיהָ לְיִשְׂרָאֵל דְּאִינוּן בְּבֵי מַרְעָא בְגָלוּתָא. דִּצְדָקָה אִיהִי שְׁכִינְתָּא עִלָּאָה, עֲלָהּ אִתְּמַר (איכה ב יג) מִי יִרְפָּא לָךְ, וְאִיהִי כ\"ה כ\"ה אַתְוָן דִּקְרִיאַת שְׁמַע עַרְבִית וְשַׁחֲרִית, וּבֵיהּ נָחֲתָא לְיִשְׂרָאֵל לְמִפְרַק שְׁכִינְתָּא, אֲבָל בִּימִינָא אוֹקִים לָהּ וְרִחַם עֲלָהּ, הֲדָא הוּא דִכְתִיב (ישעיה נד ח) וּבְחֶסֶד עוֹלָם רִחַמְתִּיךְ, וּבְגִין דָּא נִשְׁמָתָא וְרוּחָא וְנַפְשָׁא אִינוּן מִשְׁכְּבָא (משכונא) דִשְׁכִינְתָּא בְגָלוּתָא, וְעַלֵיה אִתְּמַר (דברים כד יג) וְשָׁכַב בְּשַׂלְמָתוֹ וּבֵרַכֶךָּ, וּבְגִין פִּקּוּדִין אִלֵּין שַׁרְיָא שְׁכִינְתָּא עַל בַּר נַשׁ.</p>\n<p>וְעַל נִשְׁמָתָא אִתְּמַר (מיכה ז ה) מִשֹּׁכֶבֶת חֵיקֶךָ שְׁמֹר פִּתְחֵי פִיךָ, דְּלָא תִדּוֹר אִם לֹא תְּשַׁלֵּם, הֲדָא הוּא דִכְתִיב (משלי כב כז) אִם אֵין לְךָ לְשַׁלֵּם לָמָּה יִקַּח מִשְׁכָּבְךָ מִתַּחְתֶּיךָ, וְאִשְׁתָּאֲרוּ רוּחַ וְנֶפֶשׁ יְתוֹמִים, וְאִם נִשְׁמָתָא עָבְרַת עַל פִּקּוּדֵי אוֹרַיְיתָא וְאַנְחַת חוֹבִין בְּגוּפָא, דִין אִיהוּ לִיפָּרַע מִנִּכְסֵי יְתוֹמִים, בְּפִקּוּדִין דַּעֲשֵׂה דְאִשְׁתָּאַר לוֹן מִנִּשְׁמָתָא, דִבְגִין חוֹבִין נָטְלִין מֵחַיָּיבַיָּא מַשְׁכּוֹנָא דְאִיהִי נִשְׁמָתָא, וְדָא אִיהוּ (שמות כב כה) אִם חָבֹל תַּחְבֹּל שַׂלְמַת רֵעִִךָ.</p>\n<p>וְאִי אִית לֵיהּ חוֹבִין וְאִית לֵיהּ זַכְוָון, אִתְפַּרְעוּ חוֹבִין בְּזַכְוָון, וְאִתְּמַר יָצָא שְׂכָרוֹ בְּהֶפְסֵדוֹ, מִיָּד חָזְרִין לֵיהּ לְגוּפָא קֳדָם דְּיֵיתֵי שִׁמְשָׁא, וְדָא אִיהוּ (שם) עַד בֹּא הַשֶּׁמֶשׁ תְּשִׁיבֶנּוּ לוֹ, דְּכַד נָאִים בַּר נַשׁ נִשְׁמָתָא סָלְקָא מִנֵּיהּ, וְלָא נָחְתַת בְּגוּפָא עַד דְּפָרְעַת כָּל חוֹבִין דְּעָבַד בַּר נַשׁ בְּהַהוּא יוֹמָא, וּבְגִין דָּא מְמַשְׁכֵּן לָהּ הַהוּא בֵּי דִינָא דִלְעִילָא, בְגִין דִּמְקַטְרְגָא סָלִיק אַבַּתְרָהָא לְמִתְּבַע מִינָהּ דִּינָא, בְּאַרְבַּע מִיתוֹת בֵּית דִּין, תְּרֵין דְּאִתְּמַר לְעִיל, וּתְרֵין דְּאִינוּן שַׁרְיָין עַל אִינוּן דִּמְגַלִּין עִִרְיָין דְּאוֹרַיְיתָא, זַכָּאָה אִיהוּ מָאן דְּנָטִיר לָהּ בְּכָל יוֹמָא.</p>\n<p>וּבְזִמְנָא דְחוֹבִין אִינוּן רַבְרְבִין, וּמַלְוְה בַּר נַשׁ חוֹבִין עַל מַשְׁכּוֹנָא, אָבַד מַשְׁכּוֹנָא דְאִיהִי נִשְׁמָתָא, וְלָא חָזְרַת לְגַבֵּיהּ, וְכֹלָּא אִיהוּ בְּדִין דְּדָן לָהּ גְּבוּרָה דְאִיהוּ בֵּי דִינָא רַבְרְבָא, בְכָל לֵילְיָא בִתְרֵין עֲשַׂר שַׁעִִתִּין וּבְשַׁבְעִין וּתְרֵין רְגָעִין כְּחֻשְׁבַּן חֶסֶ\"ד, דְּאִתְּמַר בֵּיהּ (ישעיה טז ה) וְהוּכַן בַּחֶסֶד כִּסֵּא, וְרָזָא דְמִלָּה (איוב ז יח) וַתִּפְקְדֶנּוּ לִבְקָרִים, לִרְגָעִים תִּבְחָנֶנּוּ.</p>\n<p>וְאִית חוֹבִין דְּאִינוּן בְּסֵתֶר, וְלָא יְכִילִן לְאַסְהָדָא בְהוֹן מַלְאָכִין דְּאָזְלִין עִם נִשְׁמָתָא, דְאִתְּמַר בָּהּ (תהלים צא יא) כִּי מַלְאָכָיו יְצַוְּה לָּךְ, הָא שְׁכִינְתָּא סָהִידַת עֲלַיְיהוּ, הֲדָא הוּא דִכְתִיב (ירמיה כג כד) אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים, בְּגִין דִּשְׁכִינְתָּא עַל רֵישֵׁיהּ, דְּאִתְּמַר בָּהּ דַּע מַה לְּמַעִִלָה מִמָּךְ, עַיִן רוֹאָה וְאֹזֶן שׁוֹמַעַת וְכָל מַעֲשֶׂיךָ בְּסֵפֶר נִכְתָּבִין, (לזמנין נשמתא לא הות מודה בחובין דתבע עליה יצר הרע, וחשיד יצר הרע בהאי), (נ\"א ולזמנין נשמתא לא חבת וחשיד יצר הרע בהאי), וְאָזְלִין לְגַבֵּי בֵּי דִינָא וְדָן עֲלַיְיהוּ דִין הַנִּשְׁבָּעִים, אוֹמִיאַת נִשְׁמָתָא עֲלַיְיהוּ וְאִתְפַּטְרַת, וְאִם לַאו פַּרְעַת.</p>\n<p>וְאִית חוֹבִין דְּאִתְּמַר בְּהוֹן (איוב לז ז) וּבְיַד כָּל אָדָם יַחְתּוֹם, וּמַרְאִין לָהּ חֲתִימַת יְדָהָא. וְאִית חוֹבִין דְּאִינוּן עַל תְּנַאי דְּאַתְנֵי עֲלֵיהּ לְפָרְעָא לוֹן בְּהַאי עָלְמָא, דְחוֹבִין דִּילֵיהּ בְּאַתְרֵיהּ, דְּלָא יִגְבַּהּ לוֹן תּוֹבֵעַ אֶלָּא בְּאַתְרֵיהּ, וְאִלֵּין אִינוּן חוֹבִין דְּעִִשְׂרִין שְׁנִין, וְאִית חוֹבִין לְתַתָּא, דְאוּקְמוּהוּ קַדְמָאִין דְּעַד עִִשְׂרִין שְׁנִין</p>"],[9500011285,"<p>מַעֲנִישִׁין לְתַתָּא וְלָא לְעִילָא, וְאִית חוֹבִין דְּמַעֲנִישִׁין לְעִילָא וְתָבְעִין לוֹן לְעִילָא בֵּי דִינָא רַבְרְבָא, וּבְגִינַיְיהוּ מְמַשְׁכְּנִין נִשְׁמָתָא לְעִילָא, וְלָא מַנִּיחִין לָהּ לְנָחֲתָא לְתַתָּא, אֲבָל בְּחוֹבִין דְּמַעֲנִישִׁין עֲלַיְיהוּ לְתַתָּא, לָא מַעֲנִישִׁין לָהּ לְעִילָא, וְלָא מְעַכְּבֵי לֵיהּ תַּמָּן, וְאִית חוֹבִין דְּנִשְׁמָתָא דְּגָבִין מִנַּיְיהוּ בְּכָל אֲתַר, כְּגוֹן (שמות כא יז) וּמְקַלֵּל אָבִיו וְאִמּוֹ, דְאִתְּמַר בֵּיהּ מוֹת יוּמָת, מִבֵּי דִינָא דִלְעִילָא וּמִבֵּי דִינָא דִלְתַתָּא, דְּאִתְדַּנַּת בִּתְרֵין דִּינִין, וּבְגִין חוֹבָא דָא בְכָל אֲתַר דְּאַשְׁכְּחִין לָהּ לְעִילָא גָבִין מִינָהּ, וּבְכָל אֲתַר דְּאַשְׁכְּחִין לָהּ לְתַתָּא גָבִין מִינָהּ, וְלֵית פִּקּוּדָא דְלֵית לָהּ רְשׁוּ לְאַגָּנָא עֲלָהָא, דְּאִית חוֹבִין דְּדַיְינִין לָהּ בְּדִינִים חֲמוּרִים לְנִשְׁמָתָא, וְיֵתֵי מִצְוָה דְאִיהִי מַטְרוֹנִיתָא כְּגוֹן מִצְוַת תְּפִלִּין, וְאַגִּינַת עֲלֵיהּ וּפְרִישַׂת גַּדְפָהָא עֲלָהּ, וְלֵית רְשׁוּ לִמְקַטְרֵג לְקָרְבָא תַּמָּן, וְאִית חוֹבִין דְּמַטְרוֹנִיתָא לֵית לָהּ רְשׁוּ לְאַגָּנָא עֲלַיְיהוּ, הֲדָא הוּא דִכְתִיב (שם יד) מֵעִם מִזְבְּחִי תִּקָּחֶנּוּ לָמוּת.</p>\n<p>אֲבָל פִּקּוּדִין אִית דְּאִינוּן שְׁפָחוֹת, מֵאִלֵּין פִּקּוּדִין דְּאִינוּן עַל מְנָת לְקַבֵּל פְּרָס, אַף עַל גַּב דְּיֵיתוּן לְאַגָּנָא עֲלָהּ, נָטְלֵי לוֹן מְקַטְרְגִין תְּחוֹת רְשׁוּתַיְיהוּ, (נ\"א נפקין לה מקטרגין מרשותייהו), וְאִית חוֹבִין אָחֳרָנִין דְּאִתְקְרִיאוּ חֲלוּקֵי דַיָּינִין, עַל חוֹבִין דְּחוֹלְקִין בְּהוֹן, מִנְּהוֹן מַטֶּה כְּלַפֵּי חֶסֶד, וְדַיְינִין לָהּ לְנִשְׁמָתָא בְּמָמוֹן דְּאִיהוּ דִינֵי מָמוֹנוֹת, וְאִית אָחֳרָנִין דְּחוֹלְקִין עֲלַיְיהוּ וְאִינוּן נוֹטִין כְּלַפֵּי חוֹבָה, לְמֵידַן לָהּ בְּדִינֵי נְפָשׁוֹת, אִם זַכְוָון מִתְגַּבְּרִין עַל חוֹבִין דָּנִין לָהּ בְּדִינֵי מָמוֹנוֹת, וְגָבִין מִזַּכְוָון דְּאִינוּן גְּמִילוּת חֲסָדִים דִּילֵיהּ, וְאִם חוֹבִין מִתְגַּבְּרִין דַּיְינִין לָהּ בְּדִינֵי נְפָשׁוֹת מִסִּטְרָא דִגְבוּרָה, וְגָבִין בָּהּ נֶפֶשׁ וְרוּחַ.</p>\n<p>וּלְעִילָא לֵית מַשּׂוֹא פָּנִים בֵּין זַכָּאָה לְחַיָּבַיָּא, וְכֵן צָרִיךְ לְהַשְׁווֹת לְתַתָּא גַבֵּי דִינָא זַכָּאָה עִם חַיָּיבָא, מִסִּטְרָא דֶאֱמֶת עַמּוּדָא דְאֶמְצָעִיתָא, וְלָא יְהֵא דַיָּינָא רַשַּׁאי לְמֶעֱבַד מַשּׂוֹא פָנִים לְחַד מִנַּיְיהוּ בְדִינָא, דִבְדַיָּינָא דִלְעִילָא אִתְּמַר בֵּיהּ (דברים י יז) לֹא יִשָּׂא פָנִים וְלֹא יִקַּח שֹׁחַד, וַוי לֵיהּ לְדַיָּינָא לְתַתָּא דְאִשְׁתַּנֵּי מִדַּיָּינָא דִלְעִילָא, דְאַכְחִישׁ עוֹבָדָא דִבְּרֵאשִׁית, וְלָא יֵימָא דָא מְהֵימְנָא מִדָּא, דִּכְמָה דְאִיהוּ לְתַתָּא (שם טז יח) שׁוֹפְטִים וְשׁוֹטְרִים תִּתֶּן לְךָ בְּכָל שְׁעָרֶיךָ, לְדַיְינָא גוּפִין, הָכִי אִית לְעִילָא שׁוֹפְטִים וְשׁוֹטְרִים לְדַיְינָא נִשְׁמָתָא, וְלָא יוֹקִיר לְדָא יַתִּיר מִדָּא, אֶלָּא תַרְוַיְיהוּ בְּהַשְׁוָאָה בְדִינָא, וְאִינוּן צְרִיכִין לְמִשְׁמַע קֳדָם דַּיָּינָא, וְלָא יְמַלְּלוּן עַד דְּשָׁאִיל לוֹן דַּיָּינָא, וְיָהִיב לוֹן רְשׁוּ לְמַלְּלָא, וִיהוֹן קֳדָמֵיהּ בִּדְחִילוּ, בְּגִין דִּשְׁכִינְתָּא שַׁרְיָא עֲלַיְיהוּ, וּמָאן דְּתָבַע קְשׁוֹט כְּאִלּוּ מְקַיֵּים עַל עָלְמָא דַיָּין אֱמֶת (ס\"א דין אמת), וְכָל שֶׁכֵּן מָאן דְּדָן דִּין אֱמֶת, כְּאִלּוּ מְקַיֵּים (תהלים פ יב) אֱמֶת מֵאֶרֶץ תִּצְמָח, וַוי לֵיהּ לְמָאן דְּאוֹקִים שִׁקְרָא וְאַפִּיל אֱמֶת, דְּגָרִים (דניאל ח יב) וְתַשְׁלֵךְ אֱמֶת אַרְצָה, וּמָאן גָּרִים דָּא דַּיָּינָא דְלָא דָן דִּין אֱמֶת, וּבְוַדַּאי דַּיָּין דְּדָן דִּין אֱמֶת כְּאִלּוּ הוּא אַפִּיק לִשְׁכִינְתָּא וּלְיִשְׂרָאֵל מִגָּלוּתָא, וְאוֹקִים לוֹן מֵאַרְעָא.</p>\n<p>קָם רַבִּי שִׁמְעוֹן עַל רַגְלוֹי, וְסָלִיק יְדוֹי לְגַבֵּי עִילָא, וְשַׁבַּח לְמָארֵי עָלְמָא, וְאָמַר, רִבּוֹן עָלְמָא עֲבֵיד בְּגִין שְׁכִינְתָּא דְאִיהִי בְגָלוּתָא, וְאִם אִיהִי בְּאוֹמָאָה הָא אַבָּא וְאִמָּא דְאִינוּן חָכְמָה וּבִינָה יָכְלִין לְמֶעֱבַד הַתָּרָה, הֲדָא הוּא דִכְתִיב (ישעיה יד כז) יהו\"ה צְבָאוֹ\"ת יָעָץ וּמִי יָפֵר, אִם הַתַּלְמִיד אוֹמֵי הָרַב יָכִיל לְמֶעֱבַד הַתָּרָה.</p>\n<p>וְאִם נָדַר אוֹ נִשְׁבַּע בֵּן דְּאִיהוּ ו' דְּלָא יִפְרוֹק לָהּ אֶלָּא דִתְהֵי בְּגָלוּתָא עַד זִמְנָא יְדִיעָא, וְנֶדֶר אוֹ שְׁבוּעָה אִיהוּ בְּי\"ה דְּאִינוּן חָכְמָה וּבִינָה, וְאִיהוּ אִתְחָרֵט, הָא תְּלַת בְּנֵי נָשָׁא יָכְלִין לְמִפְטַר לֵיהּ, וְאִינוּן תְּלַת אֲבָהָן לְעִילָא לְקִבְלַיְיהוּ, וְאִם לָא תִּתְחָרֵט, אֲנָא בָּעִינָא מִינָךְ, וּמִכָּל אִינוּן דִּמְתִיבְתָּא דִלְעִילָא וְתַתָּא, דְתַעֲבֵיד בְּגִין רַעֲיָא מְהֵימְנָא דְלָא זָז מִשְּׁכִינְתָּא בְּכָל אֲתַר, וְאִיהוּ עָאל שְׁלָם בֵּינָךְ וּבֵינָהּ זִמְנִין</p>"],[9500011286,"<p>סַגִּיאִין, וּמָסַר גַּרְמֵיהּ לְמִיתָה בְּגִינָהּ וּבְגִין בְּנָהָא, הֲדָא הוּא דִכְתִיב (שמות לב לב) וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךָ אֲשֶׁר כָּתָבְתָּ.</p>\n<p>וְאִם הוּא נֶדֶר מִסִּטְרָא דְאַבָּא וְאִמָּא, וְלָא בָּעִי, אֲנָא סָלִיק לְגַבֵּי הַהוּא דְאִתְּמַר בֵּיהּ (דברים יז ח) כִּי יִפָּלֵא מִמְּךָ דָבָר, דְּאִתְּמַר בֵּיהּ בְּמוּפְלָא מִמָּךְ אַל תִּדְרוֹשׁ, דְּיִפְטוֹר נֶדֶר, וְאַף עַל גַּב דִּשְׁכִינְתָּא אִיהִי בְגָלוּתָא לְגַבֵּי בַּעִִלָהּ כְּנִדָּה, דְּאִיהִי יַפְרִישׁ בֵּין דָּם לְדָם, וְאִתְפַּתַּח מְקוֹרָא דִילָהּ, לְדַכָּאָה לָהּ בְּמַיִם דְּאוֹרַיְיתָא, מַיִם חַיִּים דְּלָא פָסְקִין, וְאַפְרֵישׁ מִינָהּ דַּם נִדָּה דְּאִיהִי לִילִי\"ת, דְּלָא אִתְקְרִיבַת בַּהֲדָהּ, דְּאִיהִי חוֹבָא דְנִשְׁמָתָא דְסָאִיבַת לָהּ, וְלֵית לָהּ רְשׁוּ לְסָלְקָא נִשְׁמָתָא לְגַבֵּי בַּעִִלָהּ, לְהַהוּא אֲתַר דְּאִתְיְיהִיבַת מִתַּמָּן, וְאִתְדָּנַת בֵּין דִּין לְדִין, בֵּין דִּינֵי נְפָשׁוֹת לְדִינֵי מָמוֹנוֹת, דְּאִית מָאן דְּפָרַע בְּמָמוֹנֵיהּ, וְאִית מָאן דְּפָרַע בְּנַפְשֵׁיהּ, וּבֵין נֶגַע לָנֶגַע, כְּמָה דְאוּקְמוּהוּ (איכה א א) אֵיכָה יָשְׁבָה בָדָד, דְּאִיהִי חֲשִׁיבָא שְׁכִינְתָּא בְּגָלוּתָא כִּמְצוֹרָע, דְּאִתְּמַר בֵּיהּ (ויקרא יג מו) בָּדָד יֵשֵׁב מִחוּץ לַמַּחֲנֶה, מִחוּץ וַדַּאי, דָּא גָלוּתָא, דְּאִיהִי לְבָר מֵאַרְעָא דְיִשְׂרָאֵל, דְּאִיהִי מוֹתְבָא דְאָת ה'.</p>\n<p>וְאִי מְקוֹרָא לָא יָכִיל לְמִפְתַּח עַד דְּיִפְתַּח לֵיהּ הַהוּא דְסָגִיר לֵיהּ, אֲנָא מְפַיַּיסְנָא לֵיהּ בְּגִין יו\"ד ה\"א וא\"ו ה\"א, דְּאִיהוּ יִחוּדָא (דיחודיה תמן), וּבְגִין לְבוּשִׁין דְּאִתְלַבֵּשׁ, מִיָּד אִתְפַּתְּחַת מְקוֹרָהּ וְאִתְדַּכִּיאַת שְׁכִינְתָּא, וְרָזָא דְמִלָּה (ירמיה יד ח) מִקְוִה יִשְׂרָאֵל יהו\"ה מוֹשִׁיעוֹ בְּעִת צָרָה, מוֹשִׁיעוֹ וַדַּאי, הַהוּא דְמָקוֹרָא דְמִקְוְה בִּידֵהּ.</p>\n<p>(זהו תקון כ\"ו)</p>\n<p>בְּרֵאשִׁית תַּמָּן תְּרֵי אֵשׁ, וְאִלֵּין אִינוּן תְּרֵין אֵשִׁין דְּאִינוּן בּוֹרֵא מְאוֹרֵי הָאֵשׁ, וַעֲלַיְיהוּ אִתְּמַר (שיר ב ה) סַמְּכוּנִי בָּאֲשִׁישׁוֹת, בִּתְרֵי אֵשׁוֹת, וְאַמַּאי אָמַר בְּהוֹן סַמְּכוּנִי, אֶלָּא בְלֵילֵי שַׁבָּת נְשָׁמָה יְתֵירָה קָא נָחֲתָא לְסָמְכָא שְׁכִינְתָּא תַּתָּאָה בְגָלוּתָא, דְאִתְּמַר בָּהּ (עמוס ה ב) נָפְלָה וְלֹא תוֹסִיף קוּם, וְכַד אָתָא מוֹצָאֵי שַׁבָּת אִסְתַּלְקַת נִשְׁמָתָא יְתֵירָה דְבָהּ וַיִּנָּפַשׁ, וַיִּנָּפַשׁ מִיָּד דְּאִיהִי אִסְתַּלְקַת וַי נֶפֶשׁ, דְּלֵית מָאן דְּסָמִיךְ לָהּ, בְּהַהוּא זִמְנָא אִיהִי אָמְרַת לְיִשְׂרָאֵל סַמְּכוּנִי בָּאֲשִׁישׁוֹת דְּאִינוּן מְאוֹרֵי הָאֵשׁ, וּמַאי נִיהוּ תְּרֵי תּוֹרוֹת, דְּאִינוּן חֲצוּבוֹת מֵאֵשׁ דְּאִיהִי אלהי\"ם מִדַּת הַגְּבוּרָה, וּמַאי נִיהוּ לִמּוּדֵי יהו\"ה תְּרֵין שִׂפְוָון דְּאִקְרוּן לַהֲבוֹת (דאוקדון בלהבות) אֵשׁ, וְאִינוּן תְּרֵין תַּפּוּחִין, דְּמִנְּהוֹן רוּחָא דִמְשִׁיחָא נָפִיק, דְּאִתְּמַר בֵּיהּ (ישעיה יא ב) וְנָחָה עָלָיו רוּחַ יהו\"ה.</p>\n<p>לְבַת מֶלֶךְ דַּהֲוַת בְּבֵי מַרְעָא מֵרְחִימוּ דְבַעִִלָהּ, דְּאָזַל בַּעִִלָהּ אִיהִי נָפְלַת לְמִשְׁכָּבָה, צָוְוחַת וְאָמְרַת סַמְּכוּנִי בָּאֲשִׁישׁוֹת, הָא אִיהִי בְּבֵי מַרְעָא, הִיא אוֹמֶרֶת רַפְּדוּנִי, בְּמַאי בַּתַּפּוּחִים דְּמִתְרַבִּים בַּעֲצֵי הַיַּעַר, וְאִלֵּין אִינוּן עֲצֵי בְשָׂמִים.</p>\n<p>קָם סָבָא תְּלִיתָאָה וְאָמַר רַבִּי רַבִּי, הָא אֲנַן בַּעֲצֵי בְשָׂמִים מַבְדִּילִין, וְהָכָא אִיהִי לָא אָמְרַת אֶלָּא בַּתַּפּוּחִים, אֶלָּא אֲנַן מְבָרְכִין עַל עֲצֵי בְשָׂמִים בְּגִין דְּאִתְּמַר בְּהוֹן (שיר ז ט) וְרֵיחַ אַפֵּךְ כַּתַּפּוּחִים, וְלָא עוֹד אֶלָּא כָּל מִינֵי בְשָׂמִים אִינוּן טָבָאן לְבָרְכָא עֲלַיְיהוּ, וַאֲנַן דְּעָבְדִין בַּהֲדַס בְּגִין דְּאִית בֵּיהּ תְּלַת עַלִּין, דְּאִתְקְרִיאוּ תְּלַת הֲדַסִּים, דִּרְמִיזִין לִתְלַת אֲבָהָן, אֲבָל תְּרֵין נוּקְבִין דְּחוֹטָמָא אִינוּן לָקֳבֵל תְּרֵין תַּפּוּחִין דְּאִינוּן תְּרֵי נְבִיאֵי קְשׁוֹט, דִּי בְהוֹן עָתִיד לְאַפָּקָא רוּחָא דְקוּדְשָׁא דְאִיהוּ רַעִִיָא מְהֵימְנָא דִלְעִילָא, דְּבֵיהּ אִתְיַשְׁבַת נַפְשָׁא דִילָהּ, וּבְגִין דָּא אִיהִי אָמְרַת (שם ב ה) רַפְּדוּנִי בַּתַּפּוּחִים כִּי חוֹלַת אַהֲבָה אָנִי</p>"],[9500011287,"<p>בְּלֵילְיָא דְשַׁבָּת אִתְּמַר (שיר ה ה) קַמְתִּי אֲנִי לִפְתּוֹחַ לְדוֹדִי בְשַׁבָּת, וְכַד נָפִיק שַׁבָּת אִתְּמַר (שם) וְדוֹדִי חָמַק עָבָר, וּבְהַהוּא זִמְנָא (שם) בִּקַּשְׁתִּיהוּ וְלֹא מְצָאתִיהוּ קְרָאתִיו וְלֹא עָנָנִי, עַד דְּאוֹמֵינָא דִבְזִמְנָא דְיֵיתֵי זִמְנָא אַחֲרָא דְאוֹחִיד בִּידֵיהּ וְלָא אַשְׁבְּקִינֵיהּ לְמֵיזַל, כְּמָה דְאִתְּמַר (שם ג ד) אֲחַזְתִּיו וְלֹא אַרְפֶּנּוּ עַד שֶׁהֲבֵאתִיו אֶל בֵּית אִמִּי, דָא בֵי מַקְדְּשָׁא דִלְעִילָא, וְאֶל חֶדֶר הוֹרָתִי דָא בֵי מַקְדְּשָׁא דִלְתַתָּא.</p>\n<p>וּבְזִמְנָא דַאֲחִיד בִּידֵיהּ בְּפוּרְקָנָא בַתְרַיְיתָא, לָא יְהֵא לִי כְזִמְנִין אוֹחֲרָנִין, דִּבְכָל פּוּרְקָנָא וּפוּרְקָנָא הֲוָה אָתֵי, וּלְבָתַר הֲוָה פָרַח מִנָּאִי, אֲבָל בְּפוּרְקָנָא בַתְרַיְיתָא אֲנָא אֲחִיד בֵּיהּ וְקָשִׁיר לֵיהּ בְּכַמָּה קְשִׁירִין דִּרְחִימוּ, דְלָא יָזוּז מִנָּאִי לְעָלַם וּלְעָלְמֵי עָלְמִין, דִּבְכָל גָּלוּתָא וְגָלוּתָא הֲוָה אָזִיל מִנָּאִי, וַהֲוִינָא שָׁאִיל עֲלֵיהּ לְכָל עוֹבֵר וְשָׁב, הֲדָא הוּא דִכְתִיב (שם) כִּמְעַט שֶׁעָבַרְתִּי מֵהֶם עַד שֶׁמָּצָאתִי אֵת שֶׁאָהֲבָה נַפְשִׁי, וְזִמְנִין לָא הֲוִינָא אַשְׁכַּח מָאן דְּיֵימָא לִי מִדֵּי מִנֵּיהּ, וַהֲוִינָא אוֹמֵי בְּגִינֵיהּ לְכָל בְּנֵי קַרְתָּא, הֲדָא הוּא דִכְתִיב (שם ה ח) הִשְׁבַּעִִתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלָםִ אִם תִּמְצְאוּ אֶת דּוֹדִי מַה תַּגִּידוּ לוֹ שֶׁחוֹלַת אַהֲבָה אָנִי, וְכַמָּה זִמְנִין (שם ג א) עַל מִשְׁכָּבִי בַּלֵּילוֹת דְּאִינוּן גָּלִיּוֹת, בִּקַּשְׁתִּי אֵת שֶׁאָהֲבָה נַפְשִׁי וְלָא הֲוָה מָאן דְּיֵימָא לִי, עַד דְּאִיהוּ הֲוָה אָתֵי, וּכְעַן בְּגָלוּתָא בַתְרַיְיתָא בָּרַח דּוֹדִי בְכַעֲסָא סַגִּיא, וְשָׁאִילְנָא בְגִינֵיהּ וְלָא אַשְׁכַּחְנָא מָאן דְּיֵימָא לִי מִדֵּי, וּבְגִין דָּא אֲנָא אוֹמִינָא, דִבְזִמְנָא דְיֵיתֵי וַאֲחִידְנָא בִידוֹי דְּלָא יָזוּז מִנָּאִי, וַאֲנָא אֲחַזְתִּיו וְלֹא אַרְפֶּנּוּ אֲחַזְתִּיו בְּקִשּׁוּרָא דִּתְּפִלִּין דְּיָד, וְלֹא אַרְפֶּנּוּ בִתְפִלִּין דְּרֵישָׁא.</p>\n<p>תָּא חֲזִי, דוֹדְהָא כַּד יֵתֵי לְגַבָּהּ, יֵימָא לְגַבֵּי תְּרֵין מְשִׁיחִין (שם ז יג) נַשְׁכִּימָה לַכְּרָמִים דְּאִינוּן יִשְׂרָאֵל, דִּי בְהוֹן אִתְּמַר (ישעיה ה ז) כִּי כֶרֶם יהו\"ה צְבָאוֹת בֵּית יִשְׂרָאֵל, נִרְאֶה הֲפָרְחָה הַגֶּפֶן דְּאִיהִי שְׁכִינְתָּא בְהוֹן, הֵנֵצוּ הָרִמּוֹנִים אִלֵּין אִינוּן דְּמַלְיָין מִצְוֹת כָּרִמּוֹן.</p>\n<p>קָם רַבִּי שִׁמְעוֹן וְאָמַר סָבָא סָבָא, נַשְׁכִּימָה לַכְּרָמִים, הָא אִית כְּרָמִים דְּלַאו אִינוּן יִשְׂרָאֵל, כְּגוֹן (שיר א ו) דְשָׂמוּנִי נוֹטֵרָה אֶת הַכְּרָמִים כַּרְמִי שֶׁלִּי לֹא נָטָרְתִּי, וְאִינוּן עִרְבוּבְיָא דְעִרֶב רַב, דְּאִינוּן מְעוּרָבִין בְּהוֹן בְּיִשְׂרָאֵל בְּגָלוּתָא, וּבְגִין דָּא כַד יֵיתֵי קוּדְשָׁא בְּרִיךְ הוּא לְגַבֵּי שְׁכִינְתָּא, אִיהוּ יֵימָא לְגַבָּהּ, נַשְׁכִּימָה לַכְּרָמִים, נִרְאֶה אִם פָּרְחָה הַגֶּפֶן בְּהוֹן, דְּאִתְּמַר בָּהּ כִּי כֶרֶם יהו\"ה צְבָאוֹת בֵּית יִשְׂרָאֵל, הֵנֵצוּ הָרִמּוֹנִים אִלֵּין וַדַּאי אִינוּן דְּמַלְיָין מִצְוֹת כָּרִמּוֹנִים, שָׁם אֶתֵּן אֶת דּוֹדַי לָךְ, אִלֵּין דְּאִינוּן רְחִימִין דִּילָךְ, תַּמָּן יְהִיבְנָא לוֹן לָךְ, (שיר ב יא) כִּי הִנֵּה הַסְּתָו עָבָר שׁוּלְטָנוּ דִשְׁאָר מְמַנָּן דְאוּמִין, הַגֶּשֶׁם חָלַף הָלַךְ לוֹ שָׁלְטָנוּתָא דְעִרֶב רַב.</p>\n<p>בְּהַהוּא זִמְנָא יֵימָא לְגַבָּהּ, (שיר ז א) שׁוּבִי שׁוּבִי הַשּׁוּלַמִּית, בִּתְרֵי בָּתִּים דְּאִינוּן בַּיִת רִאשׁוֹן וּבַיִת שֵׁנִי לְתַתָּא, שׁוּבִי שׁוּבִי בְּבַיִת רִאשׁוֹן וְשֵׁנִי לְעִילָא, וְנֶחזֶה בָּךְ. דָּבָר אַחֵר, שׁוּבִי שׁוּבִי אַרְבַּע זִמְנִין, בְּאַרְבַּע אַתְוָון דִּילָהּ דְּאִינוּן אדנ\"י, וְנֶחזֶה בָּךְ בְּאַרְבַּע אַתְוָון דִּילֵיהּ דְּאִינוּן יהו\"ה, אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְגַבֵּי יִשְׂרָאֵל, אַרְבַּע זִמְנִין שׁוּבִי בִּשְׁכִינְתָּא בִּתְיוּבְתָּא, וְנֶחזֶה בָּךְ בְּאַרְבַּע כּוֹסוֹת דְּפוּרְקָנָא דְאִינוּן בַּפֶּסַח, דְּחַיָּיבִין בֵּיהּ יִשְׂרָאֵל לְמִשְׁתֵּי אַרְבַּע כּוֹסוֹת, כְּגַוְונָא דְאַרְבַּע גְּאוּלוֹת, שׁוּבִי שׁוּבִי בְּאַרְבַּע יִחוּדִין (ס\"א יסודין) דִּילָךְ, וְנֶחזֶה בָּךְ בְּאַרְבַּע חֵיוָון, וְנֶחזֶה בָּךְ בִּשְׁמַיָּא וְאַרְעָא, וּמִיָּד (דה\"י א טז לא) יִשְׂמְחוּ הַשָּׁמַיִם וְתָגֵל הָאָרֶץ וְיֹאמְרוּ בַגּוֹיִם יהו\"ה מָלָךְ.</p>\n<p>בְּהַהוּא זִמְנָא הַנִּצָּנִים נִרְאוּ בָאָרֶץ אִלֵּין אֲבָהָן, זַכְוָון דִּלְהוֹן אִתְגַּלְיָאן עַל שְׁכִינְתָּא דְאִיהִי אֶרֶץ הַחַיִּים, וְעַל בְּנָהָא דְאִתְּמַר בְּהוֹן (בראשית כח יד) וְהָיָה זַרְעֲךָ כַּעֲפַר הָאָרֶץ, (שיר ב יב) עִת הַזָּמִיר הִגִּיעַ, (שמות טו א) אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל, וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ, (ישעיה נב יח) קוֹל צוֹפַיִךְ נָשְׂאוּ קוֹל יַחְדָּיו יְרַנֵּנוּ, כִּי עַיִן בְּעַיִן יִרְאוּ בְּשׁוּב יהו\"ה צִיּוֹן, בְּהַהוּא זִמְנָא קוּדְשָׁא בְּרִיךְ הוּא מְשַׁבַּח לָהּ, הֲדָא הוּא דִכְתִיב (שיר ז ו) רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל, דָּא תְּפִלִּין</p>"],[9500011288,"<p>דְּרֵישָׁא, וּרְצוּעִין תַּלְיָין מִכַּאן וּמִכַּאן כִּזְמוֹרוֹת, דְּאִינוּן כַּכַּרְמֶל דְּתַלְיָין מִגֶּפֶן, וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן דָּא תְפִלָּה דְיָד, מַה דַּהֲוָת דַלַּת בְּגָלוּתָא עֲנִיָּיה, הֲדָא הוּא דִכְתִיב (תהלים קב א) תְּפִלָּה לְעָנִי כִי יַעֲטוֹף, תְּהֵא לְבוּשָׁא כָּאַרְגָּמָן, דְּאִיהוּ סוֹד א\"וּרִיאֵל רְ\"פָאֵל גַּ\"בְרִיאֵל מִ\"יכָאֵל נ\"וריאל, (שיר ז ו) מֶלֶךְ אָסוּר בָּרְהָטִים דָּא קוּדְשָׁא בְּרִיךְ הוּא יהו\"ה, דִּיְהֵא אָסוּר בְּאַרְבַּע בָּתִּים דִּילָהּ דְּאִינוּן אדנ\"י, אַרְבַּע רְהָטֵי מוֹחָא, דִיְהֵא אָסוּר בָּרְהָטִים כְּגַוְונָא דָא יאהדונה\"י, כִּי שִׁמְךָ בְּךָ וּבְךָ שִׁמְךָ, וְדָא אִיהוּ סוֹד אָמֵן מִן אַרְגָּמָן.</p>\n<p>דָּבָר אַחֵר (שם) רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל, דָּא (תהלים קיט קס) רֹאשׁ דְּבָרְךָ אֱמֶת, דַּלַּת רֹאשֵׁךְ כָּאַרְגָּמָן דָּא שְׁכִינְתָּא, מֶלֶךְ דָּא אַבְרָהָם, אָסוּר דָּא יִצְחָק בָּעֲקֵדָה, בְּקִשְׁרָא דִּתְּפִלִּין דִּדְרוֹעָא שְׂמָאלָא, בָּרְהָטִים דָּא יַעֲקֹב בְּאַרְבַּע רְהִיטֵי מוֹחָא דִתְּפִלִּין דְּרֵישָׁא, דְאִתְּמַר (בראשית ל לח) בָּרְהָטִים בְּשִׁקֲתוֹת הַמָּיִם.</p>\n<p>קָם רַבִּי שִׁמְעוֹן וְאָמַר, אִתְכַּנְשׁוּ חֲיָילִין קַדִּישִׁין עִלָּאִין וְתַתָּאִין, לְמֶחמֵי בְּקִשּׁוּטָהָא דְכַלָּה, דְהָא חוּפָּה מִתְתַּקְנָא לְגַבָּהּ, וְחָתָן קָא נָטִיל לָהּ תַּמָּן, פָּתַח וְאָמַר אֵלִיָּהוּ אֵלִיָּהוּ נְחֵית הָכָא, אַנְתְּ וַחֲיָילִין דְּנִשְׁמָתְהוֹן דְּצַדִּיקַיָּיא דִמְתִיבְתָּא עִלָּאָה וְתַתָּאָה, לְקַשְׁטָא לְכַלָּה, מִיָּד הָא נָחִית אֵלִיָּהוּ בְכַמָּה חֲיָילִין דְּמַלְאָכִין וְכַמָּה נִשְׁמָתִין.</p>\n<p>פָּתַח וְאָמַר רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל, כַּלָּה כַּמָּה מִתְתַּקְנָא רֹאשֵׁךְ בִּתְפִלִּין דְּאִיהוּ (נ\"א דאינון) פְּאֵר עַל רֹאשֵׁךְ, דַּעֲלַיְיהוּ אִתְּמַר (יחזקאל כד יז) פְּאֵרְךָ חֲבוֹשׁ עָלֶיךָ, וּרְצוּעִין תַּלְיָין מֵהַאי סִטְרָא וּמֵהַאי סִטְרָא, מַה דַּהֲווֹ תַּלְתַּלִּים שְׁחוֹרוֹת כָּעוֹרֵב, הָא אִינוּן יְרוֹקִין כַּכַּרְמֶל, כְּעַלִּין יְרוֹקִין דְּאִינוּן בַּגְּפָנִין כַּכַּרְמֶל, וּמַה דַּהֲוַת בְּגָלוּתָא דַלַּת, תְּפִלָּה לְעָנִי, וְדָא תְפִלָּה דְיָד, דְּבָהּ הוּא מִתְעַטְּפָא עָנִי בְּגָלוּתָא (ס\"א בצלותא), הֲדָא הוּא דִכְתִיב (תהלים קב א) תְּפִלָּה לְעָנִי כִי יַעֲטֹף, כְּעַן אִתְּמַר בָּךְ (שיר ז ו) וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן, מֶלֶךְ אָסוּר בָּרְהָטִים, אִלֵּין אַרְבַּע רְהִטֵי מוֹחָא, אַרְבַּע בָּתֵּי דִתְּפִלִּין דְּאִינוּן אהי\"ה, וְכֵן בְּיָד אהי\"ה, כְּחוּשְׁבַּן חַד וְעִִשְׂרִין אַזְכָּרוֹת דִתְּפִלִּין דְּרֵישָׁא, וְחַד וְעִִשְׂרִין אַזְכָּרוֹת דִתְּפִלִּין דְּיָד, וּסְלִיקוּ לְחוּשְׁבַּן אהי\"ה אהי\"ה, הוּא מֶלֶךְ אָסוּר בָּרְהָטִים, אֲשֶׁ\"ר אהי\"ה, וְאִיהוּ רֹא\"שׁ יהו\"ה קָרִינָן לֵיהּ, אָסוּר בְּכֻלְּהוּ אַזְכָּרוֹת.</p>\n<p>דָּבָר אַחֵר רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל, רֵישָׁא דִילָךְ כַּלָּה, עַל כֻּלְּהוּ חֲיָילִין סָלְקָא, (שם) עַל שִׁשִּׁים הֵמָּה מְלָכוֹת דְּאִינוּן שִׁתִּין סִדְרֵי מִשְׁנָה, וְסָלְקִין לְשִׁית מְאָה, וּלְשִׁשִּׁים רִבּוֹא, וּשְׁמֹנִים פִּלַגְשִׁים דַּהֲווֹ תְּמָנִין סִפְרֵי דְאַגַּדְתָּא, וַעֲלָמוֹת אֵין מִסְפָּר אִינוּן הֲלָכוֹת דְּלֵית לוֹן מִסְפָּר וְחוּשְׁבָּן, דְּאִינוּן נִימִין דְּשַׂעֲרִין דְּכַלָּה דְלֵית לוֹן חוּשְׁבָּנָא, וְאַנְתְּ כַּלָּה סְלִיקַת עַל כֻּלְּהוּ, הֲדָא הוּא דִכְתִיב (משלי לא כט) רַבּוֹת בָּנוֹת עָשׂוּ חָיִל וְאַתְּ עָלִית עַל כֻּלָּנָה.</p>\n<p>דָּבָר אַחֵר רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל, שַׂעֲרָא דִילָךְ כַּמָּה אִיהוּ מִתְתַּקְנָא בִּתְלַת עֲשַׂר תִּקּוּנִין, דְּאִינוּן תְּרֵי עֲשַׂר מַזָּלוֹת וְסִיהֲרָא תְּלַת עֲשַׂר, וְנִימִין דִּילָךְ אִינוּן כֹּכְבַיָּא וּמַזָּלֵי דְלֵית לוֹן חוּשְׁבָּן, וְדַלַּת רֹאשֵׁךְ, אַנְתְּ (הוא) דַהֲוִית סִיהֲרָא עֲנִיָּה תְחוֹת כֻּלְּהוּ כֹּכְבַיָּא, מְהַדְּקָא בֵּין רַגְלִין, הֲדָא הוּא דִכְתִיב (רות ג ז) וַתְּגַל מַרְגְּלוֹתָיו וַתִּשְׁכָּב, כְּעַן הָא אַנְתְּ רֵישָׁא לְכֻלְּהוּ, כָּאַרְגָּמָן דְּאִיהוּ אָמֵן יאהדונה\"י, אַנְתְּ אדנ\"י, מֶלֶךְ דְּאִיהוּ יהו\"ה, אָסוּר בָּרְהָטִים דִּילָךְ, אַרְגָּמָ\"ן א\"וּרִיאֵל רְ\"פָאֵל גַּ\"בְרִיאֵל מִ\"יכָאֵל נ\"וריאל, חֲיָילִין קַדִּישִׁין שְׁמָעוּ,</p>\n<p>כַּד חָתָן דְּאִיהוּ שִׁמְשָׁא יֵיתֵי לְאַנְהָרָא לְסִיהֲרָא, אִיהִי אִתְקַשְׁטַת בְּשַׂעֲרָהָא דִילָהּ, מִתְתַּקְנָא בִתְלַת עֲשַׂר (נ\"א בתריסר) דִּקְנִין (דרגין, תקונין), דְּאִינוּן תְּרֵיסַר מַזָּלוֹת, שִׁמְשָׁא (צ\"ל וסיהרא), (תהלים יט ו) וְהוּא כְּחָתָן יוֹצֵא מֵחֻפָּתוֹ, וְאִיהוּ יָשִׂישׂ כְּגִבּוֹר לָרוּץ אָרְחִין בִּרְקִיעָא, יָצִיץ לְגַבָּהּ וַדַּאי, הֲדָא הוּא דִכְתִיב (שיר השירים ב ט) מַשְׁגִּיחַ מִן הַחַלּוֹנוֹת מֵצִיץ מִן הַחֲרַכִּים, לְאִסְתַּכְּלָא לְגַבָּהּ בִּרְקִיעָא</p>"],[9500011289,"<p>דְאִיהוּ (ס\"א דא איהו) יָשִׂישׂ, מַאי כַּגִּבּוֹר, מַה גְּבוּרָה עָבִיד בְּהַאי, אֶלָּא תְרֵין עֲשַׂר מַשְׁקוֹפִין אִית בְּרָקִיעַ, וְכֻלְּהוּ חֲיָילִין מְקַטְרְגִין לְגַבַּיְיהוּ נְטוּרֵי תַרְעִין, שִׁמְשָׁא מִתְעַטְּרָא בְּאַתְוָון דִּתְּפִלִּין דְּאִיהוּ שֵׁם יהו\"ה, וְאִתְלַבַּשׁ בִּגְבוּרָה, הֲדָא הוּא דִכְתִיב (ישעיה מב יג) יהו\"ה כַּגִּבּוֹר יֵצֵא, וְדָא אִיהוּ יָשִׂישׂ כַּגִּבּוֹר לָרוּץ אֹרַח, וּבָקַע חַלּוֹנוֹת כֻּלְּהוּ דְרָקִיעַ, וְעָבִיד תְּרֵין עֲשַׂר אָרְחִין, כְּמָה דְעָבַד מֹשֶׁה עַל יַמָּא, וְדָא אִיהוּ לָרוּץ אֹרַח, וּבְגִין דְּנָטִיל בְּקַדְמֵיתָא מִגְּבוּרָה, שִׁמְשָׁא נָפִיק סוּמְקָא.</p>\n<p>לְבָתַר אִתְלַבַּשׁ בְּחֶסֶד דְּאִיהוּ חִוָּור, וּבֵיהּ אִשְׁתַּכַּךְ רוּגְזֵיהּ דְּשִׁמְשָׁא, יָרוֹק הֲוָה מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, וְכַד אִתְלַבַּשׁ (נ\"א אתלבן) בַּחֶסֶד בִּנְהוֹרָא חִוְורָא, מִנֵּיהּ יְהֵא נָהִיר לְסִיהֲרָא, מִקְצֵה הַשָּׁמַיִם מוֹצָאוֹ, דָּא עַמּוּדָא דְאֶמְצָעִיתָא, קָצֶה דִילָהּ צַדִּיק, וּתְקוּפָתוֹ עַל קְצוֹתָם תְּרֵי סַמְכֵי קְשׁוֹט, וּבְהוֹן אֵין נִסְתָּר מֵחַמָּתוֹ, דָּא שְׁכִינְתָּא עִלָּאָה דְאִיהִי חַמָּה, מִן תַּמָּן יִצְטַבַּע בְּגַוָּון יָרוֹק דְּאִיהוּ רַחֲמֵי, בְּהַהוּא זִמְנָא מִסְתַּכְּלִין שִׁמְשָׁא וְסִיהֲרָא כַּחֲדָא, וְאֵין נִסְתָּר מֵחַמָּתוֹ, דְאִיהִי חוּפָּה דִילָהּ.</p>\n<p>וּבְהַהוּא זִמְנָא נָטְלַת הִיא מִתְּלַת גַּוָּונִין, לְאִתְפָּאֲרָא קֳדָמֵיהּ בִּתְלַת גַּוָּונִין דְּעִינָא, דְּאִינוּן חִוָּור סוּמַק יָרוֹק, וּבְהַהוּא זִמְנָא אִיהוּ יֵימָא לְגַבָּהּ, (שיר ו ה) הָסֵבִּי עִינַיִךְ מִנֶּגְדִּי שֶׁהֵם הִרְהִיבוּנִי, מוֹקְדִין לִי בְּשַׁלְהוֹבִין דִּרְחִימוּ דִילָךְ, וּבוֹצִינָא קַדִּישָׁא תְּרֵין עַיְנִין אִנּוּן תְּרֵין לוּחִין יַקִּירִין דְּאוֹרַיְיתָא, דְאִתְּמַר בְּהוֹן (שמות לא יח) לֻחֹת אֶבֶן כְּתוּבִים בְּאֶצְבַּע אלהי\"ם (שם לב טו) כְּתוּבִים מִשְּׁנֵי עִִבְרֵיהֶם, וּמְרַקְּמָאן מִתְּרֵין עֲשַׂר גַּוָּונִין מֵהַאי סִטְרָא, וּמִתְּרֵין עֲשַׂר גַּוָּונִין מֵהַאי סִטְרָא, דְּאִינוּן אַרְבָּעָה וְעִִשְׂרִין סִטְרִין, וַעֲלַיְיהוּ אִתְּמַר (שם) מִזֶּה וּמִזֶּה הֵם כְּתְבִים, זֶ\"ה וְזֶ\"ה תְּרֵין זִמְנִין אַרְבָּעָה וְעִִשְׂרִים סְפָרִים.</p>\n<p>וְאִֹינוּן תְּרֵין עֲשַׂר אַנְפִּין וּתְרֵי עֲשַׂר גַּדְפִין דְּחֵיוָון, הֲדָא הוּא דִכְתִיב (יחזקאל א י) וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעִִתָּם גַּוָּון חִוָּור דְּעִינָא, וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל לְאַרְבַּעִִתָּם גַּוָּון סוּמַק דְּעִינָא, וּפְנֵי נֶשֶׁר לְאַרְבַּעִִתָּם אִינוּן גַּוָּון יָרוֹק דְּעִינָא, דְּאִתְּמַר (שם) וְאַרְבָּעָה פָנִים לְאֶחָד וְגוֹמֵר, וְאַרְבַּע כְּנָפַיִם וְגוֹמֵר, הָא אַרְבָּעָה וְעִִשְׂרִים, גַּדְפִין אִינוּן כַּנְפֵי עִינָא, וַעֲלַיְיהוּ אִתְּמַר מִזֶּה וּמִזֶּה הֵם כְּתֻבִים, וְחֵיוָון בְּהוֹן כְּתִיב (ישעיה ו ג) וְקָרָא זֶה אֶל זֶה וְאָמַר קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ יהו\"ה צְבָאוֹ\"ת מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ, זֶה אֶל זֶה וַדַּאי, כְּגַוְונָא דְלוּחִין דְאוֹרַיְיתָא דְאִתְּמַר בְּהוֹן כְּתוּבִים מִשְּׁנֵי עִִבְרֵיהֶם מִזֶּה וּמִזֶּה הֵם כְּתוּבִים, לֻחוֹת אֶבֶן כְּתוּבִים וְגוֹמֵר, לֻחֹת אֶבֶן, מַאי אֶבֶן, דָּא אֶבֶן הַשְּׁתִיָּיה, שֶׁמִּמֶּנָּה הוּשָׁתַת הָעוֹלָם, וְהִיא בַת עִינָא, עֲלָהּ אִתְּמַר (זכריה ג ט) עַל אֶבֶן אַחַת שִׁבְעָה עִינָיִם, וְאִינוּן שִׁבְעָה גִּלְדֵּי עִינָא, וַעֲלַיְיהוּ אִתְּמַר (תהלים קיט קסד) שֶׁבַע בַּיּוֹם הִלַּלְתִּיךָ, וְדָא מַלְכוּתָא קַדִּישָׁא, דְאִתְּמַר בָּהּ (שם קיח כב) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה, מַאי הַבּוֹנִים אִלֵּין אִינוּן מָארֵי מַתְנִיתִין דְּאִינוּן בָּנָאן בִּנְיָינִין דְּעָלְמָא, וּפוֹסְקֵי הֲלָכוֹת, דְּמָאֲסוּ בָהּ בְּגָלוּתָא, אִתְּמַר בָּהּ הָיְתָה לְרֹאשׁ פִּנָּה, בְּגִין דְּאִיהִי הֲלָכָה לְמֹשֶׁה מִסִּינַי קַבָּלָה לְמֹשֶׁה, וּמַה דַּהֲוַת בַּת עִינָא אוּכְמָא, מִינָהּ וּבָהּ יְהֵא קוּדְשָׁא בְּרִיךְ הוּא נָהִיר עָלְמָא, בְּגִין דְּאִיהוּ נָהִיר בָּהּ.</p>\n<p>וְעַיְינִין דְּנַהֲרִין בְּאוֹרַיְיתָא, עֲלַיְיהוּ אִתְּמַר (שם קמה טו) עִינֵי כֹל אֵלֶיךָ יְשַׂבֵּרוּ וְאַתָּה נוֹתֵן לָהֶם אֶת אָכְלָם בְּעִתּוֹ, וְצָרִיךְ בַּר נַשׁ לְאִתְעַסְּקָא בְּהוֹן תָּדִיר עִִרֶב וָבֹקֶר וְצָהֳרָיִם תָּמִיד, לְאִסְתַּכְּלָא בָהּ קוּדְשָׁא בְּרִיךְ הוּא בְּעִינוֹי, הֲדָא הוּא דִכְתִיב (דברים יא יב) תָּמִיד עִינֵי יהו\"ה אלהי\"ך בָּהּ מֵרֵאשִׁית הַשָּׁנָה וְעַד אַחֲרִית שָׁנָה, וְאוֹלִיפְנָא תָּמִיד מִתָּמִיד, תָּמִיד דְּעִִרֶב וָבֹקֶר, מִתָּמִיד דְּתָּמִיד עִינֵי יהו\"ה אלהי\"ך בָּהּ, וְהָא תָּמִיד דְּעִִרֶב וָבֹקֶר דִּקְרִיאַת שְׁמַע אִיהוּ, אֶלָּא מִכַּאן אוֹלִיפְנָא דְמָאן דְּקָרֵי קְרִיאַת שְׁמַע עִִרֶב וָבֹקֶר בְּכָל יוֹם תָּמִיד, כְּאִלּוּ קִיֵּים וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה בְּאוֹרַיְיתָא, הֲדָא הוּא דִכְתִיב (יהושע א ח) לֹא יָמוּשׁ סֵפֶר הַתּוֹרָה הַזֶּה מִפִּיךָ וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה, וְסֵפֶר תּוֹרָה</p>"],[9500011290,"<p>אִיהוּ עַיִן, תְּרֵי כַּנְפֵי עִינָא תְּרֵי לוּחֵי, וַעֲלַיְיהוּ אִתְּמַר תָּמִיד עִינֵי יהו\"ה אלהי\"ך בָּהּ מֵרֵאשִׁית הַשָּׁנָה, וּמַאי בָּהּ, בְּבַת עַיִן דְּאִיהִי שְׁכִינְתָּא, וְכַנְפֵי עִינָא עֲלַיְיהוּ אִתְּמַר (תהלים קיח יט) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק, תְּלַת גַּוָּונִין כְּלָל וּפְרָט, וּכְלָל וְאִינוּן אהי\"ה אֲשֶׁר אהי\"ה, דְּאִינוּן כְּלָל בְּכָל אוֹרַיְיתָא, אהי\"ה כְּלָל, אֲשֶׁר פְּרָט, אהי\"ה כְּלָל. קְרִיצִין דְּעַל עַיְינִין, עֲלַיְיהוּ אִתְּמַר (שיר ה יא) תַּלְתַּלִּים שְׁחוֹרוֹת כָּעוֹרֵב, וְאִינוּן תִּלֵּי תִּלִּים. מִצְחָא דְעַל עַיְינִין בָּהּ צִיץ נֶזֶר הַקֹּדֶשׁ, מְרוּקָם בְּגַוָּונִין וְצִיּוּרִין דְּבֵי מַקְדְּשָׁא דִלְעִילָא, וְצִיּוּרִין דִּילָהּ שִׁרְטוּטִין בְּפוּתְיָא וּבְאוּרְכָּא, מִנְּהוֹן דְּקִיקִין מִנְּהוֹן רַבְרְבִין, וַעֲלַיְיהוּ אִתְּמַר בְּמָקוֹם שֶׁאָמְרוּ לְהַאֲרִיךְ אֵינוֹ רַשַּׁאי לְקַצֵּר, לְקַצֵּר אֵינוֹ רַשַּׁאי לְהַאֲרִיךְ, לְהַאֲרִיךְ מִסִּטְרָא דְו', לְקַצֵּר מִסִּטְרָא דְי'.</p>\n<p>אַנְפּוֹי דְמַטְרוֹנִיתָא, אִינוּן מ\"ט אַנְפִּין טָהוֹר, נַהֲרִין כְּשׁוֹשַׁנָּה חִוָּור וְסוּמַק, נָטְלִין מִימִינָא וּשְׂמָאלָא, גַּוָּון חִוָּור בְּלִיבּוּן דַּעֲנָוָה, סוּמַק בֹּשֶׁת דִּדְחִילוּ, יְרָא בֹשֶׁת, כַּד אִתְחַזְּרוּ יְרוֹקִין, הָא חָתָן דִּילָהּ אִסְתַּלַּק לְגַבֵּי חַמָּה דְאִיהִי אִימָּא עִלָּאָה, וּמֵאִלֵּין תְּלַת גַּוָּונִין דְּאַנְפִּין תַּלְיָין שַׁבְעִין וּתְרֵין אַנְפִּין כְּחוּשְׁבַּן חֶסֶ\"ד, וּבְהוֹן יר\"ו אַתְוָון כְּחֻשְׁבַּן גְּבוּרָ\"ה, וְדָא אִיהוּ רָזָא דְוַיַּעֲבֹר יהו\"ה, רָזָא דְעִיבּוּר, נָהִיר בְּהוֹן לְגַבֵּי כַלָּה בְּאַרְבַּע אַנְפִּין, הֲדָא הוּא דִכְתִיב (יחזקאל א ו) וְאַרְבָּעָה פָנִים לְאֶחָת, וְעַמּוּדָא דְאֶמְצָעִיתָא אִיהוּ וָא\"ו עִיבּוּר הַשָּׁנָה, דְאִית בָּהּ תְּלַת עֲשַׂר יַרְחִין, וְאִנּוּן וְאִיהִי בְּרָאשֵׁי תֵּיבִין וָ\"הוּ אֲ\"נִי וָ\"הוּ, וּבֵיהּ אִיהוּ אִשָּׁה (נ\"ל איש) וְאִיהִי אִשָּׁה עוּבָרָה, סוֹד הָעִבּוּר יְסוֹד, דְּאִיהוּ יְסוֹד טִפָּה, דְמִינָהּ אִתְעֲבִידַת עִבּוּר, דְּאִיהוּ וא\"ו, דְּהָא וָא\"ו בְּלָא טִפָּה לֵית לָהּ עִבּוּר, וְדָא אִיהוּ מוֹחָא דְתַמָּן חָכְמָה.</p>\n<p>וָא\"ו אִיהוּ חוֹטָמָא מִתְתַּקְנָא בְּאַנְפִּין, עֲלַיְיהוּ אִתְּמַר (בראשית ב ז) וַיִּיצֶר יהו\"ה אלהי\"ם, וְנַהֲרִין בְּחִוָּור וְסוּמַק, וְחוֹטָמָא דְאָזְלָא בְאֹרַח מֵישַׁר אִיהִי חוֹתָם אֱמֶת, וְאִם לַאו אִיהִי בְאֹרַח קְשׁוֹט לַאו אִיהִי חוֹתָמָא דְגוּשְׁפַּנְקָא דְמַלְכָּא, וּבְגִין דָּא צִיּוּרָא דְמַטְרוֹנִיתָא דִיּוֹקְנָא דִילָהּ דְּחוֹטָמָא, מִתְתַּקְנָא בְּאַנְפִּין וּבְאֹרַח מֵישַׁר עַל אַנְפִּין, וּתְרֵין נוּקְבִין דְּחוֹטָמָא תְּרֵי נְבִיאֵי קְשׁוֹט, פִּימָא בְרַתָּא דְמַלְכָּא, וּבָהּ לְשׁוֹן לִמּוּדִים דְּאִיהוּ צַדִּיק, וַעֲלָהּ (נ\"א ועלייהו) אִתְּמַר (שיר ד ג) כְּחוּט הַשָּׁנִי שִׂפְתוֹתַיִךְ וּמִדְבָּרֵךְ נָאוְה בְּאוֹרַיְיתָא, פִּימָא כְּלָלָא דְכֹלָּא, מִינָהּ קוֹל וְדִבּוּר דְּאִינוּן ו\"ה, מִינָהּ הֲבַל דְּאִיהִי ה', פִּימָא דְקִיקָא סְתִימָא בְּאוֹת י', מִתְתַּקְנָא בִשְׁמָא דַיהו\"ה, וּבְגִין דָּא כְּחוּט הַשָּׁנִי שִׂפְתוֹתַיִךְ וּמִדְבָּרֵךְ נָאוְה.</p>\n<p>צַוָּארֵךְ כְּמִגְדַּל הַשֵּׁן (שם ז ה), דָּא יְרוּשָׁלַםִ, עֲלָהּ אִתְּמַר (שם ד ד) כְּמִגְדַּל דָּוִד צַוָּארֵךְ, תַּכְשִׁיטִין דִּילָהּ כֹּהֲנִים לְוִיִּים יִשְׂרְאֵלִים, בָּנוּי לְתַלְפִּיּוֹת דָּא צַדִּיק דְּאִיהוּ תֵּל שֶׁהַכֹּל פּוֹנִים בּוֹ, פִּנּוֹת דִּילֵיהּ תְּרֵין נְבִיאֵי קְשׁוֹט, דִּשְׁכִינְתָּא וַדַּאי אִיהִי יְרוּשָׁלַם, תַּכְשִׁיטִין דִּילָהּ תְּלַת אֲבָהָן, חֲרוּזִין דִּילָהּ תְּרֵי סַמְכֵי קְשׁוֹט.</p>\n<p>דָּבָר אַחֵר צַוָּארֵךְ דָּא אוֹרַיְיתָא, תַּכְשִׁיטִין דִּילָהּ רְמַ\"ח פִּקּוּדִין דִּילָהּ, חֲרוּזִין וּקְמִיעִין דִּילָהּ אִינוּן מְמַנָּן עַל שְׁסָ\"ה לֹא תַעֲשֶׂה, דְנָטְרִין לָהּ בְּהוֹן, וְכַד אִסְתַּלַּק צַוָּאר בְּתַכְשִׁיטִין דִּילָהּ לְגַבֵּי חָתָן, כַּמָּה רֵיחִין טָבִין סָלְקִין בָּהּ, הֲדָא הוּא דִכְתִיב (שם ג ו) מִי זֹאת עוֹלָה מִן הַמִּדְבָּר, דָּא טוּרָא דְסִינַי דְּאִיהִי צַוָּאר עָלְמָא, (שם) מְקֻטֶּרֶת מֹר דָּא קוּדְשָׁא בְּרִיךְ הוּא, דְאִתְּמַר בֵּיהּ (שם ד) אֵלֶךְ לִי אֶל הַר הַמּוֹר, וּלְבוֹנָה דָא סִיהֲרָא קַדִּישָׁא, עֲלָהּ אִתְּמַר וְאֶל גִּבְעַת הַלְּבוֹנָה, מִכֹּל אַבְקַת רוֹכֵל דָּא צַדִּיק, דְּאִיהוּ כָּל כָּלִיל בְּכֹלָּא.</p>\n<p>דָּבָר אַחֵר צַוָּארֵךְ דָּא אוֹרַיְיתָא דִבְעַל פֶּה, הֲלָכָה לְמֹשֶׁה מִסִּינַי, מְקֻטֶּרֶת מוֹר אָמַר מַר, וּלְבוֹנָה לִבּוּן הַהֲלָכָה, מִכֹּל אַבְקַת רוֹכֵל דָּא צַדִּיק דְּאִית בֵּיהּ מִכָּל מִינִים, וְדָא נָהִיר לָהּ לְאוֹרַיְיתָא דִבְעַל פֶּה, וּמִיָּד</p>"],[9500011291,"<p>דְּאִיהִי מִתְקַשְּׁטָא בְּכָל מִינֵי תַּכְשִׁיטִין, יְרוּשָׁלַםִ דְּאִיהוּ צַוָּאר עָלְמָא, קוּדְשָׁא בְּרִיךְ הוּא אַסְחַר לָהּ, הֲדָא הוּא דִכְתִיב (זכריה ה ט) וַאֲנִי אֶהְיֶה לָּהּ נְאֻם יהו\"ה חוֹמַת אֵשׁ סָבִיב, וְאִיהוּ מְחַבֵּק לָהּ בִּתְרֵין דְּרוֹעִין, הֲדָא הוּא דִכְתִיב (שיר השירים ב ו) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי.</p>\n<p>וִידִין דְּמַטְרוֹנִיתָא כַּלָּה קַדִּישָׁא, אִינוּן רְשִׁימִין כֻּלְּהוּ בִּשְׁמָא דְיהו\"ה, כְּגַוְונָא דָא (אמר המגיה הלשון מוטעה ונ\"ל שהלשון כך) בְּכַף י', בְּחָמֵשׁ אֶצְבְּעָן ה', בִּדְרוֹעָא דִילָהּ ו', בְּכָתֵף דִּילָהּ ה', בְּכָתֵף דִּילָהּ מְצוּיָירִין כַּמָּה שִׁרְטוּטִין כְּעַנְפִין דְּאִילָנָא דְחַיֵּי, לְרַשְׁמָא בֵּיהּ דְּאִיהוּ עִץ הַחַיִּים, הֲדָא הוּא דִכְתִיב (משלי ג יח) עִץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ וְתֹמְכֶיהָ מְאֻשָּׁר, מִימִינָא דִילֵיהּ אִתְיְיהִיבַת אוֹרַיְיתָא דְבִכְתָב, מִשְּׂמָאלָא דִילֵיהּ אוֹרַיְיתָא דִבְעַל פֶּה, וּבְאָן אִתְיְיהִיבוּ בִּתְרֵין לוּחִין, דְּאִתְּמַר בְּהוֹן (שיר ד ה) שְׁנֵי שָׁדַיִךְ כִּשְׁנֵי עֳפָרִים תָּאֳמֵי צְבִיָּה.</p>\n<p>וְעוֹד ו' אִיהוּ אוֹרַיְיתָא דְבִכְתָב, דְּאִתְיְיהִיבַת בִּתְרֵין דְּרוֹעִין דְּאִינוּן שִׁית פִּרְקִין, וּבְאָן אִתְיְיהִיבַת בִּתְרֵין לוּחִין, דְּאִינוּן שְׁנֵי שָׁדַיִךְ, וְאִינוּן י' י' (ובהון צורת ז'), וּבְהוֹן צָר, הֲדָא הוּא דִכְתִיב וַיִּיצֶר, וְאִינוּן בְּתוּלִין דְּעְִלֵימְתָא דְאִיהִי אוֹרַיְיתָא דִבְעַל פֶּה, דְּאִתְּמַר בְּהוֹן (שמות לב יט) וַיְשַׁבֵּר אֹתָם תַּחַת הָהָר חָתָן דִּילָהּ, הַהוּא דְאָמַר (דברים כב כ) לֹא נִמְצְאוּ בְתוּלִים לַנַּעֲרָה (שם יט), וְעָנְשׁוּ אוֹתוֹ מֵאָה כֶסֶף אִלֵּין מֵאָה בִּרְכָאָן (שם), וְלוֹ תִהְיֶה לְאִשָּׁה לֹא יוּכַל לְשַׁלְּחָהּ בְּגָלוּתָא כָּל יָמָיו.</p>\n<p>שְׁבָחָא דְגוּפָא, (שיר ז ח) זֹאת קוֹמָתֵךְ דָּמְתָה לְתָמָר, וּמָאן דְּיָדַע שִׁעוּר קוֹמָה דִילָהּ אִיהוּ יָרִית עָלְמָא דְאָתֵי דְּאִיהוּ ו', דְּאִתְּמַר בֵּיהּ (ירמיה יז יג) מִקְוִה יִשְׂרָאֵל יהו\"ה, מִקְוְה דְאִיהוּ קוֹמָה דִילָהּ שִׁעוּר דִּילָהּ, שִׁעוּר קוֹמָה דָא צַדִּיק, דְּאִתְּמַר בֵּיהּ (תהלים צב יג) צַדִּיק כַּתָּמָר יִפְרָח, וַעֲלָהּ אִתְּמַר דָּמְתָה לְתָמָר.</p>\n<p>דְּאִתְּמַר בָּהּ, (שמות טו כז) וַיָּבֹאוּ אֵלִימָה וְשָׁם שְׁתֵּים עִִשְׂרֵה עִינֹת מַיִם וְשִׁבְעִים תְּמָרִים, תְּרֵין עֲשַׂר עִינוֹת אִלֵּין אִינוּן תְּרֵין עֲשַׂר פִּרְקִין, דְּאִינוּן שִׁית בִּתְרֵין דְּרוֹעִין וְשִׁית בִּתְרֵין שׁוֹקִין, הֲדָא הוּא דִכְתִיב (שיר השירים ה יד) יָדָיו גְּלִילֵי זָהָב מְמֻלָּאִים בַּתַּרְשִׁישׁ, מַאי בַּתַּרְשִׁישׁ בִּתְרֵי שֵׁשׁ, בִּתְרֵין דְּרוֹעִין שִׁית פִּרְקִין, וְכֵן שִׁית אָחֳרָנִין בִּתְרֵין שׁוֹקִין, (שם טו) שׁוֹקָיו עַמּוּדֵי שֵׁשׁ, אִלֵּין אִינוּן י\"ב עִינוֹת מַיִם. שִׁבְעִים תְּמָרִים דִּי בְהוֹן צַדִּיק כַּתָּמָר יִפְרָח הָא אִינוּן חָמֵשׁ אֶצְבְּעָאן, וּבְהוֹן תְּלֵיסַר פִּרְקִין, אִינוּן חַ\"י, וְכֵן חַ\"י בְּיַד יָמִין, תְּלָתִין וְשִׁית, וְכֵן חַ\"י חַ\"י בִּתְרֵין רַגְלִין, הָא ע\"ב, (אמר המגיה תימה כי הפרקין ארבסר ואיך אמר תליסר), שַׁבְעִין דִּלְהוֹן שַׁבְעִין תְּמָרִים, תְּרֵין צַדִּיקֵי כַּתָּמָר יִפְרָח בְּהוּ.</p>\n<p>וּבְהוֹן כְּתִיב (שם ז ב) מַה יָּפוּ פְעָמַיִךְ בַּנְּעָלִים בַּת נָדִיב, נְעָלִים דִּילָהּ נְעִילַת הֶחָג וּנְעִילַת הַפֶּסַח, וְלָא צָרִיךְ לְאִתְחַזָּאָה קֳדָם נְעָלִים דְּחוֹל, דְּאִינוּן שְׂאוֹר וְחָמֵץ, וַעֲלַיְיהוּ אָמַר לְמֹשֶׁה (שמות ג ה) שַׁל נְעָלֶיךָ מֵעַל רַגְלֶיךָ, דִּתְרוּמָה וְחוּלִין כְּגַוְונָא דָא לָא צָרִיךְ לְאִתְעָרְבָא תְּרוּמָה בַּקֹּדֶשׁ, וְכֵן מְלָאכָה דְחוֹל לָא צָרִיךְ לְאִתְחַזָּאָה קֳדָם מְלָאכָה דְקֹדֶשׁ דְּאִיהוּ מְלֶאכֶת הַכֹּהֲנִים, וְכֵן אֵשׁ דְּחוֹל לָא צָרִיךְ לְאִתְחַזָּאָה בְּשַׁבָּת קֳדָם אֵשׁ דְּקֹדֶשׁ, דְּכֻלְּהוּ חוֹל וְאָחֳרָנִין קֹדֶשׁ, וּבְגִין דָּא מַנִּי הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחוֹל.</p>\n<p>הָא צִיּוֹן דְּאִיהִי שְׁכִינְתָּא נָפְקָא בְכָל קִשּׁוּטִין דִּילָהּ, וְכָל עָלְמָא מוֹרִין לָהּ בְּאֶצְבַּע, הֲדָא הוּא דִכְתִיב (ישעיה לג כ) חֲזֵה צִיּוֹן קִרְיַת מוֹעֲדֵנוּ, וְחָתָן נָפִיק מְעוּטָּר לְגַבָּהּ, וְכָל עָלְמָא אָמְרֵי (שיר ג יא) צְאֶנָה וּרְאֶנָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה בַּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ בְּיוֹם חֲתוּנָּתוֹ וּבְיוֹם שִׂמְחַת לִבּוֹ, חֲתוּנָּתוֹ שְׁכִינְתָּא עִלָּאָה, שִׂמְחַת לִבּוֹ שְׁכִינְתָּא תַּתָּאָה, יוֹם דְּתַרְוַיְיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, בּוֹצִינָא קַדִּישָׁא הָא כַּלָּה מִתְקַשְּׁטָא לְגַבֵּי בַעִִלָהּ דְּאִיהוּ יהו\"ה, בְּרָא דְמַלְכָּא.</p>\n<p>(זהו תקון כז)</p>"],[9500011292,"<p>דָּא אִיהוּ בְּרֵאשִׁית בָּרָא אלהי\"ם, בְּרֵאשִׁית אַבָּא וְאִימָּא, יהו\"ה אלהינ\"ו, בָּרָא יהו\"ה, בְּרָא דְאַבָּא וְאִימָּא, אלהי\"ם בְּרַתָּא, וַעֲלַיְיהוּ אִתְּמַר (ויקרא יט ג) אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ, (שמות כ יב) כַּבֵּד אֶת אָבִיךָ וְאֶת אִמֶּךָ, אָבִיךָ דָּא קוּדְשָׁא בְּרִיךְ הוּא, אִמֶּךָ דָּא שְׁכִינְתָּא, דְחִילוּ דִילָהּ בְּפִקּוּדִין דְּלֹא תַעֲשֶׂה, אוֹקִירוּ דִילָהּ בְּפִקּוּדִין דַּעֲשֵׂה, וְכָל אִינוּן דִּמְקַיְּימֵי פִקּוּדֵי דַעֲשֵׂה עֲלַיְיהוּ אִתְּמַר (שמואל א ב ל) כִּי מְכַבְּדַי אֲכַבֵּד, וְאִינוּן דְּעָבְרִין עַל לֹא תַעֲשֶׂה עֲלַיְיהוּ אִתְּמַר וּבֹזַי יֵקָלּוּ. אָמַר בּוֹצִינָא קַדִּישָׁא רַבִּי רַבִּי, וּמָה הוּא אוֹקִירוּ וּבִזָּיוֹן לְקוּדְשָׁא בְּרִיךְ הוּא בְפִקּוּדִין דַּעֲשֵׂה וְלֹא תַעֲשֶׂה, אֶלָּא בְּוַדַּאי כַּד שְׁכִינְתָּא אִיהִי בְּגָלוּתָא, כָּל מָאן דְּעָבִיד מִצְוָה לְאַקָּמָא לָהּ מִן גָּלוּתָא, כְּאִלּוּ אוֹקִיר לְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>לְמַלְכָּא דַהֲוָה לֵיהּ קְטָטָה עִם מַטְרוֹנִיתָא, וְאָרְמָא לָהּ מִן הֵיכָלֵיהּ, וְאִיהִי אָזְלַת לְגַבֵּי שְׁכִינָהָא, וַהֲלָא כָּל מָאן דִּמְקַבֵּל לָהּ בְּבֵיתֵיהּ וְאוֹקִיר לָהּ (ודאי אוקיר למלכא), וְעַאִיל שְׁלָם בֵּינָהָא וּבֵין בַּעִִלָהּ, הֲלָא כָּל יְקָרָא דְעָבִיד לָהּ לְמַלְכָּא עָבִיד, דְּאִם מַלְכָּא כָּעַס עֲלָהּ זִמְנָא חֲדָא אוֹ תְּרֵין, יְהֵא לֵיהּ שְׁלָם עִמָּהּ וְיַחֲזִיר לָהּ לְבֵיתֵיהּ, וְאִיהוּ שָׁאִיל לָהּ מָאן אוֹקִיר לָךְ אוֹ מָאן זִלְזֵל בָּךְ, אוֹ אִם תָּרִיךְ לָהּ לְמַלְכוּתָא אַחֲרָא.</p>\n<p>כְּגַוְונָא דָא קוּדְשָׁא בְּרִיךְ הוּא תָּרִיךְ לָהּ לִשְׁכִינְתָּא, וְאַרְמֵי לָהּ מִבֵּיתֵיהּ, הֲדָא הוּא דִכְתִיב (ישעיה נ א) וּבְפִשְׁעִיכֶם שֻׁלְּחָה אִמְּכֶם, וַהֲלָא כָּל מָאן דְּאוֹקִיר לָהּ בְּגָלוּתָא לְקוּדְשָׁא בְּרִיךְ הוּא אוֹקִיר, אוֹ מָאן דִּמְזַלְזֵל בָּהּ לְקוּדְשָׁא בְּרִיךְ הוּא מְזַלְזֵל, וּבְגִין דָּא כִּי מְכַבְּדַי אֲכַבֵּד וּבוֹזַי יֵקָלּוּ, דְּאַף עַל גַּב דְּקוּדְשָׁא בְּרִיךְ הוּא זַבִּין לָהּ בְּחוֹבִין דִּבְנָהָא בְּגָלוּתָא רְבִיעָאָה, אִיהוּ נָטִיר לָהּ וְאִיהוּ יִפְרוֹק לָהּ, וְרָזָא דְמִלָּה (שמות כא ז) וְכִי יִמְכּוֹר אִישׁ אֶת בִּתּוֹ לְאָמָה לֹא תֵצֵא כְּצֵאת הָעֲבָדִים, אֶלָּא תִּפּוֹק בַּת חוֹרִין, בְּגִין דִּבְגָלוּתָא קַדְמָאָה דְלָא הֲוַת לָהּ בַּעִִלָהּ דְּאִיהִי אוֹרַיְיתָא חֵירוּ דִילָהּ, לָא נָפְקַת לָהּ בַּת חוֹרִין, וְנָפְקַת בְּחִפָּזוֹן כְּעַבְדָּא דְבָרַח מֵרִבּוֹנֵיהּ וְלָא אִית לָהּ שְׁטַר חֵירוּ, אֲבָל בְּפוּרְקָנָא בַתְרַיְיתָא דְאִית לָהּ בַּעִִלָהּ דְּאִיהוּ בֶן חוֹרִין, לֹא תֵצֵא בְּחִפָּזוֹן וְלֹא תֵצֵא כְעַבְדִין, דְּאִתְּמַר בְּהוֹן עֲבָדִים הָיִינוּ לְפַרְעֹה בְּמִצְרָיִם, אֶלָּא תִּפּוֹק בַּת חוֹרִין, וּבְגִין דָּא כִי יִמְכּוֹר אִישׁ אֶת בִּתּוֹ לְאָמָה לֹא תֵצֵא כְּצֵאת הָעֲבָדִים.</p>\n<p>וּמְנָלָן דְּאוֹרַיְיתָא אִיהוּ חֵירוּת, הֲדָא הוּא דִכְתִיב (שמות לב טז) וְהַמִּכְתָּב מִכְתַּב אלהי\"ם הוּא חָרוּת עַל הַלֻּחֹת, וְאִיהוּ יְהֵא לָהּ בְּפוּרְקָנָא בַּתְרַיְיתָא חֵרוּת מִמַּלְאַךְ הַמָּוְת, דְּלָא יָמוּת מָשִׁיחַ בֶּן אֶפְרַיִם, חֵרוּת מִשִּׁעִִבּוּד מַלְכִיּוֹת דְּלָא יִשְׁתַּעִִבְּדוּן בָּהּ וּבִבְנָהָא לְעָלַם, וִיהֵא לָהּ חֵירוּ וְלִבְנָהָא מִכָּל מַרְעִין בִּישִׁין דְּעָלְמָא דְּאִינוּן עִרֶב רַב, וְיִשְׂרָאֵל דְּאִינוּן מִסִּטְרָא דְהַהוּא נַעַר אוֹ מִכָּרְסַיָּא קַדִּישָׁא, אַף עַל גַּב דַּהֲווֹ מְחוּיָיבִין בְּכַמָּה חוֹבִין, כְּמָה דְאָמְרִין אֵין בֶּן דָּוִד בָּא עַד שֶׁיִּהְיֶה דוֹר שֶׁכֻּלּוֹ זַכַּאי אוֹ כֻּלּוֹ חַיָּיב, אִתְּמַר בְּהוֹן (שם כא ח) אִם רָעָה בְּעִינֵי אֲדוֹנֶיהָ אֲשֶׁר לֹא יְעָדָהּ, עִם כָּל דָּא וְהֶפְדָּהּ בְּגָלוּתָא, וְלֹא יִמְשׁוֹל לְמוֹכְרָהּ בְּגָלוּתָא, בְּבִגְדוֹ בָהּ, בְּגִין דְּבָגְדוּ בַעֲבוֹדָה זָרָה.</p>\n<p>וְעוֹד כִי יִמְכּוֹר אִישׁ אֶת בִּתּוֹ לְאָמָה, דָא נִשְׁמָתָא קַדִּישָׁא, דְמָכַר לָהּ בְּגוּפָא דְאִיהוּ אָמָה דִילָהּ, וְאִתְּמַר (משלי ל כג) וְשִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ, כַּד תִּפּוֹק מִגּוּפָא לֹא תֵצֵא כְּצֵאת הָעֲבָדִים, דְּאִינוּן נְפָשׁוֹת דְּאִינוּן מְשׁוּתָּפִין עִם גּוּפָא תַּתָּאָה, דַהֲנָאָה דִלְהוֹן לַאו אִיהִי לְעָלְמָא דְאָתֵי, לְאִשְׁתַּדְלָא בְאוֹרַיְיתָא דְאִיהוּ חֵירוּ מִמַּלְאַךְ הַמָּוְת, אֶלָּא לְיָרְתָא לְעָלְמָא דֵין, וּבְגִין דָּא נִשְׁמָתָא דְאִיהִי אִשְׁתַּדְלָא בְּאוֹרַיְיתָא, לֹא תֵצֵא כְּצֵאת הָעֲבָדִים מִגּוּפָא בְּדוֹחֲקָא, כְּנִשְׁמָתָא דְעַם הָאָרֶץ דְּאִיהִי עִִבֶד, אֶלָּא תִּיפּוֹק בַּר חוֹרִין מִמַּלְאַךְ הַמָּוְת.</p>\n<p>(זהו תקון כ\"ח)</p>\n<p>בְּרֵאשִׁית,</p>"],[9500011293,"<p>דָּא בְּאֵר (נ\"א באר שית), וְאִינוּן תְּרֵין, חַד (במדבר כא א) בְּאֵר חֲפָרוּהָ שָׂרִים כָּרוּהָ נְדִיבֵי הָעָם, חַד אִיהוּ בְּאֵר דְּאִתְּמַר בָּהּ (בראשית כו כא) וַיָּרִיבוּ גַּם עָלֶיהָ, וְתִנְיָינָא בְּאֵר אַחֶרֶת וְלֹא רָבוּ עָלֶיהָ, בְּאֵר דְּרָבוּ עָלֶיהָ דָּא אוֹרַיְיתָא דִבְעַל פֶּה, דְּאִתְּמַר בָּהּ (שם כ) וַיָּרִיבוּ רוֹעִי גְרָר עִם רוֹעִי יִצְחָק לֵאמֹר לָנוּ הַמָּיִם, אִלֵּין מַקְשִׁין עַל אִלֵּין, וְאִלֵּין חוֹלְקִין עַל אִלֵּין, אִלֵּין מְטַהֲרִין וְאִלֵּין מְטַמְּאִין, אִלֵּין פּוֹסְלִין וְאִלֵּין מַכְשִׁירִין, אִלֵּין אוֹסְרִין וְאִלֵּין מַתִּירִין, בְּשִׁית סִטְרִין, וְאִינוּן בְּרֵאשִׁית בָּרָא שִׁית וכו'.</p>\n<p>(זהו תקון כ\"ט)</p>\n<p>בְּרֵאשִׁית בָּרָא שִׁית סִטְרִין דְּאִסּוּר וְהֶתֵּר כִּדְקָאַמְרָן, וַעֲלֵיהּ אִתְּמַר (במדבר יד יז) וְעַתָּה יִגְדַּל נָא כֹּחַ אדנ\"י, וְאִיהִי כ\"ח אַתְוָון דְּעוֹבָדָא דִבְּרֵאשִׁית, בְּהַאי (נ\"א דאיהו) כ\"ח תַּלְמִידֵי חֲכָמִים (בראשית כו כב) וַיַּחְפְּרוּ בְּאֵר אַחֶרֶת וְלֹא רָבוּ עָלֶיהָ, דְּאִיהִי הֲלָכָה לְמֹשֶׁה מִסִּינַי קַבָּלָה לְמֹשֶׁה מִסִּינַי, וּמֹשֶׁה בְּגִינָהּ בְּזִמְנָא דְאָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא אֵין שָׁלוֹם בְּעִירָךְ, אָמַר וְעַתָּה יִגְדַּל נָא כֹּחַ אדנ\"י, וְאִיהִי תַּלְמוּד דְּאִתְּמַר לְמֹשֶׁה, מֹשֶׁה קִבֵּל תּוֹרָה מִסִּינַי, מִשְׁנָה שִׁפְחָה דִילָהּ, דָּא אִתְעֲבִיד לַהֲלָכָה דְאִיהִי בְּרַתָּא דְמַלְכָּא לְבוּשָׁא, וּבְרַתָּא דְּמַלְכָּא אִיהִי בַּת קוֹל מִלְּגָאו, וּבְרַיְיתָא אִיהִי שִׁפְחָה לָהּ מִלְּבָר, וְאִלֵּין תְּרֵין סָמְכִין לָהּ לִבְרַתָּא דְמַלְכָּא בְגָלוּתָא מִשְׁנָה וּבְרַיְיתָא.</p>\n<p>וְאִית שִׁפְחָה בִּישָׁא דְאִתְקְרִיאַת שִׂטְנָה, הֲדָא הוּא דִכְתִיב (בראשית כו כא) וַיִּקְרָא אֶת שְׁמָהּ שִׂטְנָה, אִתְּתָא דְנָחָשׁ דְּאִיהוּ שָׂטָן, וְדָא אִיהוּ מַחֲלֹקֶת וְקוּשְׁיָא, וַעֲלָהּ אִתְּמַר (שמות א יד) וַיְמָרְרוּ אֶת חַיֵּיהֶם בַּעֲבוֹדָה קָשָׁה, דְּוַדַּאי דָּא אִיהוּ קוּשְׁיָא, בְּחוֹמֶר דָּא קַל וָחֹמֶר, דָּא נָחָשׁ עֲקַלָּתוֹן מַחֲלֹקֶת, זִמְנָא אִיהוּ קַל בְּשִׁעִִבּוּדָא דְיִשְׂרָאֵל כַּד חוֹבִין קַלִּין עֲלַיְיהוּ, וְזִמְנָא דְאִיהוּ חָמוּר כָּבֵד, וּמִסִּטְרָא דִילֵיהּ (שם ה ט) תִּכְבַּד הָעֲבֹדָה.</p>\n<p>וְנָחָשׁ אִיהוּ אָזִיל בְּקוּשְׁיָא וּמַחֲלוֹקֶת, כְּגַוְונָא דְגַלֵּי יַמָּא, כְּגַוְונָא דָּא כַּד חָשִׁיב בַּר נַשׁ דְּאִיהוּ בְּקוּשְׁיָא וּמַחֲלֹקֶת לְתַתָּא בְּסֵיפָא דְּמַתְנִיתִין, אַשְׁכַּח לָהּ בְּרֵישָׁא, וְכַד חָשִׁיב דְּאִיהוּ בְרֵישָׁא, אַשְׁכַּח לָהּ בְּסֵיפָא, וּלְבָתַר פַּלִּיג בְּאֶמְצָעִיתָא דְמַתְנִיתִין, וַיַּחְפְּרוּ בְּאֵר אַחֶרֶת דָּא פְּסִיקְתָּא, דְּתַמָּן פִּסְקֵי הֲלָכָה וְאִיהוּ תִּרוּץ, וְלֹא רָבוּ עָלֶיהָ וַיִּקְרָא שְׁמָהּ רְחוֹבוֹת, וְאִלֵּין פִּסְקִין וְתִרוּצִין אִינוּן לְבֵנִים, דְּאִינוּן לִבּוּן הַהֲלָכָה, וְדָא אִיהוּ וּבִלְבֵנִים, וּבְכָל עֲבוֹדָה בַּשָּׂדֶה וַדַּאי דָּא בְרַיְיתָא, דַעֲלָהּ אִתְּמַר (דברים כב כז) כִּי בַשָּׂדֶה מְצָאָהּ וְגוֹמֵר, אֵת כָּל עֲבֹדָתָם זוֹ מִשְׁנָה, שִׁפְחָה תִּנְיָינָא לִבְרַיְיתָא, אֲשֶׁר עָבְדוּ בָהֶם בְּפָרֶךְ, הַכֹּל תָּלוּי עַד שֶׁיָּבֹא אֵלִיָּהוּ, דָא שִׁפְחָה תְּלִיתָאָה דְאִיהִי אִקְרֵי עֲבוֹדָה (עיבוד ה'). קָם יְנוּקָא חֲדָא, פָּתַח וְאָמַר (איוב לב ו) צָעִיר אֲנִי לְיָמִים וְאַתֶּם יְשִׁישִׁים.</p>\n<p>(זהו תיקון ל')</p>\n<p>בְּ\"רֵאשִׁית בָּ\"רָא אֱ\"לֹהִים דָּא בָּבָ\"א, וְאִינוּן תְּלַת בָּבֵי דְאִתְרְמִיזוּ בִּתְלַת אַנְפִּין בְּרֵא\"שִׁית בָּרָ\"א אֱ\"לֹהִים, וַעֲלָהּ אִתְּמַר (שמות כב ח) עַל כָּל דְּבַר פֶּשַׁע עַל שׁוֹר עַל חֲמוֹר דָּא בָּבָא קַמָּא, עַל שֶׂה עַל שַׂלְמָה דָּא בָּבָא מְצִיעָא, עַל כָּל אֲבֵדָה אֲשֶׁר יֹאמַר כִּי הוּא זֶה דָא בָּבָא בַּתְרָא, עַל שׁוֹר בֵּיהּ מִתְוַכְּחִים מָארֵי מַתְנִיתִין דָּא עִם</p>"],[9500011294,"<p>דָּא, וְאִית שׁוֹר וְאִית שׁוֹר, שׁוֹר תָּם וְשׁוֹר מוּעָד, וְאִית חֲמוֹר וְאִית חֲמוֹר, וְעַל אִלֵּין דְּסִטְרָא דִמְסָאֲבוּ אִתְּמַר בְּהוֹן (דברים כב י) לֹא תַחֲרוֹשׁ בְּשׁוֹר וּבַחֲמוֹר יַחְדָּו, וְיַעֲקֹב בְּגִינַיְיהוּ אָמַר (בראשית לב ו) וַיְהִי לִי שׁוֹר וַחֲמוֹר, צֹאן דָּא שֶׂה דְּאִתְּמַר בֵּיהּ עַל שֶׂה, וְעִִבֶד וְשִׁפְחָה דָא אִיהוּ עַל כָּל אֲבֵדָה.</p>\n<p>וְשׁוֹר מוּעָד, אַרְבָּעָה וְעִִשְׂרִים תּוֹלָדוֹת דִּנְזִיקִין תַּלְיָין מִנֵּיהּ, וְכֻלְּהוּ תַלְיָין מֵאַרְבַּע אָבוֹת דְּאִינוּן קֶרֶן וְשֵׁן וְגוּף וְרֶגֶל, נְגִיחָה בְּקֶרֶן, שֵׁן דַּהֲוָה אָכִיל בְּגֶזֶל, רָבְצָה בְּגוּפָא עַל מָאנֵי וְתַבַּר לוֹן, וְלֵית מָאנֵי אֶלָּא תַּלְמִידֵי חֲכָמִים, וְכֵן הִזִּיק בְּרַגְלָיו, וְכֻלְּהוּ בְּמַתְנִיתִין אִתְּמַר, חֲמוֹר אִיהוּ חָמוּר בְּחוּמְרָא דְמַתְנִיתִין, וְתַלְמִיד חָכָם דְּשַׁלִּיט עֲלֵיהּ אִתְּמַר בֵּיהּ עָנִי וְרוֹכֵב עַל חֲמוֹר, וּמַאי נִיהוּ דְשַׁלִּיט עֲלֵיהּ, חָ כָם מ וּפְלָא וְ רַב רַ בָּנָן דָּא שַׁלִּיט עֲלֵיהּ, אֲבָל אָחֳרָא אִיהוּ מְחַמְּרָא בַּתְרֵיהּ בְּחוּמְרָא דְמַתְנִיתִין, וְכֵן שׁוֹר נָגַח לוֹן בְּקוּשְׁיָא, וְנַשִּׁיךְ לוֹן, וְרָבִיץ עֲלַיְיהוּ וְתַבַּר לוֹן, וְדָא אִיהוּ מַחֲלֹקֶת, וְכֵן בְּרֶגֶל תַּבַּר מָאנִין, וּבְגִין דָּא בְּשׁוֹר וּבַחֲמוֹר דְּאִינוּן מְמַנָּן דְּעִשָׂו וְיִשְׁמָעִאל, יֵתוּן רְכִיבִין עֲלַיְיהוּ תְּרֵין מְשִׁיחִין וְשָׁלְטִין עֲלַיְיהוּ, וּמָארֵי מַתְנִיתִין שָׁלְטִין עֲלַיְיהוּ, וַעֲלַיְיהוּ אָמַר יַעֲקֹב וַיְהִי לִי שׁוֹר וַחֲמוֹר דְּשַׁלִּיט עֲלַיְיהוּ, בְּתַלְמוּדָא וּבְמֶדְרָשִׁים, וּבִקְשִׁירוּ דִתְּפִלִּין וְצִיצִית שַׁלִּיט עֲלַיְיהוּ, דְּאִינוּן מוּעָדִים לְקַלְקֵל, דְּאִתְּמַר בְּהוֹן (שמות א יד) וַיְמָרְרוּ אֶת חַיֵּיהֶם בַּעֲבֹדָה קָשָׁה בְּחֹמֶר וּבִלְבֵנִים.</p>\n<p>מִיָּד נָפַק קָלָא וְאָמַר, אַנְחוּ לֵיהּ לַיְנוֹקָא וִיסַלֵּיק לְאַתְרֵיהּ, דְּהָא שִׁתִּין הֲלָכוֹת דְּאִינוּן שִׁשִּׁים הֵמָּה מְלָכוֹת תַּלְיָין בְּאַוִּירָא, וְאִיהוּ אָתֵי לְסָלְקָא לוֹן לְאַתְרַיְיהוּ, מִיָּד פָּרַח וְלָא חָזוּ מִדֵּי, אָמַר רַבִּי שִׁמְעוֹן וַדַּאי דָּא אִיהוּ תִּינוֹק יוֹנֵק מִשְּׁדֵי אִמּוֹ, וְדָא נַעַר, דְּאִיהוּ אַנְהִיג אַרְבִּין בְּיַמָּא, דְאִינוּן תַּלְמִידֵי חֲכָמִים דְּאָזְלִין בְּיַמָּא דְאוֹרַיְיתָא, בְּאַרְבַּע רוּחִין, דִּי בְהוֹן אִתְּמַר (יחזקאל לז ט) כֹּה אָמַר יהו\"ה מֵאַרְבַּע רוּחוֹת בֹּאִי הָרוּחַ, וְאִית אַרְבַּע רוּחִין אָחֳרָנִין מִסִּטְרָא דְשָׂטָן דְּאַתְיָין בְּקוּשְׁיָא וּמַחֲלוֹקֶת, וְטָבְעִין סְפִינוֹת דְּאִינוּן תַּלְמִידֵי חֲכָמִים בְּיַמָּא דְאוֹרַיְיתָא, וְלָא יָכְלִין לְנָפְקָא מִתַּמָּן, וְגַלְגַּלִּין סָלְקִין וְנָחֲתִין בְּהוֹן.</p>\n<p>אַדְהָכִי הָא יְנוֹקָא קָא נָחִית, פָּתַח וְאָמַר בּוֹצִינָא קַדִּישָׁא פְּתַח פִּיךָ בְּאוֹרַיְיתָא, דְהָא פִּימָךְ אִיהִי סִינַי, קָלִין וַהֲבָלִין דְּנָפְקִין מִפּוּמָךְ עֲלַיְיהוּ אִתְּמַר (שמות כ יח) וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת וְאֶת הַלַּפִּידִים וְגוֹמֵר, וְכֻלְּהוּ צַיְיתִין לְמִלּוּלָךְ עִלָּאִין וְתַתָּאִין, דְּאִינוּן שִׁתִּין רִבּוֹא דִמְתִיבְתָּא עִלָּאָה, וְשִׁתִּין רִבּוֹא דִמְתִיבְתָּא תַּתָּאָה, וְאַנְתְּ אִיהוּ בְּדִיּוֹקְנָא דְמָארָךְ, דִּבְזִמְנָא דְפָתַח בְּאָנֹכִי שׁוֹר לָא נָגַח אַרְיֵה לָא שָׁאַג עוֹף דְּאִיהוּ נִשְׁרָא לָא פָּרַח, וְכָל חֲיָילִין דְּתַלְיָין מִנַּיְיהוּ בְּכָרְסַיָּיא יְקָרָא, וְאָדָם לָשֶׁבֶת עַל כָּרְסַיָּיא דְאִיהוּ קוּדְשָׁא בְּרִיךְ הוּא, אִיהוּ צַיִּית לְמִלִּין דִּילָךְ, בְּגִין דְּמַטְרוֹנִיתָא דִילָהּ דְּאִיהִי אוֹרַיְיתָא קַדִּישָׁא סָלִיק בְּפוּמָךְ.</p>\n<p>(זהו תיקון ל\"א)</p>\n<p>מִיָּד פָּתַח וְאָמַר, בְּרֵאשִׁית, בָּרָא שִׁית, וְאִינוּן שִׁית יַמִּים בָּרָא אלהי\"ם מַאי אלהי\"ם יַמָּא שְׁבִיעָאָה, וְרָזָא דְמִלָּה (קהלת א ז) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם, וְהַיָּם אֵינֶנּוּ מָלֵא. עִלָּאִין שְׁמָעוּ, נוּנִין דְּרַחֲשִׁין בְּיַמָּא דְאוֹרַיְיתָא, עֲלָהּ אִתְּמַר (תהלים קד כה) שָׁם רֶמֶשׂ וְאֵין מִסְפָּר חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת, וְכֻלְּהוּ שָׁאֲגִין עַל טַרְפִין, וּשְׁכִינְתָּא אִתְּמַר בָּהּ (משלי לא ו) וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ, כָּל הַנְּחָלִים דְּאָזְלִין לְיַמָּא הָא שֶׁבַע אִינוּן, וְאִינוּן שֶׁבַע נְעָרוֹת</p>"],[9500011295,"<p>הָרְאוּיוֹת לָתֶת לָהּ לְאִימָּא קַדִּישָׁא דְאִיהִי בַּת שֶׁבַע, יָם אוֹקְיָנוֹס כְּלִילָא מִשֶּׁבַע יַמִּים, וְאַמַּאי אִתְקְרִיאַת אוֹקְיָינוֹס, בְּגִין דְּכָל מִינֵי מַיָּא וְנוּנִין וְרַחֲשִׁין דְּלַאו אִינוּן דִּילָהּ, וְיֵתוּן לְאַעָלָא בָּהּ, אִיהִי מֵקִיא לוֹן, וּמִתַּמָּן הֵם שָׁבִים לָלֶכֶת, כְּגַוְונָא דְתֵיבַת נֹחַ דְּלָא הֲוָה מְקַבְּלָא מִמִּינָא אַחֲרָא, אֶלָּא מֵאִלֵּין דְּמַנִּי קוּדְשָׁא בְּרִיךְ הוּא, וּבְגִין דָּא כָּל הַנְּחָלִים דְּאִינוּן תַּלְמִידֵי חֲכָמִים כֻּלְּהוּ מִשְׁתַּדְלֵי בְּאוֹרַיְיתָא הוֹלְכִים אֶל הַיָּם, וּבָעָאן לְאַעָלָא לִשְׁכִינְתָּא, וְאִיהִי לָא מְקַבְּלָא לוֹן בְּגַוָּוהּ, אֶלָּא לְאִלֵּין דְּמַנִּי קוּדְשָׁא בְּרִיךְ הוּא לְאַעָלָא לְגַבָּהּ (נ\"א בגווה), דְּאִינוּן שֶׁבַע רוֹעִים, וּלְשִׁבְטִין דְּנָפְקִין מִנַּיְיהוּ, וּלְכָל דְּאַתְיָין מִסִּטְרַיְיהוּ וְיִתְעָרְבוּן בְּהוֹן, יַמָּא קַבִּילַת לוֹן וְיִתְעָרְבוּן בְּגַוָּוהּ, אֲבָל לְאָחֳרָנִין לָא קַבִּילַת לוֹן, וּמִתַּמָּן אִינוּן שָׁבִין לָלֶכֶת.</p>\n<p>דְּוַדַּאי אִיהוּ ה' יַמָּא, נַחַל דִּילָהּ ו', כָּל אִינוּן דְּיָרְתִין נִשְׁמָתִין מִן יַמָּא וְנַחַל דִּילָהּ, בִּדְחִילוּ וּרְחִימוּ דְי\"ה, אִיהִי קַבִּילַת לוֹן, וְאָחֳרָנִין דְּלַאו אִינוּן חֵלֶק יהו\"ה אִיהִי לָא קַבִּילַת לוֹן, וְדַחְיָא לוֹן מִתַּמָּן, וּמִתַּמָּן הֵם שָׁבִים לָלֶכֶת. קָמוּ כֻּלְּהוּ וּבָרִיכוּ לֵיהּ, וְאָמְרוּ פִּימָא דִשְׁכִינְתָּא, סִינַי סִינַי, זַכָּאִין אוּדְנִין דְּשָׁמְעִין מִלִּין אִלֵּין מִפּוּמָךְ.</p>\n<p>אמר המגיה ע\"כ מצאתי, ואולי אלו הי\"א תקונים הם בכלל השבעים אלא שלא הושמו איש על ידו לדגליהם, וכבר מצאתי לקוטים אחרים, ולפי שלבי אמר לי שאינם מכלל התקונים רק מאמרים מפוזרים מספר הזהר, הבדלתי אותם לי למשמרת עד אשר אראה מה יהיו, ואם יהיה אלקים עמדי והנחני בדרך אמת עוד אוסיף להדפיס דברים יקרים ונוראים שלא נראו בגלוי עד היום הזה, וברוך י\"י אשר לא הסיר תפלתי וחסדו מאתי שגלגל זכות זה על ידי.</p>"]]});
